export type EmailTemplateVersionId = string;

/**
 * Structured key/value label attached to a message or a call. Use tags for low-cardinality filtering dimensions (category, experiment ID, template ID); they surface in the list filter of whatever carries them.
 *
 * On a message they also surface in the event log and in webhook payloads, and a message can carry `metadata` beside them for arbitrary per-send context that does not need to be filterable. A call has none of those three: its tags are set on the wire when the call is placed, and the call record is the one place you read them back.
 *
 * Whatever carries the tags defines how many it may have. Tag names are unique: a send that repeats one is rejected, and on a call the first instance of a name wins.
 *
 */
export type Tag = {
  /**
   * Tag name. ASCII letters, digits, underscore, and hyphen only. Case-sensitive. Maximum 32 characters.
   *
   */
  name: string;
  /**
   * Tag value. ASCII letters, digits, underscore, and hyphen only. Case-sensitive. Maximum 64 characters.
   *
   */
  value: string;
};

export type EmailAttachmentId = string;

/**
 * Attachment metadata returned on API reads. Download the file during its retention window with `GET /v1/email/messages/{message_id}/attachments/{attachment_id}`.
 *
 */
export type EmailAttachmentRef = {
  /**
   * Attachment ID, stable per email send.
   */
  readonly id?: EmailAttachmentId;
  /**
   * Filename as shown to the recipient.
   */
  filename: string;
  /**
   * Resolved MIME type at send time.
   */
  content_type?: string;
  /**
   * Decoded size in bytes.
   */
  size: number;
  /**
   * True when the attachment was sent inline via a `content_id` reference in the HTML body, false for regular file attachments.
   *
   */
  inline?: boolean;
  /**
   * The Content-ID set at send time, when the attachment was inline.
   */
  content_id?: string | null;
};

export type EmailMessage = {
  /**
   * Message ID.
   */
  readonly id: EmailId;
  /**
   * Sender address. `name` is present when a display name was provided on the send.
   */
  from: EmailAddress;
  /**
   * Primary recipients. Length is the recipient count. Use the broadcasts endpoint for audience-targeted sends. Each entry's `name` is present when a display name was provided on the send.
   */
  to: Array<EmailAddress>;
  /**
   * CC recipients.
   */
  cc?: Array<EmailAddress>;
  /**
   * BCC recipients.
   */
  bcc?: Array<EmailAddress>;
  /**
   * The subject line as delivered. For a send that used a template, the stored subject is the template's, so this reports it with the send's `parameters` substituted in, which is what the recipient saw.
   *
   */
  subject: string;
  category: EmailMessageCategory;
  /**
   * Reply-To addresses, if set on the send. Empty/null when no Reply-To was provided.
   */
  reply_to?: Array<EmailAddress> | null;
  readonly status: EmailMessageStatus;
  /**
   * How many recipients are in the `accepted` state, meaning we have the message and are getting ready to deliver it.
   */
  readonly accepted_count: number;
  /**
   * How many recipients the message has been prepared for and queued for delivery.
   */
  readonly processed_count: number;
  /**
   * How many recipients' messages were accepted by their mail server.
   */
  readonly delivered_count: number;
  /**
   * Number of recipients that resulted in a permanent delivery failure.
   */
  readonly bounced_count: number;
  /**
   * Number of recipients that reported spam.
   */
  readonly complained_count: number;
  /**
   * Number of recipients in transient delivery deferral. Their mail server asked for a retry, and delivery attempts continue.
   */
  readonly deferred_count: number;
  /**
   * Number of recipients rejected before delivery. Read the per-recipient `rejection_reason` field on `GET /v1/email/messages/{message_id}/recipients` for the specific cause.
   *
   */
  readonly rejected_count: number;
  /**
   * Time between the send being accepted and the message being prepared for delivery, in milliseconds, for the fastest recipient. Null until the first recipient reaches `processed`.
   *
   */
  readonly processing_latency_ms?: number | null;
  /**
   * Time between the message being processed and the receiving mail server accepting it, in milliseconds, for the fastest delivered recipient. Null until the first recipient is delivered.
   *
   */
  readonly delivery_latency_ms?: number | null;
  /**
   * End-to-end accept → delivered time for the fastest delivered recipient, in milliseconds. Null until the first recipient is delivered.
   *
   */
  readonly total_latency_ms?: number | null;
  /**
   * Total open events across all recipients.
   */
  readonly open_count: number;
  /**
   * Total click events across all recipients.
   */
  readonly click_count: number;
  /**
   * The template language this send asked for, in canonical form (`pt-BR` for a request of `pt-br`). Null when the send named no language (it took the template's default) or used no template at all. Compare it with `resolved_language`: when they differ, the language you asked for was not available and the template's `on_missing_language` policy chose the one shown there instead.
   *
   */
  readonly requested_language?: LanguageTag | null;
  /**
   * The template language this send was actually delivered in, in canonical form. Null when the send used no template. A non-null value with a null `requested_language` means the send named no language and took the template's default.
   *
   */
  readonly resolved_language?: LanguageTag | null;
  /**
   * The template this send rendered from, or null for a send that supplied its content inline.
   *
   */
  readonly template_id?: EmailTemplateId | null;
  /**
   * The exact template version this send rendered from, or null for an inline send. A template's live version changes every time you submit it, so this is what identifies the wording that was actually delivered, together with `resolved_language`.
   *
   */
  readonly template_version_id?: EmailTemplateVersionId | null;
  /**
   * Labels on this message, each one a `name` and a `value`, that you can filter and search messages by. Use tags for anything you want to find messages by later, and `metadata` for data you only want handed back to you.
   */
  tags?: Array<Tag>;
  /**
   * Any JSON you kept on the message. We store it and hand it back in webhook payloads, and that is all it does. If you want to search or filter by it, use `tags` instead.
   */
  metadata?: {
    [key: string]: unknown;
  };
  /**
   * The substitution values this send supplied, whether inline or from a template, or null if none were supplied. They are the values applied to `subject` and to the bodies the content endpoint returns, kept so you can see what produced the delivered copy and not only the result.
   *
   */
  readonly parameters?: {
    [key: string]: unknown;
  } | null;
  /**
   * Attachment metadata for the send. Empty when no attachments were included. Raw content is not echoed. When content storage is enabled, download an attachment by its `id` via the message's attachment endpoint.
   */
  attachments?: Array<EmailAttachmentRef>;
  /**
   * Whether open tracking is enabled for this send.
   */
  track_opens: boolean;
  /**
   * Whether click tracking is enabled for this send.
   */
  track_clicks: boolean;
  /**
   * When the send request was accepted.
   */
  readonly created_at: string;
  /**
   * Thread this message belongs to, or null when the message is not part of one.
   */
  readonly thread_id?: string | null;
  /**
   * The message this one is a reply to, if any.
   */
  readonly in_reply_to_message_id?: EmailId | null;
  /**
   * When all recipients reached a terminal delivered state, or null if not yet fully delivered.
   */
  readonly delivered_at?: string | null;
  /**
   * When this message is scheduled to send, for a send created with a future send time. Null for an immediate send. Stays set after the scheduled send fires.
   */
  readonly scheduled_at?: string | null;
};

export type EmailMessageList = {
  /**
   * Page of message objects.
   */
  data: Array<EmailMessage>;
} & ListEnvelope;

/**
 * A sender or recipient address. Accepts a plain email string (`jane@acme.com`), an RFC 5322 mailbox string with an embedded display name (`Jane Doe <jane@acme.com>`), or an object carrying the address and an optional display name. All forms can be mixed freely within one request. Responses always return the object form.
 *
 */
export type EmailAddressInput = string | EmailAddress;

/**
 * A template's slug: what you send it by, for example `welcome-email`. You choose it when you create the template, and it cannot be changed afterwards. It can contain lowercase letters, numbers, hyphens, and underscores, has to start and end with a letter or a number, and can be up to 63 characters long.
 *
 */
export type TemplateSlug = string;

export type EmailTemplateSend = unknown & {
  /**
   * The template to send, by its id.
   */
  id?: EmailTemplateId;
  /**
   * The template to send, by its slug handle. A workspace template (for example `welcome-email`) or a built-in `system` template (for example `bird_welcome`).
   */
  slug?: TemplateSlug;
  /**
   * Which of the template's languages to send. Omit it to send the template's default language, unless the template sets `language_source_required`, in which case a send naming no language is rejected. When the template does not have the language you ask for, its own `on_missing_language` setting decides whether the closest available language is sent instead or the send is rejected.
   *
   */
  language?: LanguageTag;
  /**
   * Values for the template's variables, keyed by the variable name. A variable name is a single word.
   *
   * Every variable in the template's `variables` list needs a value. A send
   * that omits one is rejected. Languages can use different variables, and a
   * value unused by the selected language is ignored.
   *
   * The API supplies values under the reserved `bird` key, so a send that sets
   * it is rejected. `parameters` is capped at 16 KB once serialized.
   *
   */
  parameters?: {
    [key: string]: unknown;
  };
};

/**
 * A file attached to an email. Put the base64-encoded bytes in `content` and the
 * recipient-facing name in `filename`. To show an image inline, set `content_id`
 * and reference it from the HTML body with `<img src="cid:..."/>`.
 *
 * The generated message is limited to 20 MB across the HTML body, text body,
 * attachments, and inline images after base64 and MIME encoding. Keep raw
 * attachment content at or below 15 MB to leave room for encoding and the body.
 *
 * Batch sends apply the same 20 MB limit to each message and to the full request
 * body. Executable and script content types are rejected.
 *
 */
export type EmailAttachment = {
  /**
   * The name the recipient sees on the attachment.
   */
  filename: string;
  /**
   * Base64-encoded file bytes. The encoded value and MIME wrapping count toward the 20 MB message limit.
   */
  content: string;
  /**
   * The file's MIME type. If omitted, the API infers it from the extension in `filename`. The API rejects executable and script types based on this value.
   */
  content_type?: string;
  /**
   * An RFC 2392 Content-ID for an inline file. Reference it from the HTML body with `<img src="cid:{content_id}"/>`. Omit it to send a downloadable attachment.
   */
  content_id?: string;
};

export type EmailMessageSendRequest = {
  /**
   * Sender address, as a plain email string, an RFC 5322 mailbox string (`Jane <jane@acme.com>`), or an object with an optional display name. Must be from a verified domain in this workspace.
   */
  from: EmailAddressInput;
  /**
   * Primary recipients. Each entry is a plain email string, an RFC 5322 mailbox string (`Jane <jane@acme.com>`), or an object with an optional display name.
   */
  to: Array<EmailAddressInput>;
  /**
   * CC recipients. Each entry is a plain email string, an RFC 5322 mailbox string (`Jane <jane@acme.com>`), or an object with an optional display name.
   */
  cc?: Array<EmailAddressInput>;
  /**
   * BCC recipients. Each entry is a plain email string, an RFC 5322 mailbox string (`Jane <jane@acme.com>`), or an object with an optional display name.
   */
  bcc?: Array<EmailAddressInput>;
  /**
   * Message subject line. Required for inline sends. Omit it when sending a `template` (the template supplies the subject).
   */
  subject?: string;
  /**
   * HTML body. At least one of html or text must be provided.
   */
  html?: string;
  /**
   * Plain-text body. At least one of html or text must be provided.
   */
  text?: string;
  /**
   * Reply-To addresses, each a plain email string, an RFC 5322 mailbox string, or an object with an optional display name. RFC 5322 allows multiple. Every recipient reply hits all listed addresses, so 1-2 is typical. The 25 cap exists to prevent header sizes that some receiving mail servers reject.
   *
   */
  reply_to?: Array<EmailAddressInput>;
  /**
   * Custom email headers as key-value pairs (for example `References`, `In-Reply-To`, or your own `X-*` headers). Reserved headers are rejected with a `422`. Set the message's addressing and subject through the dedicated fields: `from`, `to`, `cc`, `bcc`, `reply_to`, and `subject`. The API automatically generates `Content-Type`, `Content-Transfer-Encoding`, `DKIM-Signature`, `Received`, and `Return-Path`. You cannot override these generated headers. `List-Unsubscribe` and `List-Unsubscribe-Post` are honored as-is on `transactional` sends. Marketing sends receive a compliant unsubscribe header, so supplying either one is rejected with a `422`. Header values may not contain carriage-return or line-feed characters. Up to 25 headers per send, each value up to 998 characters.
   *
   */
  headers?: {
    [key: string]: string;
  };
  /**
   * Structured `{name, value}` labels for **filtering and analytics**. Tags become first-class query dimensions:
   *
   * - Filter the list endpoint by tag name.
   * - Slice analytics rollups by tag.
   * - Surface in webhook payloads.
   *
   * Cap: 20 tags per send. Use tags for low-cardinality dimensions (`category`, `experiment_variant`, `template_id`). For arbitrary structured context that you do not need as a filter dimension, use `metadata` instead.
   *
   */
  tags?: Array<Tag>;
  /**
   * Arbitrary JSON object returned on API reads and included in webhook payloads. You can query its paths in analytics, such as `metadata.order_id`, but it is not a dashboard filter. The serialized object is limited to 2 KB. Use metadata for per-send context such as order IDs, customer references, and structured event data. For low-cardinality filterable labels, use `tags` instead.
   *
   */
  metadata?: {
    [key: string]: unknown;
  };
  /**
   * Parameter values used to personalize inline content. A parameter is a single word, and a token in the subject or body (for example `{{ animal }}`) is replaced with the value of that name at send time. Shared across all recipients of this send. A token with no matching key renders empty. Cap: 16 KB serialized. When sending a stored `template`, put the values in `template.parameters` instead.
   *
   */
  parameters?: {
    [key: string]: unknown;
  };
  /**
   * Send a stored template instead of inline content. When set, omit `subject`, `html` and `text`, because the template supplies them. Personalize with `template.parameters`. A template send goes out immediately: `template` and `scheduled_at` are mutually exclusive, and combining them is rejected with a `422`.
   *
   */
  template?: EmailTemplateSend;
  /**
   * Whether to track open events for this message.
   */
  track_opens?: boolean;
  /**
   * Whether to track click events for this message.
   */
  track_clicks?: boolean;
  /**
   * ID of the IP pool to send from (`ipp_` prefix), or `ipp_shared` to route through the shared pool explicitly. Omit to use your organization's default pool. An unknown pool, or a pool with no dedicated IPs available to send from, is rejected with a `422`.
   *
   */
  ip_pool_id?: string;
  /**
   * Content classification, which controls suppression policy:
   *
   * - `marketing`: Blocks on all suppression reasons.
   * - `transactional`: Allows delivery through complaint and unsubscribe suppressions, for receipts, password resets, and similar operational mail.
   *
   * When you send with `template` and omit this field, the message takes the template's own classification, so a template created as `transactional` sends as transactional. Set this field to classify a single send differently from its template. It always takes precedence. A send with no template and no category defaults to `marketing`.
   *
   */
  category?: EmailMessageCategory;
  /**
   * Files to attach, up to 20 per message. A message can be at most 20 MB once it has been generated, and we refuse a send that would go over. That figure covers the HTML body, the text body and every attachment and inline image, all measured after base64 encoding, which adds roughly a third. So 15 MB of raw files already accounts for most of the budget, and the body competes for the same space. A batch send is held to the same 20 MB per message, and the whole request body is capped at 20 MB as well.
   *
   */
  attachments?: Array<EmailAttachment>;
  /**
   * Schedule the message to send at a future time instead of immediately. Must be at least 30 seconds and at most 30 days ahead. Outside that range the request is rejected with `422`. The message returns with status `accepted` and shows as `scheduled` on reads until it sends. Cancel it before then with the message cancel endpoint. Scheduled sends count against your plan's monthly scheduled-email allowance. Exceeding it is rejected with a `422`. A scheduled message has inline content: `scheduled_at` and `template` are mutually exclusive, and combining them is rejected with a `422`. This field is accepted only on a single send. Batch items reject it.
   *
   */
  scheduled_at?: string;
};

/**
 * Batch of email message send requests. All items are validated before any are queued. Attachments are allowed on individual messages. Each message must stay within the 20 MB estimated generated message-size cap. The serialized JSON request body for the batch has a hard 20 MB cap.
 *
 */
export type EmailMessageBatchRequest = Array<EmailMessageSendRequest>;

export type EmailMessageBatchItem = {
  /**
   * Message ID assigned to this batch item.
   */
  readonly id: EmailId;
  /**
   * Initial status of this message in the batch.
   */
  readonly status: "accepted";
  /**
   * Resolved category for this batch item.
   */
  category: "marketing" | "transactional";
  /**
   * The template language this item asked for, in canonical form. Null when the item named no language or used no template. Every item in a batch resolves its own template reference, so this and `resolved_language` can differ from item to item.
   *
   */
  readonly requested_language?: LanguageTag | null;
  /**
   * The template language this item was actually delivered in, in canonical form. Null when the item used no template. A value here differing from `requested_language` means the template did not have the language asked for and its `on_missing_language` policy chose this one.
   *
   */
  readonly resolved_language?: LanguageTag | null;
  /**
   * The template this item rendered from, or null for an item that supplied its content inline.
   *
   */
  readonly template_id?: EmailTemplateId | null;
  /**
   * The exact template version this item rendered from, or null for an inline item. Record it if you need to reproduce what was sent: a template's live version changes every time you submit it.
   *
   */
  readonly template_version_id?: EmailTemplateVersionId | null;
};

export type EmailMessageBatchResponse = {
  /**
   * One entry per message in the batch, in submission order.
   */
  data: Array<EmailMessageBatchItem>;
};

export type RecipientId = string;

/**
 * Envelope position of a recipient on an outbound email event.
 */
export type RecipientRole = "to" | "cc" | "bcc";

export type EmailRecipient = {
  /**
   * Recipient ID.
   */
  readonly id: RecipientId;
  /**
   * ID of the message or broadcast this recipient belongs to. For a message send, this is the message's `em_`-prefixed ID. For a broadcast, this field is also `em_`-prefixed, but currently does not resolve to a retrievable message.
   */
  parent_id: string;
  /**
   * How this recipient appeared in the send request.
   */
  role: RecipientRole;
  /**
   * Recipient email address.
   */
  recipient: string;
  /**
   * Display name provided for this recipient on the send, or null if none was given.
   */
  name?: string | null;
  /**
   * Delivery status for this recipient:
   *
   * - `accepted`: The send has been taken and is being prepared for delivery.
   * - `processed`: This recipient's message is on its way out.
   * - `deferred`: The recipient's mailbox provider asked for a retry, and delivery attempts continue.
   * - `delivered`: The recipient's mail server accepted the message.
   * - `bounced`: Delivery permanently failed (see `bounce_type` for hard vs soft).
   * - `complained`: The recipient reported the message as spam.
   * - `rejected`: Delivery was never attempted (see `rejection_reason` for why).
   *
   */
  readonly status:
    | "accepted"
    | "processed"
    | "deferred"
    | "delivered"
    | "bounced"
    | "complained"
    | "rejected";
  /**
   * Present on `status: rejected` rows. Specifies why the recipient was rejected:
   *
   * - `recipient_suppressed`: The recipient is on the workspace suppression list, so
   * delivery was never attempted.
   * - `transmission_failed`: The message could not be transmitted for delivery.
   * - `generation_failure`: The message could not be built for delivery (template or
   * content issue).
   * - `policy_rejection`: The message was refused by sending policy.
   * - `domain_unverified`: The sending domain was not verified.
   * - `quota_exceeded`: The organization's send quota was reached.
   * - `recipient_not_allowed`: A recipient was not permitted for this send (for shared
   * onboarding-domain sends, recipients must be verified workspace members).
   *
   */
  readonly rejection_reason?:
    | "recipient_suppressed"
    | "transmission_failed"
    | "generation_failure"
    | "policy_rejection"
    | "domain_unverified"
    | "quota_exceeded"
    | "recipient_not_allowed"
    | null;
  /**
   * Bounce classification for `bounced` and `deferred` rows, or null when the recipient
   * has not bounced or the receiving server's response has not been classified.
   *
   * - `hard`: a permanent failure (invalid address or non-existent domain).
   * - `soft`: a transient failure (mailbox full or server temporarily unavailable).
   * - `block`: the receiving mail server blocked the sending IP for reputation reasons.
   * - `admin`: an administrative refusal (relaying denied or blocklisted domain).
   * - `undetermined`: the receiving server's response is ambiguous.
   *
   */
  readonly bounce_type?:
    "hard" | "soft" | "undetermined" | "admin" | "block" | null;
  /**
   * SMTP reply code returned by the receiving mail server for `bounced` and `deferred` rows, or null when none was provided.
   */
  readonly bounce_code?: string | null;
  /**
   * Human-readable reason the receiving mail server gave for the bounce or deferral, or null when none was provided.
   */
  readonly bounce_description?: string | null;
  /**
   * When the message was prepared and queued for delivery to the recipient's mail server, or null if that has not happened yet.
   */
  readonly processed_at?: string | null;
  /**
   * When the recipient's mail server accepted the message, or null if not yet delivered.
   */
  readonly delivered_at?: string | null;
  /**
   * Time between the send being accepted and the message being prepared for delivery, in milliseconds. Null until processed.
   */
  readonly processing_latency_ms?: number | null;
  /**
   * Time between the message being prepared and the receiving mail server accepting it, in milliseconds. Null until delivered.
   */
  readonly delivery_latency_ms?: number | null;
  /**
   * End-to-end accept → delivered time for this recipient, in milliseconds. Null until delivered.
   */
  readonly total_latency_ms?: number | null;
  /**
   * Number of open events for this recipient.
   */
  readonly open_count: number;
  /**
   * Number of click events for this recipient.
   */
  readonly click_count: number;
};

export type EmailRecipientList = {
  /**
   * Page of recipient objects for this email send.
   */
  data: Array<EmailRecipient>;
  /**
   * What to do next, given what this page reports. Present only where the read computes it: an
   * empty list means the answer you were looking for is here and there is nothing further to
   * do. Absent entirely on reads that do not report next actions.
   *
   */
  readonly next?: Array<NextAction>;
} & ListEnvelope;

/**
 * Type of an event in a message's per-recipient delivery timeline.
 *
 * - `email.scheduled`: We accepted a send scheduled for a future time. Fires once for each message regardless of its recipient count.
 * - `email.accepted`: We accepted the send and are getting ready to deliver it. Fires once per requested recipient.
 * - `email.processed`: We queued the message for delivery to the recipient's mail server.
 * - `email.deferred`: The recipient's mail server temporarily refused the message. Delivery remains pending and is retried. Can fire more than once per recipient.
 * - `email.delivered`: The recipient's mail server accepted the message.
 * - `email.bounced`: Delivery permanently failed at the recipient's mail server.
 * - `email.out_of_band_bounce`: A bounce notification arrived after the message had already been accepted for delivery.
 * - `email.rejected`: We rejected the message before attempting delivery, for example because the recipient is suppressed.
 * - `email.canceled`: A scheduled send was canceled before it fired. Fires once for each message regardless of its recipient count.
 * - `email.opened`: The recipient opened the message. Can fire more than once per recipient.
 * - `email.clicked`: The recipient clicked a tracked link in the message. Can fire more than once per recipient.
 * - `email.unsubscribed`: The recipient opted out through a tracked unsubscribe link in the message.
 * - `email.list_unsubscribed`: The recipient opted out through the one-click unsubscribe control in their mail client.
 * - `email.complained`: The recipient reported the message as spam through their mailbox provider.
 *
 * We can add new event types to this list over time, so treat a value you do not recognize as a new type rather than as an error.
 *
 */
export type EmailEventType =
  | "email.accepted"
  | "email.bounced"
  | "email.canceled"
  | "email.clicked"
  | "email.complained"
  | "email.deferred"
  | "email.delivered"
  | "email.list_unsubscribed"
  | "email.opened"
  | "email.out_of_band_bounce"
  | "email.processed"
  | "email.rejected"
  | "email.scheduled"
  | "email.unsubscribed"
  | (string & {});

export type EmailEvent = {
  /**
   * Event ID.
   */
  readonly id: string;
  /**
   * The event's type. `email.processed`, for example, means the message has been processed and queued for delivery.
   *
   */
  type: EmailEventType;
  /**
   * When this event occurred.
   */
  occurred_at: string;
  /**
   * Recipient this event applies to.
   */
  recipient_id: RecipientId;
  /**
   * Bounce classification. Present on `email.bounced`, `email.out_of_band_bounce`, and
   * `email.deferred` events.
   *
   * - `hard`: a permanent failure (invalid address or non-existent domain).
   * - `soft`: a transient failure (mailbox full or server temporarily unavailable).
   * - `block`: the receiving mail server blocked the sending IP for reputation reasons.
   * - `admin`: an administrative refusal (relaying denied or blocklisted domain).
   * - `undetermined`: the receiving server's response is ambiguous.
   *
   */
  bounce_type?: "hard" | "soft" | "undetermined" | "admin" | "block" | null;
  /**
   * A more detailed numeric bounce code, useful for telling apart failures that share the same `bounce_type`. For example, a DNS failure and a spam block can both come through as `bounce_type: soft` or `bounce_type: block`; this field tells you which one actually happened. Present on `email.bounced`, `email.out_of_band_bounce`, and `email.deferred` events.
   *
   */
  bounce_class?: number | null;
  /**
   * SMTP status code returned by the receiving mail server. Present on `email.bounced` and `email.deferred` events.
   *
   */
  bounce_code?: string | null;
  /**
   * The bounce reason, in plain language, as reported by the mail server. Present on `email.bounced` and `email.deferred` events.
   */
  bounce_description?: string | null;
  /**
   * Specific cause of rejection. Present on `email.rejected` events only.
   *
   * - `recipient_suppressed`: The recipient is on the workspace suppression list.
   * - `transmission_failed`: The message could not be transmitted for delivery.
   * - `generation_failure`: The message could not be built for delivery, because of a template or content issue.
   * - `policy_rejection`: The message was refused by sending policy.
   * - `domain_unverified`: The sending domain was not verified.
   * - `quota_exceeded`: The organization's send quota was reached.
   * - `recipient_not_allowed`: This recipient was not allowed for this send. For a send from the shared onboarding domain, every recipient has to be a verified member of the workspace.
   *
   */
  rejection_reason?:
    | "recipient_suppressed"
    | "transmission_failed"
    | "generation_failure"
    | "policy_rejection"
    | "domain_unverified"
    | "quota_exceeded"
    | "recipient_not_allowed"
    | null;
  /**
   * The IP address used to send this message. Useful for spotting a deliverability problem that is tied to one specific sending IP rather than affecting all of them. Present on `email.delivered`, `email.bounced`, `email.out_of_band_bounce`, and `email.deferred` events.
   *
   */
  sending_ip?: string | null;
  /**
   * The recipient mailbox provider, as a lowercased classifier bucket (e.g. `gmail`, `yahoo`, `microsoft`, `apple`). Present on `email.processed`, `email.delivered`, `email.complained`, `email.bounced`, `email.out_of_band_bounce`, `email.deferred`, `email.rejected`, `email.unsubscribed`, `email.list_unsubscribed`, `email.opened`, and `email.clicked` events when the receiving mail system could be classified; null when it could not.
   *
   */
  mailbox_provider?: string | null;
  /**
   * The provider region, as reported by the receiving mail system (for example `NA`, `EU`, `APAC`). The set is open and provider-specific. Present on `email.processed`, `email.delivered`, `email.complained`, `email.bounced`, `email.out_of_band_bounce`, `email.deferred`, `email.rejected`, `email.unsubscribed`, `email.list_unsubscribed`, `email.opened`, and `email.clicked` events when reported; null otherwise.
   *
   */
  mailbox_provider_region?: string | null;
  /**
   * True when the open was auto-fetched by an inbox privacy feature (Apple Mail Privacy Protection, the Gmail image proxy) rather than a person actually opening the message. Use it to calculate open rate accurately. Present on `email.opened` events only.
   *
   */
  is_prefetched?: boolean | null;
  /**
   * The clicked URL. Present on `email.clicked` events, and on `email.unsubscribed` events when the recipient unsubscribed through a link in the message.
   */
  url?: string | null;
  /**
   * The clicked link's own name, when the link in the message carried one, so a click can be reported by what the link said rather than where it pointed. Absent when the link had no name. Appears alongside `url` on `email.clicked` events, and on `email.unsubscribed` events when the recipient unsubscribed through a link.
   */
  link_name?: string | null;
  /**
   * ISO 3166-1 alpha-2 country code derived from the client IP. Present on `email.opened` and `email.clicked` events when available.
   */
  country?: string | null;
  /**
   * Client IP address (IPv4 or IPv6). Present on `email.opened` and `email.clicked` events when available.
   */
  ip_address?: string | null;
  /**
   * Client user-agent string. Present on `email.opened` and `email.clicked` events when available.
   */
  user_agent?: string | null;
};

export type EmailEventList = {
  /**
   * Page of timeline events for this email send, in chronological order.
   */
  data: Array<EmailEvent>;
  /**
   * What to do next, given what this page reports. Present only where the read computes it: an
   * empty list means the answer you were looking for is here and there is nothing further to
   * do. Absent entirely on reads that do not report next actions.
   *
   */
  readonly next?: Array<NextAction>;
} & ListEnvelope;

/**
 * The body content of a sent email message, as delivered. A send that used a template stores the template's body, so these report it with the send's `parameters` substituted in.
 *
 */
export type EmailMessageContent = {
  /**
   * The HTML body of the message as delivered, if it was stored.
   */
  html?: string;
  /**
   * The plain-text body of the message as delivered, if it was stored.
   */
  text?: string;
};

export type AudienceId = string;

/**
 * Which identifier a contact has on file, `email` for an email address or `phone_number` for a phone number.
 */
export type ContactIdentifierFilter = "email" | "phone_number";

export type ContactId = string;

/**
 * A compact reference to an audience, carrying its ID and display name.
 */
export type AudienceRef = {
  /**
   * ID of the referenced audience.
   */
  readonly id: AudienceId;
  /**
   * The audience's display name.
   */
  name: string;
};

export type Contact = {
  /**
   * ID of the contact, accepted by every operation that takes a `contact_id`.
   */
  readonly id: ContactId;
  /**
   * The contact's email address, in its stored form, trimmed and lowercased before uniqueness is checked. Unique within the workspace. `null` when the contact has no email address.
   */
  email: string | null;
  /**
   * The contact's phone number in normalized international form: a leading `+` and four to 15 digits. We normalize formatting but do not verify the number against numbering-plan metadata. The number is unique within the workspace. Because carriers recycle disconnected numbers, use `external_id` as the durable key for your own records. `null` when the contact has no phone number.
   */
  phone_number: string | null;
  /**
   * The contact's first name. Available in broadcast templates as `bird.contact.first_name`.
   */
  first_name?: string | null;
  /**
   * The contact's last name. Available in broadcast templates as `bird.contact.last_name`.
   */
  last_name?: string | null;
  /**
   * Your own identifier for this contact, such as a user ID in your system. Unique within the workspace when set.
   */
  external_id?: string | null;
  /**
   * Custom property values for this contact, available in broadcast templates as `bird.contact.<key>`. Each key is a property created via the contact properties API, and each value is a string, number, boolean, or RFC 3339 datetime matching the property's declared type (strings up to `500` characters). Total size is capped at 2 KB serialized. Values stored under a property that was later archived remain readable here.
   *
   */
  data?: {
    [key: string]: unknown;
  };
  /**
   * The audiences this contact belongs to, most-recently-joined first. Only present when listing contacts; omitted from every other contact operation.
   */
  readonly audiences?: Array<AudienceRef>;
} & Timestamps;

export type ContactList = {
  /**
   * Page of contact objects.
   */
  data: Array<Contact>;
} & ListEnvelopeWithTotal;

export type ContactCreateRequest = {
  /**
   * The contact's email address. Trimmed and lowercased before it is stored and checked for uniqueness. Unique within the workspace. Supply an email address, a phone number, or both.
   */
  email?: string;
  /**
   * The contact's phone number in E.164 format, including the leading `+` and country code. Spaces and punctuation are accepted and stripped; the number is stored in its canonical form, which may differ from what you send, and is unique within the workspace. An empty string is treated as if the field were omitted. Supply an email address, a phone number, or both.
   */
  phone_number?: string;
  /**
   * The contact's first name.
   */
  first_name?: string;
  /**
   * The contact's last name.
   */
  last_name?: string;
  /**
   * Your own identifier for this contact, such as a user ID in your system. Unique within the workspace when set.
   */
  external_id?: string;
  /**
   * Custom property values for this contact. Each key must be an active contact property. Each value must match the property's declared type: string, number, boolean, or RFC 3339 datetime. Strings can contain up to `500` characters, and a `null` value is ignored. Unregistered or archived keys return a validation error. The serialized data is limited to 2 KB.
   */
  data?: {
    [key: string]: unknown;
  };
};

/**
 * A contact identifier a batch entry can be matched on.
 */
export type ContactMatchKey = "email" | "phone_number" | "external_id";

export type ContactUpsertRequest = {
  /**
   * Contacts to create or update, matched automatically against every identifier an entry supplies. Existing contacts are updated with the fields each entry supplies; omitted fields keep their stored values, so an entry can set fields but never clear them. Unmatched entries create contacts.
   */
  contacts: Array<ContactCreateRequest>;
  /**
   * Audiences every contact in this request is added to. Contacts that are already members are left in place. Every listed audience must exist, or the whole request fails with a validation error and nothing is written.
   */
  audience_ids?: Array<AudienceId>;
  /**
   * Optional field used to match every entry to an existing contact. Every entry must include this field when set. When omitted, each entry is matched against all identifiers it supplies. No match creates a contact, one match updates it, and identifiers that match multiple contacts return an error naming each contact.
   */
  match_on?: ContactMatchKey;
  /**
   * How a supplied `data` object is applied to an existing contact. The default `merge` mode adds the supplied keys to the contact's stored custom values. A key with a `null` value deletes that key. The `replace` mode overwrites the whole stored `data` map with the supplied map. In both modes a contact that omits `data` keeps its stored values unchanged, so an import that touches one attribute never wipes the others.
   *
   */
  data_mode?: "merge" | "replace";
};

/**
 * The identifiers a batch entry supplied, in the normalized form used for matching. A field is `null` when the entry did not include it. These values identify the request entry and do not represent the contact's current state.
 */
export type ContactUpsertEntry = {
  /**
   * Email address this entry carried, trimmed and lowercased. `null` when the entry carried none.
   */
  email: string | null;
  /**
   * Phone number this entry carried, in its normalized international form. `null` when the entry carried none. A row rejected for an invalid phone echoes the value as sent, trimmed, since no normalized form exists.
   */
  phone_number: string | null;
  /**
   * Your own identifier for this entry, when the entry supplied one.
   */
  external_id: string | null;
};

/**
 * Which identifier matched a batch entry to an existing contact. `null` when the entry created a new contact.
 */
export type ContactMatchedOn = "email" | "phone_number" | "external_id" | null;

export type ContactUpsertError = {
  /**
   * Machine-readable error category for this entry, such as `validation_error` or `conflict_error`, in the same vocabulary as the top-level error `type`. New categories may be added over time, so treat unrecognized values as a generic failure.
   */
  type: string;
  /**
   * Specific error code for this entry, from the same catalog as the top-level error `code`. `E04058` means the entry matched two contacts and requires review. `E04055` means the phone number belongs to another contact and you must retry with different data. Both are `conflict_error` errors; the code distinguishes them.
   */
  code: string;
  /**
   * Human-readable explanation of why this entry failed.
   */
  message: string;
};

export type ContactUpsertResultItem = {
  entry: ContactUpsertEntry;
  /**
   * Which identifier matched this entry to an existing contact. `null` when the entry created a new contact.
   */
  matched_on: ContactMatchedOn;
  /**
   * What happened to this contact.
   *
   * - `created`: a new contact was created for the address.
   * - `updated`: an existing contact with the address was updated.
   * - `failed`: the entry was rejected and `error` explains why. A failed entry
   * does not affect the other entries in the request.
   *
   */
  status: "created" | "updated" | "failed";
  /**
   * ID of the created or updated contact. Absent when the entry failed.
   */
  contact_id?: ContactId;
  /**
   * Why this entry failed. Absent for successful entries.
   */
  error?: ContactUpsertError;
};

export type ContactUpsertResult = {
  /**
   * One entry per contact in the request, in submission order.
   */
  data: Array<ContactUpsertResultItem>;
};

export type ContactUpdateRequest = {
  /**
   * New email address for the contact. Trimmed and lowercased before it is stored and checked for uniqueness. Must not be in use by another contact in the workspace. Omit to keep the current address; set to `null` to remove it, as long as the contact keeps at least one identifier.
   */
  email?: string | null;
  /**
   * New phone number for the contact, in E.164 format with the leading `+` and country code. Spaces and punctuation are accepted and stripped. Stored in its canonical form, which may differ from what you send, and unique within the workspace. Omit to keep the current number; set to `null` to remove it, as long as the contact keeps at least one identifier. An empty string behaves as `null`.
   */
  phone_number?: string | null;
  /**
   * The contact's first name. Set to `null` to clear.
   */
  first_name?: string | null;
  /**
   * The contact's last name. Set to `null` to clear.
   */
  last_name?: string | null;
  /**
   * Your own identifier for this contact. Unique within the workspace when set. Set to `null` to clear.
   */
  external_id?: string | null;
  /**
   * Custom property values to merge into the contact's existing data. Supplied keys are set, keys with a `null` value are removed, and omitted keys remain unchanged. Each key must be an active contact property. Each value must match the property's declared type: string, number, boolean, or RFC 3339 datetime. Strings can contain up to `500` characters. An unregistered or archived key returns a validation error. The serialized result is limited to 2 KB.
   */
  data?: {
    [key: string]: unknown;
  };
};

export type Audience = {
  /**
   * ID of the audience, accepted by every operation that takes an `audience_id`.
   */
  readonly id: AudienceId;
  /**
   * Display name for the audience.
   */
  name: string;
  /**
   * Longer description of who this audience is.
   */
  description?: string | null;
  /**
   * How the audience's recipients are determined. `static` is an explicit member list you manage by adding and removing contacts.
   */
  type: "static";
} & Timestamps;

export type AudienceList = {
  /**
   * Page of audience objects.
   */
  data: Array<Audience>;
} & ListEnvelope;

export type PreferenceId = string;

/**
 * The channel a preference statement applies to. A preference addresses one channel: the handle that identifies the person differs per channel, so opting out of one channel says nothing about the others. New channels can be added over time, so a value outside this list can be returned.
 */
export type PreferenceChannel = "email" | "sms" | "whatsapp" | (string & {});

/**
 * What the statement says: `granted` records consent to receive messages, `revoked` records an opt-out. There is no third state: a person who never stated anything simply has no preference on record.
 */
export type PreferenceStatus = "granted" | "revoked";

/**
 * How much traffic the statement covers. `non_transactional` covers marketing and other non-essential messages while transactional messages such as receipts and verification codes keep flowing; `all` covers every message including transactional ones.
 */
export type PreferenceCoverage = "all" | "non_transactional";

/**
 * How the statement was made. Statements the person made themselves (`unsubscribe_link`, `unsubscribe_event`, `keyword`, `preference_page`) carry more weight than ones asserted on their behalf (`api_key`, `user`, `import`): a person's own opt-out cannot be overridden or deleted through this API. New origins can be added over time, so a value outside this list can be returned.
 */
export type PreferenceOrigin =
  | "unsubscribe_link"
  | "unsubscribe_event"
  | "keyword"
  | "preference_page"
  | "api_key"
  | "user"
  | "import"
  | (string & {});

/**
 * One person's current stated preference for one channel: whether they have consented to or opted out of receiving messages at a handle, and how much traffic the statement covers. A key holds one current statement (a newer statement replaces it, an older one is refused), and the full history behind the current state is kept internally. `sender_scope` and `topic_id` are part of the key: a preference with both null applies channel-wide.
 *
 */
export type Preference = {
  readonly id: PreferenceId;
  readonly channel: PreferenceChannel;
  /**
   * Who the statement is about: an email address on the email channel, a phone number in E.164 format on SMS and WhatsApp.
   */
  readonly handle: string;
  /**
   * The sender the statement is limited to, or null when it covers the whole channel. On SMS this is the originator the person replied to; on WhatsApp it identifies the business account that messaged them. Email preferences are always channel-wide, so it is always null there.
   */
  readonly sender_scope: string | null;
  /**
   * The topic the statement is limited to, or null when it covers every topic. Part of the key that identifies a statement, alongside `sender_scope`.
   */
  readonly topic_id: string | null;
  readonly status: PreferenceStatus;
  readonly coverage: PreferenceCoverage;
  /**
   * When the statement was made, as reported by whoever made it. This is what orders one key's statements: a write dated before this moment is refused rather than applied.
   */
  readonly effective_at: string;
  readonly origin: PreferenceOrigin;
  /**
   * Free-form note on where the statement came from, as supplied when it was recorded: a form name, an import batch, a campaign. Null when none was given.
   */
  readonly source?: string | null;
  /**
   * When the person consented, as evidenced by whoever asserted the grant. Null on statements that carry no consent evidence, including every opt-out.
   */
  readonly consented_at?: string | null;
  /**
   * The contact whose handle matched when the statement was recorded. Null when no contact matched at that moment; it is not updated when contacts change later.
   */
  readonly contact_id?: ContactId | null;
} & Timestamps;

export type PreferenceList = {
  /**
   * Page of preferences, most recently created first.
   */
  data: Array<Preference>;
} & ListEnvelope;

export type PreferenceStatement = {
  channel: PreferenceChannel;
  status: PreferenceStatus;
  /**
   * How much traffic the statement covers. Defaults to `non_transactional`, which keeps transactional messages such as receipts and verification codes flowing.
   */
  coverage?: PreferenceCoverage;
  /**
   * Limit the statement to one sender instead of the whole channel. On SMS this is the originator; on WhatsApp it identifies the business account. Not supported on email, where preferences are always channel-wide.
   */
  sender_scope?: string;
  /**
   * Free-form note on where the statement came from: a form name, an import batch, a campaign. Stored verbatim and returned on the preference.
   */
  source?: string;
  /**
   * When the person consented, on a `granted` statement. Required evidence when granting over a stored opt-out: the grant applies only if this is later than the opt-out it reverses. May not be in the future.
   */
  consented_at?: string;
};

/**
 * Records one preference statement for a handle. Writing is an upsert by key (channel, handle, sender scope, and topic), and statements are causally ordered: a statement dated older than the key's current one is refused and returned with `applied: false` rather than applied out of order.
 *
 */
export type PreferenceCreate = {
  /**
   * Who the statement is about: an email address on the email channel, a phone number in E.164 format on SMS and WhatsApp.
   */
  handle: string;
} & PreferenceStatement;

export type PreferenceTransitionId = string;

/**
 * The outcome of one preference write or delete. `applied: true` means the request took effect: either it changed the record, or an identical statement already had. `applied: false` means it was refused as older than the key's current statement; `preference` then carries the statement that survived, and `transition_id` identifies the refusal on the key's record.
 *
 */
export type PreferenceWriteResult = {
  /**
   * Whether the request took effect. False only when it was refused as out of order; the surviving, newer statement is returned in `preference`.
   */
  readonly applied: boolean;
  /**
   * Identifies this write on the key's record, for applied and refused requests alike. Null when the write was a repeat of the current statement and recorded nothing new.
   */
  readonly transition_id: PreferenceTransitionId | null;
  /**
   * The key's surviving statement. Null after an applied delete, when the key is back to having no record.
   */
  readonly preference: Preference | null;
};

export type ContactPropertyId = string;

/**
 * The value type every contact must use for a property. Cannot be changed after creation.
 *
 * `datetime` values are RFC 3339 timestamps with an explicit offset. Examples include `2024-01-15T09:30:00Z` and `2024-01-15T11:30:00+02:00`. A bare date or a time with no offset is rejected. The value is normalized to UTC with second precision on write, so `2024-01-15T11:30:00+02:00` is stored and returned as `2024-01-15T09:30:00Z`, and any fractional seconds are dropped.
 *
 */
export type ContactPropertyType = "string" | "number" | "boolean" | "datetime";

export type ContactProperty = {
  /**
   * ID of the property, accepted by every operation that takes a `property_id`.
   */
  readonly id: ContactPropertyId;
  /**
   * The property key, used as the key in contact data and as the attribute in the `bird.contact.<key>` broadcast template variable. Lowercase letters, digits, and underscores, starting with a letter. Cannot be changed after creation.
   */
  key: string;
  type: ContactPropertyType;
  /**
   * Default used when a contact has no value for this property and the template does not supply an inline fallback. A string, number, boolean, or RFC 3339 datetime matching the declared type (strings up to `500` characters), or `null` when no fallback is set.
   */
  fallback_value?: unknown;
  /**
   * Whether the property is archived. An archived property is rejected in new contact writes and stops rendering in templates, but every value already stored on contacts is preserved. Reactivate it with unarchive.
   */
  readonly archived?: boolean;
} & Timestamps;

export type ContactPropertyList = {
  /**
   * Page of contact property objects.
   */
  data: Array<ContactProperty>;
} & ListEnvelope;

export type ContactPropertyCreateRequest = {
  /**
   * The property key, used as the key in contact data and as the attribute in the `bird.contact.<key>` broadcast template variable. Lowercase letters, digits, and underscores, starting with a letter. Cannot be changed after creation.
   */
  key: string;
  type: ContactPropertyType;
  /**
   * Default used when a contact has no value for this property and the template does not supply an inline fallback. A string, number, boolean, or RFC 3339 datetime matching the declared type (strings up to `500` characters), or `null` for no fallback; a value of another type returns a validation error.
   */
  fallback_value?: unknown;
};

export type ContactPropertyUpdateRequest = {
  /**
   * Default used when a contact has no value for this property and the template does not supply an inline fallback. A string, number, boolean, or RFC 3339 datetime matching the declared type (strings up to `500` characters); a value of another type returns a validation error. Set to `null` to remove the fallback.
   */
  fallback_value?: unknown;
};

export type AudienceCreateRequest = {
  /**
   * Display name for the audience.
   */
  name: string;
  /**
   * Longer description of who this audience is.
   */
  description?: string;
  /**
   * How the audience's recipients are determined. `static` is an explicit member list you manage by adding and removing contacts.
   */
  type?: "static";
};

export type AudienceUpdateRequest = {
  /**
   * New display name for the audience. Omit to keep the current name. The name cannot be cleared, and a whitespace-only value returns a validation error.
   */
  name?: string;
  /**
   * Longer description of who this audience is. Set to null to clear.
   */
  description?: string | null;
};

export type AudienceMember = {
  contact: Contact;
  /**
   * When this contact joined the audience. Members are listed in join order, most recent first.
   */
  readonly joined_at: string;
  /**
   * The audiences this contact belongs to, including the one being listed, most-recently-joined first.
   */
  readonly audiences?: Array<AudienceRef>;
};

export type AudienceMemberList = {
  /**
   * Page of audience members, each a contact paired with the time it joined the audience.
   */
  data: Array<AudienceMember>;
} & ListEnvelope;

export type AudienceContactsAddRequest = {
  /**
   * Contacts to add to the audience. Adding a contact that is already a member has no effect and keeps its original join time. Duplicate IDs in the list are collapsed. If any ID does not exist in the workspace, the whole request fails with a validation error and no contacts are added.
   */
  contact_ids: Array<ContactId>;
};

export type AudienceContactsRemoveRequest = {
  /**
   * Contacts to remove from the audience. Removing a contact that is not a member has no effect. Duplicate IDs in the list are collapsed. If any ID does not exist in the workspace, the whole request fails with a validation error and no memberships are removed.
   */
  contact_ids: Array<ContactId>;
};

/**
 * Whether a message was sent from the workspace (`outbound`) or received by it (`inbound`).
 */
export type MessageDirection = "outbound" | "inbound";

/**
 * Content classification: why you are sending. Carriers see it, and where a destination country requires the sender to be registered, that registration is approved for a category: a send outside what it covers returns a `422` `SenderCategoryNotPermitted`. A registration approved for `marketing` covers all four values; one approved for `transactional`, `authentication`, or `service` covers those three and not `marketing`. Use `authentication` for a one-time passcode and `marketing` for a promotion; otherwise pick the value matching the message's purpose.
 */
export type SmsMessageCategory =
  "transactional" | "marketing" | "authentication" | "service";

export type SmsMessageId = string;

/**
 * Delivery status:
 *
 * - `accepted`: Accepted and awaiting carrier handoff.
 * - `sent`: Handed to the carrier and awaiting a delivery receipt.
 * - `delivered`: Confirmed as delivered.
 * - `undelivered`: The carrier reported delivery as failed for a reason that may clear later, such as a handset out of coverage or a carrier at capacity. Final all the same: the message is not retried, so reaching the recipient means sending again.
 * - `failed`: The carrier reported delivery as failed for a reason that will not clear, such as an unassigned number, a recipient who has opted out, or content the carrier refused.
 * - `rejected`: Refused before carrier handoff.
 * - `expired`: Reached its validity limit without a final receipt.
 * - `received`: Received as an inbound message.
 *
 * `scheduled` and `canceled` are declared ahead of the send-later scheduling
 * feature that produces them, so their arrival is not a breaking change. No
 * message carries either status today.
 *
 */
export type SmsMessageStatus =
  | "scheduled"
  | "accepted"
  | "sent"
  | "delivered"
  | "undelivered"
  | "failed"
  | "rejected"
  | "canceled"
  | "expired"
  | "received";

/**
 * Segment breakdown for the message body. Segment count drives billing.
 */
export type SmsSegments = {
  /**
   * Number of segments the body is split into. Each segment is a billable unit.
   */
  readonly count: number;
  /**
   * Encoding used for the body. The `GSM_7BIT` encoding fits 160 characters in one segment, or 153 per part in a multi-segment message. The `UCS2` encoding applies when the body contains a character outside the GSM 03.38 alphabet, including emoji, CJK, and some accented characters. It fits 70 characters in one segment, or 67 per part in a multi-segment message.
   *
   */
  readonly encoding: "GSM_7BIT" | "UCS2";
  /**
   * Character count of the body under the selected encoding.
   */
  readonly characters: number;
};

/**
 * ISO 4217 three-letter currency code.
 */
export type CurrencyCode = string;

/**
 * What was charged for a message, split into the components that make it up. `null` until at least one component has been priced.
 *
 */
export type MessageCost = {
  /**
   * Total charged, as a decimal string: the sum of the components below. Net of tax, which applies to your wallet balance rather than to an individual charge.
   *
   */
  readonly amount: string;
  /**
   * ISO 4217 currency code. Every component is denominated in this currency.
   */
  readonly currency_code: CurrencyCode;
  /**
   * What we charged to carry the message, as a decimal string. `null` when this component was not priced; `"0.00000"` when it priced at zero.
   *
   */
  readonly transaction_amount: string | null;
  /**
   * Third-party fees we pass on, as a decimal string, such as US 10DLC carrier surcharges. `null` when this component was not priced; `"0.00000"` when it priced at zero.
   *
   */
  readonly passthrough_amount: string | null;
} | null;

/**
 * The settings Bird applied to this message. Every option is reported, whether you set it on the send or took the default that was in force at the time.
 *
 */
export type SmsMessageEffectiveOptions = {
  /**
   * Whether Bird replaced characters outside the GSM-7 alphabet in this message's body with their closest equivalent before sending it. When `true`, `text` is the body as sent and `segments` describes that body.
   *
   */
  smart_encoding: boolean;
};

/**
 * Standardized failure reason:
 *
 * - `invalid_destination`: The number is unassigned, ported out, or malformed.
 * - `unreachable`: The handset is off or outside coverage.
 * - `blocked_by_carrier`: The carrier filtered the message.
 * - `blocked_by_recipient`: The recipient device blocked the sender.
 * - `landline_unreachable`: The destination is a landline that does not accept SMS.
 * - `content_rejected`: The carrier rejected the content.
 * - `sender_unregistered`: The sender is not registered for the destination.
 * - `recipient_opted_out`: The recipient is on a suppression list.
 * - `provider_unavailable`: The provider remained unavailable after retries.
 * - `insufficient_balance`: The workspace wallet could not fund the send.
 * - `unknown`: The failure could not be classified.
 *
 * This is an open enum. Accept unrecognized values.
 *
 */
export type SmsErrorCode =
  | "invalid_destination"
  | "unreachable"
  | "blocked_by_carrier"
  | "blocked_by_recipient"
  | "landline_unreachable"
  | "content_rejected"
  | "sender_unregistered"
  | "recipient_opted_out"
  | "provider_unavailable"
  | "insufficient_balance"
  | "unknown"
  | (string & {});

/**
 * Failure detail for a message that could not be delivered or was rejected.
 */
export type SmsError = {
  code: SmsErrorCode;
  /**
   * The failure in words, from whatever refused the message: the carrier's own reason text on a delivery receipt, or ours on a message stopped before a carrier saw it. Free-form, so branch on `code` and show this to a human.
   */
  description: string;
  /**
   * Raw provider-supplied error code, finer-grained than the `code` that normalizes it. Not a Bird-defined value, so quote it to support when asking why a message failed. Null when the provider sent none, including any failure decided before one was reached.
   */
  carrier_error_code?: string | null;
  /**
   * When the failure occurred.
   */
  occurred_at: string;
} | null;

export type SmsMessage = {
  /**
   * ID of the message, assigned when the send is accepted. Pass it as `message_id` to the get-message endpoint.
   *
   */
  readonly id: SmsMessageId;
  /**
   * Whether the message was sent from a Bird sender (`outbound`) or received from a subscriber (`inbound`).
   */
  readonly direction: "outbound" | "inbound";
  readonly status: SmsMessageStatus;
  /**
   * Where the message went. On an outbound message this is the recipient's phone number in E.164 format; on an inbound one it is your own number that received it.
   *
   */
  to: string;
  /**
   * Where the message came from. On an outbound message this is the sender you sent it from: an E.164 number, an alphanumeric sender ID, or a short code. On an inbound message, this is the phone number that sent it to you.
   *
   */
  from: string;
  /**
   * The message body. Every message carries body text, attachments, or both, so this is absent only on a received message that carried attachments and no text. For a template send, this is the rendered text after parameter substitution. When `category` is `authentication` (a message carrying a one-time code), this is `**REDACTED**`: the code still reaches the recipient, but the API does not retain it for later reads.
   *
   */
  text?: string;
  /**
   * Content classification supplied on the send. Null for inbound messages.
   */
  category?: SmsMessageCategory | null;
  /**
   * Segment breakdown for the body.
   */
  segments: SmsSegments;
  /**
   * What the message cost, split into Bird's charge and any third-party fees passed through. Null until the message has been priced.
   */
  cost?: MessageCost;
  /**
   * Structured `{name, value}` filter labels applied to this message.
   */
  tags?: Array<Tag>;
  /**
   * Arbitrary JSON metadata stored on the message and echoed in webhook payloads.
   */
  metadata?: {
    [key: string]: unknown;
  };
  /**
   * The settings applied to this message, with any option you omitted filled in with the default in force when you sent it. Absent on inbound messages, and on any outbound message for which no settings were recorded.
   *
   */
  readonly options?: SmsMessageEffectiveOptions;
  /**
   * Preview feature: how long, in seconds, the carrier may keep attempting delivery before the message is marked `expired`. Not returned yet.
   */
  readonly validity_period?: number;
  /**
   * Carrier that handled the message. Absent until a delivery receipt identifies it, and on a received message the carrier reports it only where a carrier fee applies.
   */
  readonly carrier?: string;
  /**
   * Mobile country code and mobile network code of the carrier. Absent until the carrier is identified.
   */
  readonly mcc_mnc?: string;
  /**
   * Failure detail on a message that failed, was rejected, was not delivered, or expired. Absent otherwise.
   */
  last_error?: SmsError;
  /**
   * When the message was accepted (outbound) or received (inbound).
   */
  readonly created_at: string;
  /**
   * When the message was handed to the carrier. Null until then.
   */
  readonly sent_at?: string | null;
  /**
   * When delivery was confirmed. Null until then.
   */
  readonly delivered_at?: string | null;
};

export type SmsMessageList = {
  /**
   * Page of SMS messages, newest first.
   */
  data: Array<SmsMessage>;
} & ListEnvelope;

/**
 * Settings that change how Bird processes this message. Each option applies to this send only; omit one to use its default.
 *
 */
export type SmsSendOptions = {
  /**
   * Replace characters outside the GSM-7 alphabet with their closest GSM-7 equivalent before sending: typically curly quotes, dashes, ellipses, fullwidth forms, and non-breaking spaces.
   *
   * One such character forces the whole body into `UCS2`, which more than halves the characters that fit in a segment, so replacing them often lowers the segment count and the cost.
   *
   * Disabled by default, because it alters the body you composed. The replacement is all-or-nothing: a body that still holds a character outside the alphabet afterwards, such as an emoji or a non-Latin script, is sent exactly as you supplied it. Read the message back to see what was applied: `text` is the body as sent.
   *
   */
  smart_encoding?: boolean;
  /**
   * Preview feature: link click tracking. Defaults to `false`. Currently unavailable; setting this to `true` returns `422 SMSUnsupportedFeature`.
   */
  track_clicks?: boolean;
  /**
   * Preview feature: per-segment price ceiling. Currently unavailable; supplying this field returns `422 SMSUnsupportedFeature`.
   */
  max_price_per_segment?: number;
};

export type SmsTemplateId = string;

export type SmsTemplateSend = unknown & {
  /**
   * The template to send, by its id.
   */
  id?: SmsTemplateId;
  /**
   * The template to send, by its slug handle (for example `bird_otp_verification`). Browse the available templates and their variables with the templates endpoint.
   *
   */
  slug?: TemplateSlug;
  /**
   * Deprecated: use `slug` instead. Resolved as a slug first, and only if that finds nothing, matched against the template's display name.
   *
   *
   * @deprecated
   */
  name?: string;
  /**
   * Which of the template's languages to send. Omit it to send the template's default language, unless the template sets `language_source_required`, in which case a send naming no language is rejected. When the template does not carry the language you ask for, its own `on_missing_language` setting decides whether the closest available language is sent instead or the send is rejected.
   *
   */
  language?: LanguageTag;
  /**
   * Values for the template's variables, keyed by variable name. The accepted keys and their formats are fixed per template (the template's `variables` on the templates endpoint). A missing required variable, an undeclared key, a value that does not match its variable's format, or a serialized payload over 16 KB each return a `422`.
   *
   */
  parameters?: {
    [key: string]: unknown;
  };
};

export type SmsMessageSendRequest = unknown & {
  /**
   * Recipient phone number in E.164 format (for example `+14155550100`). One recipient per message. The number is stored and returned in canonical E.164; a recipient that cannot be routed returns a `422` `SMSInvalidRecipient`.
   *
   */
  to: string;
  /**
   * Sender to send from. Use an E.164 number such as `+15557654321`, or a short code of 5-6 digits. You can also use an alphanumeric sender ID of 1-11 letters, digits, spaces, dashes, or underscores. It must contain at least one letter, for example `MyBrand`. A numeric sender must be a number your workspace owns; an alphanumeric sender is accepted where the destination country permits one. Required on a free-text send: omitting it returns a `422` `SMSNoEligibleSender`. Not accepted alongside `template`, which selects its sender automatically.
   *
   */
  from?: string;
  /**
   * Free-text message body. Required unless `template` is supplied (the two are mutually exclusive). At least 1 character, up to a 12-segment cap (roughly 1836 GSM-7 or 804 UCS-2 characters). Bird does not truncate; a body exceeding 12 segments is rejected with a 422. The cap applies to segments because GSM-7 and UCS-2 encodings differ in characters per segment.
   *
   */
  text?: string;
  /**
   * Content classification: why you are sending. Required on a free-text send; omit it on a template send, where the category is derived from the template. Where the destination country requires the sender to be registered, a category outside what that registration covers returns a `422` `SenderCategoryNotPermitted`.
   *
   */
  category?: SmsMessageCategory;
  /**
   * Preview feature: how long, in seconds (60-172800), the carrier may keep attempting delivery before the message is marked `expired`. Currently unavailable; supplying this field returns `422 SMSUnsupportedFeature`.
   *
   */
  validity_period?: number;
  /**
   * Structured `{name, value}` labels for filtering and analytics. Tags become first-class query dimensions: filter the list endpoint by tag name, slice analytics by tag, and surface in webhook payloads. Maximum 20 tags per send. Use tags for low-cardinality dimensions (`category`, `experiment_variant`). For arbitrary structured context you do not need as a filter dimension, use `metadata` instead.
   *
   */
  tags?: Array<Tag>;
  /**
   * Arbitrary JSON object stored on the message, returned on API reads, and echoed in webhook payloads. Maximum 2 KB serialized. Use metadata for per-send context like internal IDs and foreign keys. For low-cardinality filterable labels, use `tags` instead.
   *
   */
  metadata?: {
    [key: string]: unknown;
  };
  /**
   * What Bird does to this message on its way out, such as `smart_encoding`. The message being relayed stays at the top level: its recipient, sender, content, and the delivery instructions the carrier acts on.
   *
   */
  options?: SmsSendOptions;
  /**
   * Preview feature: multimedia (MMS) attachments. Currently unavailable; supplying this field returns `422 SMSUnsupportedFeature`.
   */
  media_urls?: Array<string>;
  /**
   * Preview feature: sender selection from a messaging profile pool. Currently unavailable; supplying this field returns `422 SMSUnsupportedFeature`.
   */
  messaging_profile_id?: string;
  /**
   * Preview feature: send-later scheduling. Currently unavailable; supplying this field returns `422 SMSUnsupportedFeature`.
   */
  scheduled_at?: string;
  /**
   * Send using a stored template instead of free text. Mutually exclusive with `text`; the message category is derived from the template, so `from`, `category`, and `media_urls` are not accepted alongside it.
   *
   */
  template?: SmsTemplateSend;
  /**
   * Preview feature: broadcast correlation. Currently unavailable; supplying this field returns `422 SMSUnsupportedFeature`.
   */
  broadcast_id?: string;
  /**
   * Preview feature: campaign correlation for analytics. Currently unavailable; supplying this field returns `422 SMSUnsupportedFeature`.
   */
  campaign_id?: string;
  /**
   * Preview feature: audience-targeted sends. Currently unavailable; supplying this field returns `422 SMSUnsupportedFeature`.
   */
  audience_id?: string;
  /**
   * Preview feature: contact-targeted sends. Currently unavailable; supplying this field returns `422 SMSUnsupportedFeature`.
   */
  contact_id?: string;
  /**
   * Preview feature: topic-gated sends. Currently unavailable; supplying this field returns `422 SMSUnsupportedFeature`.
   */
  topic_id?: string;
  /**
   * Preview feature: per-recipient substitution for batch sends. Currently unavailable; supplying this field returns `422 SMSUnsupportedFeature`.
   */
  personalization?: {
    [key: string]: unknown;
  };
};

/**
 * Batch of SMS message send requests. All items are validated before any are queued.
 */
export type SmsMessageBatchRequest = Array<SmsMessageSendRequest>;

/**
 * Aggregate result for an SMS batch.
 */
export type SmsBatchSummary = {
  /**
   * Number of messages accepted in the batch. Acceptance is all-or-nothing, so this equals the number of messages submitted.
   *
   */
  accepted_count: number;
};

export type SmsMessageBatchResponse = {
  /**
   * One entry per message in the batch, in submission order.
   */
  data: Array<SmsMessage>;
  /**
   * Aggregate result for the batch.
   */
  summary: SmsBatchSummary;
};

export type SmsEvent = {
  /**
   * Unique identifier for this event, stable across repeated fetches of the message.
   */
  readonly id: string;
  /**
   * Lifecycle event type. The `sms.accepted` event means the API accepted the request. The `sms.sent` event means the message reached the carrier. The `sms.delivered` event confirms delivery. The `sms.undelivered`, `sms.failed`, and `sms.expired` events describe delivery failures. The `sms.rejected` event means the message was refused before carrier handoff. This is an open enum. Accept unrecognized values.
   *
   */
  readonly type: string;
  /**
   * When this event occurred.
   */
  readonly occurred_at: string;
  /**
   * Carrier that handled the message. Present on `sms.sent` and `sms.delivered` once identified, absent otherwise.
   */
  readonly carrier?: string;
  /**
   * Mobile country code and mobile network code of the carrier. Present on `sms.sent` and `sms.delivered` once identified, absent otherwise.
   */
  readonly mcc_mnc?: string;
  /**
   * Failure detail. Present only on `sms.failed`, `sms.undelivered`, `sms.rejected`, and `sms.expired` events.
   */
  error?: SmsError;
};

export type SmsEventList = {
  /**
   * Timeline events for this SMS message, in chronological order. The bounded timeline is returned in full and is not paginated.
   */
  data: Array<SmsEvent>;
};

/**
 * Whether the template is one of our built-in templates (`system`) or one your workspace created (`workspace`). Every SMS template is `system`.
 *
 */
export type TemplateScope = "system" | "workspace";

/**
 * Where the template stands as a whole. The same five states on every channel.
 *
 * - `draft`: nothing has ever gone live.
 * - `pending`: nothing is live and at least one language is in review.
 * - `active`: at least one language is live, so something can be sent.
 * - `rejected`: it was reviewed and every language was refused.
 * - `inactive`: nothing is live and nothing is in review, so content was withdrawn or was blocked before anything went live.
 *
 * This summary answers whether the template is usable at all. A template with
 * one language live is `active` even while another is still drafted or refused.
 * Read `languages` to determine the state of each language and its reason.
 *
 * Which of the five a template can reach follows its channel's review model. A
 * channel whose content a third party reviews reaches all five; one whose
 * content goes live on publish moves between `draft`, `active` and `inactive`.
 *
 * Open enum: treat a value you do not recognize as a new one rather than as
 * an error.
 *
 */
export type TemplateStatus =
  "draft" | "pending" | "active" | "rejected" | "inactive" | (string & {});

/**
 * A single variable slot a template fills in from the values supplied when sending. The same shape on email, SMS and WhatsApp, so reading what a template needs works the same way whichever channel you are sending on.
 *
 */
export type TemplateVariable = {
  /**
   * The key this slot is filled by. On email and SMS it is the key you set in the send's `parameters` object. On WhatsApp it is the `name` you repeat on the matching parameter inside `components`, or, for a template whose placeholders are positional, the position itself as `1`, `2` and so on.
   *
   */
  readonly key: string;
  /**
   * The value type this slot accepts. SMS templates use the typed slots (`code`, `amount` and the rest), each of which rejects a value that does not match its `constraint`. Email and WhatsApp templates use `text`, which accepts any value. Open enum: treat an unrecognized value as a future type rather than an error.
   *
   */
  readonly type: string;
  /**
   * Whether the send must supply this variable. Omitting a required value returns `422` on email, SMS, and WhatsApp sends.
   *
   */
  readonly required: boolean;
  /**
   * A plain-language description of what values this variable accepts.
   */
  readonly constraint: string;
  /**
   * Whether this slot's value is kept out of durable storage. A sensitive slot's rendered value never appears in message content read back through the API: a stand-in placeholder is stored instead.
   *
   */
  readonly sensitive?: boolean;
};

/**
 * Status of one template language on channels without third-party review.
 *
 * - `draft`: it has never been published.
 * - `live`: it is available to sends.
 * - `superseded`: a later version replaced it.
 *
 * Treat an unknown value as not sendable.
 *
 */
export type TemplateLanguageStatus =
  "draft" | "live" | "superseded" | (string & {});

/**
 * One language's state on a template: whether it is live for sends. Content is not here; the template carries the body of its default language, and a send resolves the rest.
 *
 */
export type SmsTemplateLanguageState = {
  status: TemplateLanguageStatus;
};

/**
 * What a send or a preview does when it asks for a language the template
 * cannot serve.
 *
 * `fallback` serves the closest match instead. It tries a broader form of the
 * same language first, so a request for `pt-BR` can be served by a stocked
 * `pt`, and then the template's default language. A send never fails because a
 * language is missing.
 *
 * `fail` rejects the send rather than serving a different language, for content
 * where sending the wrong language is worse than not sending at all. It matches
 * the requested tag or a broader form of it and refuses a sibling variant, so
 * `pt-BR` is never served by `pt-PT`. A send that names no language still uses
 * the default language.
 *
 * The default is per channel and stated on each channel's own field, because
 * what a wrong-language send costs differs. Where every language is separately
 * reviewed and separately priced, falling back silently would send content the
 * recipient did not expect at a rate the sender did not choose.
 *
 */
export type TemplateOnMissingLanguage = "fallback" | "fail";

export type SmsTemplateVersionId = string;

/**
 * A message template: one identity holding a copy of the message per language, resolved to one at send. It declares the variable slots a send fills in, so the parts that change travel with the request and the wording does not.
 *
 */
export type SmsTemplate = {
  /**
   * The template's generated identifier. Accepted anywhere a template is referenced: the `{template_ref}` path segment, and `template.id` on a send. The `slug` works in the same places and is more readable.
   */
  readonly id: SmsTemplateId;
  /**
   * The template's permanent handle. Pass it (or the id) as the template reference when sending. Handles beginning with `bird_` are reserved for our built-in templates.
   *
   */
  readonly slug: TemplateSlug;
  /**
   * The template's display name, shown wherever the template is listed. Nothing resolves through it, so it is safe to show wherever a human reads the template.
   *
   */
  readonly name: string;
  /**
   * What the template is for. Null when unset.
   */
  readonly description: string | null;
  scope: TemplateScope;
  status: TemplateStatus;
  /**
   * Content classification applied to messages sent from this template.
   */
  readonly category: SmsMessageCategory;
  /**
   * The template body in its default language, shown for preview. Variable placeholders appear inline (for example `{{ code }}`). Name a `language` on the send to have another one served.
   *
   */
  readonly body: string;
  /**
   * The typed slots this template fills in from the values you supply in `parameters` when sending. Every language of a template declares the same slots, so this list holds for whichever one a send resolves to.
   *
   */
  readonly variables: Array<TemplateVariable>;
  /**
   * The language a send uses when it names none, and the last resort when `on_missing_language` is `fallback` and the language asked for is not available.
   *
   */
  readonly default_language: LanguageTag;
  /**
   * The languages a send can resolve right now, as BCP-47 tags. The set may shrink for reasons other than editing, so read it rather than assuming it matches what you last saw.
   *
   */
  readonly available_languages: Array<LanguageTag>;
  /**
   * Where each of the template's languages stands, keyed by BCP-47 language tag. Content is not here: `body` previews the default language, and a send resolves the one it needs.
   *
   */
  readonly languages: {
    [key: string]: SmsTemplateLanguageState;
  };
  /**
   * What a send does when it asks for a language this template does not carry. Defaults to `fallback` on SMS.
   *
   */
  readonly on_missing_language: TemplateOnMissingLanguage;
  /**
   * Whether a send has to name a language. When true, a send that names none is rejected instead of being served the default language.
   *
   */
  readonly language_source_required: boolean;
  /**
   * The current editable draft version, or null for a built-in `system` template, which has no draft.
   *
   */
  readonly draft_version_id: SmsTemplateVersionId | null;
  /**
   * The version a send resolves to, or null for a built-in `system` template, which Bird ships ready to send rather than versioning.
   *
   */
  readonly live_version_id: SmsTemplateVersionId | null;
  /**
   * Deprecated: use `live_version_id` instead, which carries the same value.
   *
   *
   * @deprecated
   */
  readonly published_version_id: SmsTemplateVersionId | null;
  /**
   * The draft's revision counter. Null for a built-in `system` template, which is unversioned.
   *
   */
  readonly revision: number | null;
  /**
   * When this template was last submitted. Null for a built-in `system` template, which is already available to send.
   *
   */
  readonly last_submitted_at: string | null;
  /**
   * When the template was created. Null for a built-in `system` template, which Bird ships rather than stores.
   *
   */
  readonly created_at: string | null;
  /**
   * When the template was last modified. Null for a built-in `system` template, which Bird ships rather than stores.
   *
   */
  readonly updated_at: string | null;
};

export type SmsTemplateList = {
  /**
   * The templates available to your workspace. The catalog is returned in full and is not paginated.
   */
  data: Array<SmsTemplate>;
};

export type SmsSuppressionReasonFilter =
  "keyword_stop" | "carrier_opted_out" | "manual";

export type SmsSuppressionId = string;

/**
 * Reason this sender cannot message the subscriber:
 *
 * - `keyword_stop`: The subscriber sent a stop keyword. A start keyword clears it.
 * - `carrier_opted_out`: The carrier reported the opt-out.
 * - `manual`: Your workspace added the suppression through the API or dashboard.
 *
 * This is an open enum. Accept unrecognized values.
 *
 */
export type SmsSuppressionReason =
  "keyword_stop" | "carrier_opted_out" | "manual" | (string & {});

/**
 * How the opt-out reached us:
 *
 * - `keyword`: an inbound message from the subscriber.
 * - `dlr_event`: a carrier delivery report.
 * - `api_key`: an API call.
 * - `user`: someone acting in the dashboard.
 *
 * Kept beside the reason because one reason can arrive by more than one route.
 *
 * This list grows over time, so treat an unknown value as informational rather than rejecting the
 * record.
 *
 */
export type SmsSuppressionOrigin =
  "keyword" | "dlr_event" | "api_key" | "user" | (string & {});

/**
 * Message categories blocked for this sender and subscriber. `all` blocks every category, including authentication and transactional messages. `non_transactional` blocks marketing messages only. Responses currently use `all`. Treat unrecognized values as blocking every category.
 *
 */
export type SmsSuppressionCoverage =
  "all" | "non_transactional" | (string & {});

/**
 * What ended it:
 *
 * - `keyword_start`: the subscriber texting a start keyword to the same sender.
 * - `api_key`: an API call.
 * - `user`: someone acting in the dashboard.
 * - `carrier_cleared`: the carrier reporting its own opt-out cleared.
 *
 * This list grows over time, so treat an unknown value as informational rather than rejecting the
 * record.
 *
 */
export type SmsSuppressionEndReason =
  "keyword_start" | "api_key" | "user" | "carrier_cleared" | (string & {});

/**
 * One period during which a sender's messages to a subscriber are stopped: when it started, what started it, and what ended it. A subscriber who opts out, opts back in, and opts out again has three of these on record rather than one current state, and each keeps its own dates once it ends. The list returns the periods in force; fetch one by ID to read an ended one.
 *
 */
export type SmsSuppression = {
  readonly id: SmsSuppressionId;
  /**
   * The subscriber, in E.164 format.
   */
  destination: string;
  /**
   * The sender this stops. A suppression covers one sender, so your other senders still reach this subscriber. Opting out of one of your programs does not opt out of the others.
   *
   */
  originator: string;
  readonly reason: SmsSuppressionReason;
  readonly origin: SmsSuppressionOrigin;
  readonly applies_to: SmsSuppressionCoverage;
  /**
   * Whether this is stopping messages right now. Always true in a list, which carries only the suppressions in force; false when you fetch one by ID that has since ended, which is also when `ended_at` is set.
   *
   */
  readonly blocking: boolean;
  /**
   * The inbound message the subscriber opted out with, or the outbound message whose delivery report reported the opt-out. Null when neither applies.
   *
   */
  readonly source_sms_id?: SmsMessageId | null;
  /**
   * When the subscriber opted out, as reported by whoever reported it. This is what orders one subscriber's history, and it can be earlier than `created_at` when a message reached us late.
   *
   */
  readonly effective_at: string;
  /**
   * When this stopped applying. Null while it is still stopping messages.
   */
  readonly ended_at?: string | null;
  /**
   * What ended it. Null while it is still stopping messages.
   */
  readonly ended_reason?: SmsSuppressionEndReason | null;
  /**
   * When the subscriber opted back in, as reported. Null while it is still stopping messages.
   */
  readonly ended_effective_at?: string | null;
  /**
   * The inbound message the subscriber opted back in with, when there was one. Null while it is still stopping messages, and when something other than a start keyword ended it.
   *
   */
  readonly source_end_sms_id?: SmsMessageId | null;
  /**
   * When we recorded it.
   */
  readonly created_at: string;
  /**
   * When we last recorded the subscriber opting out of this sender. Later than `created_at` when they texted a stop keyword again while already suppressed, which adds no new record but does earn another confirmation reply.
   *
   */
  readonly last_asserted_at: string;
};

export type SmsSuppressionList = {
  /**
   * Page of suppressions, most recent opt-out first.
   */
  data: Array<SmsSuppression>;
} & ListEnvelope;

/**
 * Stops one sender's messages to one subscriber. Both ends are required, because a suppression covers a sender-and-subscriber pair rather than a subscriber alone.
 *
 */
export type SmsSuppressionCreate = {
  /**
   * The subscriber to stop messaging, in E.164 format.
   */
  destination: string;
  /**
   * The sender to stop. Your other senders keep reaching this subscriber, so stopping every one of them means one call per sender.
   *
   */
  originator: string;
};

/**
 * What Bird does when an inbound message matches the rule.
 *
 * - `stop` unsubscribes the sender from further messages.
 * - `start` resubscribes them.
 * - `help` replies with your support information.
 * - `info` replies with your program information. It behaves exactly as `help` does and is
 * separate so a country whose INFO answer must differ from its HELP answer can carry both.
 * Where Bird ships no `info` rule for a country, INFO is one of that country's `help`
 * keywords and answers with the `help` reply.
 * - `confirm` marks a double opt-in reply. It sends nothing today, so answer it from your own
 * handler.
 * - `custom` replies with the text you configured and has no other effect.
 *
 * Bird's built-in rules fix the operation for `stop`, `start` and `help`; you can change their
 * reply but not what they do. The same holds for `info` in any country where Bird ships an
 * `info` rule. This is an open enum. Accept unrecognized values.
 *
 */
export type SmsKeywordOperation =
  "stop" | "start" | "help" | "info" | "confirm" | "custom" | (string & {});

/**
 * Whether the rule is one of Bird's defaults (`system`) or one your workspace created (`workspace`). A `workspace` rule takes precedence over Bird's default for the same country, so it is how you replace a reply without losing the keywords Bird ships.
 *
 */
export type SmsKeywordRuleScope = "system" | "workspace";

/**
 * Identifier of a keyword rule. An `sks_` id is one of Bird's defaults, which you can read but not change; an `skw_` id is a rule your workspace created.
 *
 */
export type SmsKeywordRuleId = string;

export type SmsKeywordRule = {
  id: SmsKeywordRuleId;
  scope: SmsKeywordRuleScope;
  operation: SmsKeywordOperation;
  /**
   * The country the rule applies in, as an ISO 3166-1 alpha-2 code. A rule for `NL` covers messages received on your Dutch numbers, and messages from a subscriber whose own number is Dutch whichever of your numbers they text. Rules for the country a message arrives in always outrank rules for the country its sender is in; within each, your rule wins over Bird's keywords for that country. `number` confines a rule to one number. Null means the rule applies worldwide, which is allowed for `custom` operations only.
   *
   */
  country?: string | null;
  /**
   * The language this rule covers, in countries where Bird ships keywords in more than one. Canada has separate English and French rules, so a Canadian rule names which one it replaces and the other keeps Bird's reply. Null in countries with a single set.
   *
   */
  language?: string | null;
  /**
   * Narrows the rule to one of your numbers in E.164 format, instead of every number you hold in the country. Null means it applies to all of them.
   *
   */
  number?: string | null;
  /**
   * The keywords this rule adds. For one of Bird's defaults this is the full set Bird ships. For a rule you created it is only what you added on top. It never restates or removes Bird's keywords, so `effective_keywords` is what actually matches.
   *
   */
  keywords: Array<string>;
  /**
   * Every keyword that matches this rule: Bird's keywords for the same operation, country and language, plus the ones you added. This is what an inbound message is compared against. Keywords Bird adds later join it without you changing anything.
   *
   */
  readonly effective_keywords: Array<string>;
  /**
   * The message sent back when one of the keywords matches, except on a `confirm` rule, which never sends one. Null when the auto-reply is switched off, which `reply_disabled_at` distinguishes from a rule that has not been given one.
   *
   */
  reply?: string | null;
  /**
   * Text appended to your reply that you cannot change: the rates and opt-out wording carriers require on a help response. Your reply is sent in front of it, and both count against the length a single message allows. Null when the operation carries none.
   *
   */
  readonly reply_suffix?: string | null;
  /**
   * When the auto-reply for this rule was switched off, or null if it is on. Switching it off records that you send this reply from your own system, which is what Bird points to if a carrier asks why no reply went out.
   *
   */
  readonly reply_disabled_at?: string | null;
  /**
   * Whether what this operation does is fixed. When true you can change the reply but not the behavior. An opt-out keyword always unsubscribes the sender, whichever rule matched it, because carriers and regulators require it.
   *
   */
  readonly mandatory: boolean;
  /**
   * When the rule was created.
   */
  readonly created_at: string;
  /**
   * When the rule was last changed. On one of Bird's defaults this is when Bird last changed the keywords or the reply for that country.
   */
  readonly updated_at: string;
};

export type SmsKeywordRuleList = {
  /**
   * The keyword rules that apply to your workspace, Bird's defaults included. Ordered most specific first, so the first rule whose keywords match an inbound message is the one that runs. The set is small and returned in full; this list is not paginated.
   *
   */
  data: Array<SmsKeywordRule>;
};

export type SmsKeywordRuleCreate = {
  operation: SmsKeywordOperation;
  /**
   * The country this rule applies in, as an ISO 3166-1 alpha-2 code. It matches a message two ways: one received on any of your numbers in this country, and one sent by a subscriber whose own number is in it, wherever they text you. Rules for the country a message arrives in always outrank rules for the country its sender is in; within each, your rule wins over Bird's keywords for that country. To confine a rule to one of your numbers, set `number` instead. Required for `stop`, `start` and `help`, because those replace what Bird ships for one country and a worldwide rule would replace every country's. Omit it only for `custom`, which then applies everywhere you send. Derived from `number` when you supply an E.164 number and leave this out; a short code carries no country, so a rule for one must name it.
   *
   */
  country?: string | null;
  /**
   * Which language this rule replaces, in countries where Bird ships keywords in more than one. Required there and rejected elsewhere. Listing the country's rules shows whether it applies and which languages are available.
   *
   */
  language?: string | null;
  /**
   * Narrows the rule to one number you hold, in E.164 format or as a short code. Omit to cover every number you hold in the country. The number must be one of yours and able to receive messages.
   *
   */
  number?: string | null;
  /**
   * Extra keywords to match, on top of the ones Bird already ships for this operation and country. Omit to keep Bird's keywords and change only the reply, including keywords Bird adds later. You cannot remove one of Bird's keywords, and a keyword Bird has bound to another operation cannot be reused here. Required for `custom`, which inherits none.
   *
   */
  keywords?: Array<string>;
  /**
   * The message to send back when a keyword matches, except on a `confirm` rule, which never sends one whatever this is set to. Set it to null together with `confirmed_self_managed` to send nothing at all.
   *
   */
  reply?: string | null;
  /**
   * Set this with `reply: null` to confirm you send this reply from your own system, which switches Bird's auto-reply off for the rule. Required to send no reply, and rejected when a reply is given, so the two can never disagree.
   *
   */
  confirmed_self_managed?: boolean;
};

/**
 * Changes the reply and the added keywords. What a rule applies to (its operation, country, language and number) is fixed once created: those decide which inbound messages reach it, so changing one would make it a different rule. Delete it and create the one you want.
 *
 */
export type SmsKeywordRuleUpdate = {
  /**
   * Replaces the extra keywords this rule matches, on top of the ones Bird ships. Send an empty array to keep Bird's keywords only. Omit to leave the current ones unchanged.
   *
   */
  keywords?: Array<string>;
  /**
   * Replaces the message sent back when a keyword matches, except on a `confirm` rule, which never sends one whatever this is set to. Set it to null together with `confirmed_self_managed` to switch the auto-reply off. Omit to leave it unchanged.
   *
   */
  reply?: string | null;
  /**
   * Set this with `reply: null` to confirm you send this reply from your own system. Required to switch the auto-reply off, and rejected when a reply is given.
   *
   */
  confirmed_self_managed?: boolean;
};

/**
 * Set to `previous_period` to also return the same figures for the immediately preceding window of equal length, plus the change between the two, so you can show "+X% vs last period" without a second request.
 *
 */
export type StatsComparePeriod = "previous_period";

/**
 * The window the server actually computed against. The summary serves two window grains: calendar days (bounds are YYYY-MM-DD) and hours (bounds are RFC 3339 instants on the hour). The grain of `from` and `to` mirrors the grain of the request's bounds.
 *
 */
export type SmsStatsSummaryPeriod = {
  /**
   * Inclusive start of the window, as a calendar day (`YYYY-MM-DD`) or an RFC 3339 hour boundary.
   */
  readonly from: string;
  /**
   * Inclusive end of the window, as a calendar day (`YYYY-MM-DD`) or an RFC 3339 hour boundary.
   */
  readonly to: string;
  /**
   * Latest time reflected in the statistics. More recent events might not be included yet. Null when the freshness boundary is unavailable.
   *
   */
  readonly data_as_of?: string | null;
};

/**
 * SMS lifecycle counts and rates for a whole period or breakdown. Counts use the message send time, so a later delivery stays attributed to the bucket in which the message was sent. Rates are null when their denominator is zero.
 *
 */
export type SmsDeliveryStats = {
  /**
   * Distinct messages accepted for sending after admission checks. This is the denominator for `delivery_rate` and `failure_rate`.
   */
  readonly accepted: number;
  /**
   * Distinct messages handed off to the carrier for delivery.
   */
  readonly sent: number;
  /**
   * Distinct messages the carrier confirmed as delivered to the handset.
   */
  readonly delivered: number;
  /**
   * Distinct messages the carrier reported as not delivered.
   */
  readonly undelivered: number;
  /**
   * Distinct messages that failed during sending.
   */
  readonly failed: number;
  /**
   * Distinct messages rejected before any send attempt, for example by sending policy or a message-generation failure.
   */
  readonly rejected: number;
  /**
   * Distinct messages that could not be delivered within their validity window and expired.
   */
  readonly expired: number;
  /**
   * Share of accepted messages that were delivered, computed as `delivered / accepted`. Null when no messages were accepted in scope.
   *
   */
  readonly delivery_rate: number | null;
  /**
   * Share of accepted messages that ultimately failed, computed as `(undelivered + failed + expired) / accepted`. Null when no messages were accepted in scope.
   *
   */
  readonly failure_rate: number | null;
};

/**
 * Approximate p50, p95, and p99 latency percentiles in milliseconds for one latency family. All three are null when no qualifying event contributed a measurement.
 *
 */
export type SmsLatencyQuantiles = {
  /**
   * Median (50th percentile) latency in milliseconds. Null when no qualifying event contributed a measurement.
   */
  readonly p50_ms: number | null;
  /**
   * 95th percentile latency in milliseconds. Null when no qualifying event contributed a measurement.
   */
  readonly p95_ms: number | null;
  /**
   * 99th percentile latency in milliseconds. Null when no qualifying event contributed a measurement.
   */
  readonly p99_ms: number | null;
};

/**
 * Latency percentiles in milliseconds for the requested scope:
 *
 * - `processing`: From acceptance to carrier handoff.
 * - `delivery`: From carrier handoff to delivery confirmation.
 * - `total`: From acceptance to delivery confirmation.
 *
 * Each family is omitted when no qualifying event contributes a measurement.
 * Individual percentiles can also be null.
 *
 */
export type SmsLatencyStats = {
  processing?: SmsLatencyQuantiles;
  delivery?: SmsLatencyQuantiles;
  total?: SmsLatencyQuantiles;
};

/**
 * Changes from the previous period. A `*_pct_change` value is the signed relative change `(current - previous) / previous` and is null when the previous count is zero. A `*_rate_pp` value is the signed difference between rate fractions and is null when either rate is undefined.
 *
 */
export type SmsStatsComparisonDelta = {
  /**
   * Relative change in accepted messages (`delivery.accepted`) versus the previous period, as a signed fraction. Null when the previous period accepted none.
   */
  readonly accepted_pct_change: number | null;
  /**
   * Relative change in sent messages (`delivery.sent`) versus the previous period, as a signed fraction. Null when the previous period had none.
   */
  readonly sent_pct_change: number | null;
  /**
   * Relative change in delivered messages (`delivery.delivered`) versus the previous period, as a signed fraction. Null when the previous period delivered none.
   */
  readonly delivered_pct_change: number | null;
  /**
   * Relative change in undelivered messages (`delivery.undelivered`) versus the previous period, as a signed fraction. Null when the previous period had none.
   */
  readonly undelivered_pct_change: number | null;
  /**
   * Relative change in failed messages (`delivery.failed`) versus the previous period, as a signed fraction. Null when the previous period had none.
   */
  readonly failed_pct_change: number | null;
  /**
   * Relative change in rejected messages (`delivery.rejected`) versus the previous period, as a signed fraction. Null when the previous period had none.
   */
  readonly rejected_pct_change: number | null;
  /**
   * Relative change in expired messages (`delivery.expired`) versus the previous period, as a signed fraction. Null when the previous period had none.
   */
  readonly expired_pct_change: number | null;
  /**
   * Signed difference between this period's and the previous period's delivery rate, both fractions in [0,1] (multiply by 100 for percentage points). Null when either period's delivery rate is undefined.
   */
  readonly delivery_rate_pp: number | null;
  /**
   * Signed difference between the current and previous failure-rate fractions. Multiply by 100 for percentage points. The value can fall outside `[-1, 1]` because a message can contribute to more than one failure outcome and high-volume counts are approximate. Null when either rate is undefined.
   *
   */
  readonly failure_rate_pp: number | null;
};

/**
 * The same statistics for the equal-length, inclusive period ending immediately before the requested start, together with the change between the two periods. Present only when `compare=previous_period` is requested. The change is already computed, so a percentage difference needs no second request.
 *
 */
export type SmsStatsComparison = {
  /**
   * Equal-length window ending immediately before the requested start.
   */
  period: SmsStatsSummaryPeriod;
  readonly delivery: SmsDeliveryStats;
  readonly latency: SmsLatencyStats;
  readonly delta: SmsStatsComparisonDelta;
};

/**
 * Single-row aggregate across the full requested period, covering SMS lifecycle counts plus the derived delivery and failure rates, and latency percentiles. Use this endpoint for KPI tiles and reporting; the daily and hourly endpoints carry the same counts per bucket.
 *
 * Every count is a sum of per-bucket counts across the window. Latency percentiles are computed across the whole period rather than summed per bucket. Rates are null when their denominator is zero.
 *
 */
export type SmsStatsSummary = {
  /**
   * The window the response covers (echoed back from the request, day or hour grain), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: SmsStatsSummaryPeriod;
  readonly delivery: SmsDeliveryStats;
  readonly latency: SmsLatencyStats;
  readonly comparison?: SmsStatsComparison;
};

/**
 * The bucket grain of the series, either `day` or `hour`.
 */
export type StatsGrain = "day" | "hour";

/**
 * The window and bucket grain the response covers, echoed from the request, plus the freshness boundary the data is current to.
 *
 */
export type SmsStatsSeriesPeriod = {
  /**
   * Inclusive start of the window. A calendar day (YYYY-MM-DD) on the day grain, an RFC 3339 instant rounded to the hour on the hour grain.
   */
  readonly from: string;
  /**
   * Inclusive end of the window. A calendar day (YYYY-MM-DD) on the day grain, an RFC 3339 instant rounded to the hour on the hour grain.
   */
  readonly to: string;
  readonly grain: StatsGrain;
  /**
   * Latest time reflected in the statistics. More recent events might not be included yet. Null when the freshness boundary is unavailable.
   *
   */
  readonly data_as_of?: string | null;
};

/**
 * SMS lifecycle counts for a time bucket. Counts use the message send time, so a message accepted on Monday and delivered on Tuesday counts in Monday's bucket. Rates are available only for whole periods and breakdowns.
 *
 */
export type SmsDeliveryCounts = {
  /**
   * Distinct messages accepted for sending after admission checks.
   */
  readonly accepted: number;
  /**
   * Distinct messages handed off to the carrier for delivery.
   */
  readonly sent: number;
  /**
   * Distinct messages the carrier confirmed as delivered to the handset.
   */
  readonly delivered: number;
  /**
   * Distinct messages the carrier reported as not delivered.
   */
  readonly undelivered: number;
  /**
   * Distinct messages that failed during sending.
   */
  readonly failed: number;
  /**
   * Distinct messages rejected before any send attempt, for example by sending policy or a message-generation failure.
   */
  readonly rejected: number;
  /**
   * Distinct messages that could not be delivered within their validity window and expired.
   */
  readonly expired: number;
};

/**
 * SMS lifecycle counts for one time bucket (a calendar day or hour), bucketed by send time. Every count in a bucket describes the messages accepted in it, regardless of when their later events arrived. Per-bucket values include counts only. The summary and breakdown endpoints report rates and latency as whole-window aggregates.
 *
 */
export type SmsStatsPoint = {
  /**
   * The day (YYYY-MM-DD) or hour (RFC 3339, on the hour) this point covers, matching the period's grain.
   */
  readonly bucket: string;
  readonly delivery: SmsDeliveryCounts;
};

/**
 * Time-series stats payload. `period` echoes the range and bucket grain the server computed against; `data` is one row per bucket in chronological order.
 *
 */
export type SmsStatsResponse = {
  period: SmsStatsSeriesPeriod;
  /**
   * One row per day or hour in chronological order. Buckets with no activity contain zero counts.
   */
  readonly data: Array<SmsStatsPoint>;
};

/**
 * Metric to rank breakdown rows by, applied descending. Shared by the volume breakdowns whose rows carry the full delivery and latency block (originators, countries, categories, carriers). Any lifecycle count or derived rate may be used; rows whose rate is undefined (zero denominator) sort last.
 *
 */
export type SmsStatsSortMetric =
  | "accepted"
  | "sent"
  | "delivered"
  | "undelivered"
  | "failed"
  | "rejected"
  | "expired"
  | "delivery_rate"
  | "failure_rate";

/**
 * Bucket grain for a stats trend series.
 */
export type StatsTrendGrain = "daily" | "hourly";

/**
 * Aggregate delivery and latency stats for a single originator (the sender address messages were sent from) over the requested period.
 */
export type SmsOriginatorStatsPoint = {
  /**
   * Sender address this row aggregates, either an alphanumeric sender ID or a phone number. Matches the message `from` value.
   */
  readonly originator: string;
  readonly delivery: SmsDeliveryStats;
  readonly latency: SmsLatencyStats;
  /**
   * Per-bucket lifecycle counts for this originator, using `trend_grain`. Includes only buckets with activity. Present when `include_trend=true`.
   */
  readonly trend?: Array<SmsStatsPoint>;
};

/**
 * Per-originator breakdown for the requested period, ranked by the `sort` metric (default `accepted`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type SmsStatsByOriginatorResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: SmsStatsSummaryPeriod;
  /**
   * Originator breakdown rows, ranked by the `sort` metric (default `accepted`) descending. Empty when no messages were sent in the period.
   */
  readonly data: Array<SmsOriginatorStatsPoint>;
  /**
   * Total number of distinct originators with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped; raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Aggregate delivery and latency stats for a single destination country over the requested period.
 */
export type SmsCountryStatsPoint = {
  /**
   * The destination country this row aggregates, as an ISO 3166-1 alpha-2 code.
   */
  readonly country: string;
  readonly delivery: SmsDeliveryStats;
  readonly latency: SmsLatencyStats;
  /**
   * Per-bucket lifecycle counts for this country, using `trend_grain`. Includes only buckets with activity. Present when `include_trend=true`.
   */
  readonly trend?: Array<SmsStatsPoint>;
};

/**
 * Per-country breakdown for the requested period, ranked by the `sort` metric (default `accepted`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type SmsStatsByCountryResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: SmsStatsSummaryPeriod;
  /**
   * Country breakdown rows, ranked by the `sort` metric (default `accepted`) descending. Empty when no messages were sent in the period.
   */
  readonly data: Array<SmsCountryStatsPoint>;
  /**
   * Total number of distinct destination countries with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped; raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Aggregate delivery and latency stats for a single message category over the requested period.
 */
export type SmsCategoryStatsPoint = {
  /**
   * The category this row aggregates, as set at send time. `transactional` is one-to-one messaging triggered by a user action; `marketing` is bulk sending. New categories may be added over time.
   */
  readonly category: string;
  readonly delivery: SmsDeliveryStats;
  readonly latency: SmsLatencyStats;
  /**
   * Per-bucket lifecycle counts for this category, using `trend_grain`. Includes only buckets with activity. Present when `include_trend=true`.
   */
  readonly trend?: Array<SmsStatsPoint>;
};

/**
 * Per-category breakdown for the requested period, ranked by the `sort` metric (default `accepted`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type SmsStatsByCategoryResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: SmsStatsSummaryPeriod;
  /**
   * Category breakdown rows, ranked by the `sort` metric (default `accepted`) descending. Empty when no messages were sent in the period.
   */
  readonly data: Array<SmsCategoryStatsPoint>;
  /**
   * Total number of distinct categories with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped; raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Metric to rank breakdown rows by, applied descending. Shared by the breakdowns whose rows carry lifecycle counts only, with no derived rates to sort on.
 *
 */
export type SmsStatsLifecycleSortMetric =
  | "accepted"
  | "sent"
  | "delivered"
  | "undelivered"
  | "failed"
  | "rejected"
  | "expired";

/**
 * Delivery and latency statistics for one standardized failure reason over the requested period.
 */
export type SmsErrorCodeStatsPoint = {
  /**
   * Standardized failure reason this row aggregates. Matches the `error_code` message-list filter.
   */
  readonly error_code: SmsErrorCode;
  readonly delivery: SmsDeliveryStats;
  readonly latency: SmsLatencyStats;
  /**
   * Per-bucket lifecycle counts for this error code, using `trend_grain`. Includes only buckets with activity. Present when `include_trend=true`.
   */
  readonly trend?: Array<SmsStatsPoint>;
};

/**
 * Per-error-code breakdown for the requested period, ranked by the `sort` metric (default `failed`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type SmsStatsByErrorCodeResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: SmsStatsSummaryPeriod;
  /**
   * Error-code breakdown rows, ranked by the `sort` metric (default `failed`) descending. Empty when no delivery failures occurred in the period.
   */
  readonly data: Array<SmsErrorCodeStatsPoint>;
  /**
   * Total number of distinct error codes with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped; raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Aggregate delivery and latency stats for a single delivery carrier over the requested period.
 */
export type SmsCarrierStatsPoint = {
  /**
   * The delivery carrier this row aggregates, as resolved for the destination handset.
   */
  readonly carrier: string;
  readonly delivery: SmsDeliveryStats;
  readonly latency: SmsLatencyStats;
  /**
   * Per-bucket lifecycle counts for this carrier, using `trend_grain`. Includes only buckets with activity. Present when `include_trend=true`.
   */
  readonly trend?: Array<SmsStatsPoint>;
};

/**
 * Per-carrier breakdown for the requested period, ranked by the `sort` metric (default `accepted`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type SmsStatsByCarrierResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: SmsStatsSummaryPeriod;
  /**
   * Carrier breakdown rows, ranked by the `sort` metric (default `accepted`) descending. Empty when no messages were sent in the period.
   */
  readonly data: Array<SmsCarrierStatsPoint>;
  /**
   * Total number of distinct carriers with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped; raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Aggregate delivery and latency stats for a single tag (`name:value`) over the requested period.
 */
export type SmsTagStatsPoint = {
  /**
   * The tag this row aggregates, in `name:value` form. Each distinct name-and-value pair is its own row, and a message carrying several tags is counted once under each of them, so rows do not sum to the period total.
   *
   */
  readonly tag: string;
  readonly delivery: SmsDeliveryStats;
  readonly latency: SmsLatencyStats;
  /**
   * Per-bucket lifecycle-count series for this tag over the window, bucketed by `trend_grain`. Sparse, so only buckets with activity are present rather than zero-filled, unlike the daily and hourly series. Present only when `include_trend=true`.
   *
   */
  readonly trend?: Array<SmsStatsPoint>;
};

/**
 * Per-tag breakdown for the requested period, ranked by the `sort` metric (default `accepted`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type SmsStatsByTagResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: SmsStatsSummaryPeriod;
  /**
   * Tag breakdown rows, ranked by the `sort` metric (default `accepted`) descending. Empty when no tagged messages were sent in the period.
   */
  readonly data: Array<SmsTagStatsPoint>;
  /**
   * Total number of distinct tags with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped; raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * The number of messages that ended the requested period in a single lifecycle status. This transposes the lifecycle counts into one row per status, so it carries no rates or latency.
 */
export type SmsStatusStatsPoint = {
  /**
   * The lifecycle status this row counts. These are successive lifecycle stages. The `accepted` status was admitted for sending, `sent` was handed to the carrier, and `delivered` was confirmed by the carrier. The `undelivered`, `failed`, and `expired` statuses are failure outcomes. The `rejected` status was refused before a send attempt. Counted outcomes are a subset of the full message status vocabulary. The pre-send `scheduled`, cancellation `canceled`, and inbound-only `received` statuses are not send outcomes, so they never appear here.
   *
   */
  readonly status:
    | "accepted"
    | "sent"
    | "delivered"
    | "undelivered"
    | "failed"
    | "rejected"
    | "expired";
  /**
   * Distinct messages that reached this lifecycle status in the period, attributed to the message's send time rather than the event's own.
   */
  readonly count: number;
};

/**
 * Lifecycle-status breakdown for the requested period, ordered by message count descending. Statuses with no activity are omitted.
 */
export type SmsStatsByStatusResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: SmsStatsSummaryPeriod;
  /**
   * Status breakdown rows, one per lifecycle status with activity, ordered by count descending. Empty when no messages had activity in the period.
   */
  readonly data: Array<SmsStatusStatsPoint>;
  /**
   * Number of distinct lifecycle statuses with activity in the period (at most seven). Equal to the number of rows returned, since this breakdown is never capped.
   */
  readonly total: number;
};

/**
 * The change from the preceding period to the requested one. The `received_pct_change` field is a signed relative change, computed as `(current - previous) / previous`. A value of `0.5` means 50% higher, and `-0.2` means 20% lower. The field is null when the previous period received none.
 *
 */
export type SmsInboundStatsComparisonDelta = {
  /**
   * Relative change in received messages versus the previous period, as a signed fraction. Null when the previous period received none.
   */
  readonly received_pct_change: number | null;
};

/**
 * The received-message count for the equal-length, inclusive period ending immediately before the requested start, together with the change between the two periods. Present only when `compare=previous_period` is requested. The change is already computed, so a percentage difference needs no second request.
 *
 */
export type SmsInboundStatsComparison = {
  /**
   * Equal-length window ending immediately before the requested start.
   */
  period: SmsStatsSummaryPeriod;
  /**
   * Distinct messages received in the preceding period.
   */
  readonly received: number;
  readonly delta: SmsInboundStatsComparisonDelta;
};

/**
 * Total received messages over the requested period.
 *
 */
export type SmsInboundStatsSummaryResponse = {
  period: SmsStatsSummaryPeriod;
  /**
   * Distinct messages received in the period, counted by the time the carrier received them.
   */
  readonly received: number;
  readonly comparison?: SmsInboundStatsComparison;
};

/**
 * One time bucket of received-message counts, attributed by arrival time.
 */
export type SmsInboundStatsPoint = {
  /**
   * Start of the bucket this row covers, as a calendar day (YYYY-MM-DD) for the daily series or an hour boundary (RFC 3339) for the hourly one.
   */
  readonly bucket: string;
  /**
   * Distinct messages received in this bucket, counted by the time the carrier received them.
   */
  readonly received: number;
};

/**
 * Received-message time series. `period` echoes the range and bucket grain the server computed against; `data` is one row per bucket in chronological order.
 *
 */
export type SmsInboundStatsResponse = {
  period: SmsStatsSeriesPeriod;
  /**
   * One row per bucket (day or hour, per the grain) in the period, in chronological order. Buckets with no activity are included with a count of zero, so the series charts continuously without client-side gap handling.
   */
  readonly data: Array<SmsInboundStatsPoint>;
};

/**
 * Received-message volume for one country.
 *
 */
export type SmsInboundCountryStatsPoint = {
  /**
   * The country of the Bird number the messages arrived on, as an ISO 3166-1 alpha-2 code. This identifies where the message was received. It does not identify the sender's country.
   */
  readonly country: string;
  /**
   * Distinct messages received on numbers in this country during the period.
   */
  readonly received: number;
};

/**
 * Received-message volume broken down by country, ranked by volume.
 *
 */
export type SmsInboundStatsByCountryResponse = {
  period: SmsStatsSummaryPeriod;
  /**
   * One row per country with activity in the period, most messages first, capped at the requested `limit`. A country with no messages in the period is absent rather than zero-filled, because unlike a time bucket it is not part of a continuous axis.
   *
   */
  readonly data: Array<SmsInboundCountryStatsPoint>;
  /**
   * Total number of distinct countries the messages arrived in with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped; raise `limit` (up to 200) or narrow the window to see more.
   */
  readonly total: number;
};

/**
 * Received-message volume for one mobile operator.
 *
 */
export type SmsInboundOperatorStatsPoint = {
  /**
   * Mobile country code and mobile network code of the network the sending subscriber is on. The breakdown keys on this rather than on an operator name because the carrier reports a name only where a surcharge applies, which would leave most of the world in one unnamed bucket.
   */
  readonly mcc_mnc: string;
  /**
   * Distinct messages received from senders on this operator during the period.
   */
  readonly received: number;
};

/**
 * Received-message volume broken down by operator, ranked by volume.
 *
 */
export type SmsInboundStatsByOperatorResponse = {
  period: SmsStatsSummaryPeriod;
  /**
   * One row per operator with activity in the period, most messages first, capped at the requested `limit`. An operator with no messages in the period is absent rather than zero-filled, because unlike a time bucket it is not part of a continuous axis.
   *
   */
  readonly data: Array<SmsInboundOperatorStatsPoint>;
  /**
   * Total number of distinct sending operators with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped; raise `limit` (up to 200) or narrow the window to see more.
   */
  readonly total: number;
};

/**
 * Received-message volume for one of your numbers.
 *
 */
export type SmsInboundNumberStatsPoint = {
  /**
   * The Bird number the messages arrived on, in E.164, or the short code they were sent to. This is the same value the message resource exposes as `to`.
   */
  readonly number: string;
  /**
   * Distinct messages received on this number during the period.
   */
  readonly received: number;
};

/**
 * Received-message volume broken down by number, ranked by volume.
 *
 */
export type SmsInboundStatsByNumberResponse = {
  period: SmsStatsSummaryPeriod;
  /**
   * One row per number with activity in the period, most messages first, capped at the requested `limit`. A number with no messages in the period is absent rather than zero-filled, because unlike a time bucket it is not part of a continuous axis.
   *
   */
  readonly data: Array<SmsInboundNumberStatsPoint>;
  /**
   * Total number of distinct numbers with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped; raise `limit` (up to 200) or narrow the window to see more.
   */
  readonly total: number;
};

/**
 * Identifier of a number allocated to your workspace, as returned in the id field of `GET /v1/numbers`.
 */
export type AllocatedNumberId = string;

/**
 * An intelligence property you can add to a base phone number lookup.
 *
 * - `classification`: the property resolves `line_type` to its precise
 * allocated service (premium rate, satellite, machine-to-machine,
 * payphone) where the base lookup only distinguishes broad categories.
 * - `porting`: the property returns when the number last moved network and
 * its full porting record.
 * - `presence`: the property reports whether the number is currently live
 * on the network.
 * - `roaming`: the property reports whether it is roaming and on which
 * network.
 * - `sim_swap`: the property returns when its SIM last changed.
 * - `score`: the property returns a credibility score from 0 to 100.
 *
 * Each property you request is billed separately, and only when it is
 * delivered.
 *
 */
export type LookupProperty =
  "classification" | "porting" | "presence" | "roaming" | "sim_swap" | "score";

export type PhoneNumberLookupRequest = {
  /**
   * The phone number to look up, in international format: the country calling code, then the national number. The leading `+` is optional, and `00` works in its place, so `+31612345678`, `31612345678` and `0031612345678` are all the same number. A number written for dialling inside one country, with no country code, is rejected rather than guessed at.
   */
  phone_number: string;
  /**
   * Properties to add to the base lookup. Omit this field or send an empty
   * array to request only the base lookup.
   *
   * Each delivered property is billed in addition to the base lookup. A
   * property that could not be answered is returned with its status and is
   * not billed.
   *
   */
  type?: Array<LookupProperty>;
};

/**
 * The network a number belongs to.
 */
export type LookupNetworkInfo = {
  /**
   * The carrier's name, absent when the carrier could not be identified.
   */
  readonly carrier_name?: string | null;
  /**
   * The mobile country code, absent for a network that has none or could not be identified.
   */
  readonly mcc?: string | null;
  /**
   * The mobile network code, absent for a network that has none or could not be identified.
   */
  readonly mnc?: string | null;
};

/**
 * A notable characteristic of a number. `ported` means the number has moved
 * from the network that issued it to another one, so `network_info` and
 * `original_network_info` name different carriers.
 *
 * Open enum: more flags may be added over time, so treat an unrecognized value
 * as a future flag rather than an error.
 *
 */
export type LookupFlag = "ported" | (string & {});

/**
 * What kind of line the number is, as reported by the carrier platform.
 *
 * This is included in every base lookup, regardless of which properties you
 * request.
 *
 * - `unknown`: the carrier platform holds no classification for the
 * range.
 * - `other`: it holds a classification with no equivalent here.
 * - `m2m`: a range reserved for machine-to-machine traffic, belonging to no
 * individual subscriber.
 *
 * For the allocated service of the range at finer precision, request the
 * `classification` property. That answers from a different source, with its own
 * wider vocabulary, and is reported separately so you can always tell the two
 * apart.
 *
 */
export type LookupLineType =
  | "mobile"
  | "fixed_line"
  | "voip"
  | "toll_free"
  | "premium_rate"
  | "satellite"
  | "pager"
  | "payphone"
  | "m2m"
  | "service"
  | "other"
  | "unknown";

/**
 * How a requested property resolved.
 *
 * - `ok`: the property was answered and its value is in the response.
 * - `unavailable`: no answer arrived, so the property adds nothing: its
 * block is `null`, or for `classification`, `line_type` retains the value
 * from the base lookup. The property is not billed.
 * - `inconclusive`: an answer arrived but does not resolve the
 * property, either because the number is outside the coverage of the data
 * behind it or because the source returned a value this property does not
 * report. It is a real answer rather than a missing one, and it is not
 * billed either.
 *
 * Open enum: further statuses may be added over time, so treat an unrecognized
 * value as a future one rather than an error. Only `ok` carries a value and only
 * `ok` is billed, so branching on `ok` and treating everything else as "not
 * answered" stays correct however the vocabulary grows.
 *
 */
export type LookupPropertyStatus =
  "ok" | "unavailable" | "inconclusive" | (string & {});

/**
 * The allocated service of the number's range, at the precision the
 * intelligence source publishes it.
 *
 * This is a finer vocabulary than `line_type`, which reports what the carrier
 * platform alone can tell. Some values have no carrier equivalent. For example,
 * a number the carrier calls `service` may be classified as `premium_rate`,
 * `shared_cost`, `universal_access`, or a voicemail platform. Where the fields
 * overlap, they remain independent results rather than one refining the other.
 *
 * Three values in particular have no carrier-side concept at all:
 *
 * - `m2m` is a range reserved for machine-to-machine traffic, belonging to no
 * individual subscriber.
 * - `national_rate` is a non-geographic landline number charged above the
 * local rate.
 * - `fixed_line_or_mobile` is a range a country allocates so a number can port
 * between the two.
 *
 */
export type LookupClassificationValue =
  | "mobile"
  | "fixed_line"
  | "fixed_line_or_mobile"
  | "voip"
  | "toll_free"
  | "premium_rate"
  | "shared_cost"
  | "local_rate"
  | "national_rate"
  | "personal_number"
  | "universal_access"
  | "satellite"
  | "pager"
  | "payphone"
  | "m2m"
  | "isp"
  | "vpn"
  | "voice_mail"
  | "calling_cards"
  | "short_codes"
  | "service"
  | "other";

/**
 * The allocated service of the number's range. Returned when you request the
 * `classification` property.
 *
 * This sits beside `line_type` rather than replacing it, so you can always see
 * which source answered. The `line_type` property is included in the base lookup
 * and comes from the carrier platform. The `classification` property is
 * separately billed and comes from an intelligence source.
 *
 */
export type LookupClassification = {
  readonly status: LookupPropertyStatus;
  /**
   * The allocated service of the range. Present only when `status` is `ok`.
   */
  readonly value?: LookupClassificationValue;
};

/**
 * Whether the number is live on its network right now. Returned when you
 * request the `presence` property.
 *
 * The result reflects a real-time query to the network where the number is
 * registered.
 *
 */
export type LookupPresence = {
  readonly status: LookupPropertyStatus;
  /**
   * Whether the number is registered on a network and able to receive traffic. A `false` value means the network answered and reported the number as currently unreachable. This differs from the API being unable to find out. Present only when `status` is `ok`.
   *
   */
  readonly reachable?: boolean;
};

/**
 * Whether the number is roaming, and on which network. Returned when you request the `roaming` property.
 */
export type LookupRoaming = {
  readonly status: LookupPropertyStatus;
  /**
   * Whether the number is currently roaming outside its home network. Present only when `status` is `ok`.
   */
  readonly is_roaming?: boolean;
  /**
   * The mobile country code of the visited network. Absent when the number is not roaming or the visited network is not reported.
   */
  readonly mcc?: string | null;
  /**
   * The mobile network code of the visited network. Absent when the number is not roaming or the visited network is not reported.
   */
  readonly mnc?: string | null;
};

/**
 * When the number's SIM last changed. Returned when you request the `sim_swap` property.
 */
export type LookupSimSwap = {
  readonly status: LookupPropertyStatus;
  /**
   * When the SIM was last changed. Absent when only a recency band is known.
   */
  readonly last_swapped_at?: string | null;
  /**
   * The lower bound, in days, of how long ago the SIM was last changed. Networks that do not release an exact date report a band instead; absent when no lower bound is known.
   */
  readonly min_days?: number | null;
  /**
   * The upper bound, in days, of how long ago the SIM was last changed. Absent when no upper bound is known; with a lower bound present, that means the change was at least `min_days` ago.
   */
  readonly max_days?: number | null;
};

/**
 * One recorded move of a number between networks.
 */
export type LookupPortingEvent = {
  /**
   * When the move was recorded, `null` when the record carries no date.
   */
  readonly occurred_at: string | null;
  /**
   * What the record describes, as the number's registry reports it. Registries use their own short codes rather than a shared vocabulary, so treat this as a label to display rather than a value to branch on.
   */
  readonly action: string | null;
};

/**
 * Whether the number has ever moved network, when it last did, and its full porting record. Returned when you request the `porting` property. The base lookup only reports whether the number has ever ported, through the `ported` flag.
 *
 */
export type LookupPorting = {
  readonly status: LookupPropertyStatus;
  /**
   * Whether the number has ever moved network. `false` is a positive finding rather than a lack of one: the registry was consulted and holds no move for this number. Present only when `status` is `ok`.
   *
   */
  readonly ported?: boolean;
  /**
   * When the number last moved network. Absent when it has never ported or when no date is on record.
   */
  readonly last_ported_at?: string | null;
  /**
   * Whether `last_ported_at` is an approximation. Some registries record the period of a move without its exact day.
   */
  readonly last_ported_at_is_approximate?: boolean;
  /**
   * Every move on record, oldest first. Absent when the number has never ported or when its registry publishes no history.
   */
  readonly history?: Array<LookupPortingEvent>;
};

/**
 * A credibility score for the number. Returned when you request the `score` property.
 */
export type LookupScore = {
  readonly status: LookupPropertyStatus;
  /**
   * Credibility from 0 (low) to 100 (high). A low score means the number looks less credible than a typical subscriber line in the same range. Treat it as one signal instead of a verdict. It is a composite and is not derivable from the other properties. Present only when `status` is `ok`.
   *
   */
  readonly value?: number;
};

/**
 * Information about a phone number.
 *
 * The number, its flags, and its line type are included in the base lookup and
 * are always present. The country and two networks are present when identified.
 * Each property you request through `type` is returned in a block with the same
 * name and its own `status`. A property you did not request is absent. A
 * property that could not be answered is present with only its `status`. Each
 * requested property is billed only when its status is `ok`.
 *
 * Fields with no value are omitted rather than returned as `null`.
 *
 */
export type PhoneNumberLookup = {
  /**
   * The number that was looked up, in E.164 format.
   */
  readonly phone_number: string;
  /**
   * The ISO 3166-1 alpha-2 country of the number. Absent when the number belongs to no single country, as a non-geographic range does.
   */
  readonly country_code?: CountryCode | null;
  /**
   * The network that serves the number today. Absent when no network could be identified.
   */
  readonly network_info?: LookupNetworkInfo | null;
  /**
   * The network that issued the number's range. It differs from `network_info` when the number has been ported. Absent when the issuing network could not be identified.
   */
  readonly original_network_info?: LookupNetworkInfo | null;
  /**
   * Notable characteristics of the number. Empty when none apply.
   */
  readonly flags: Array<LookupFlag>;
  readonly line_type: LookupLineType;
  /**
   * The allocated service of the number's range. Absent unless you requested the `classification` property.
   */
  readonly classification?: LookupClassification;
  /**
   * Whether the number is live on its network. Absent unless you requested the `presence` property.
   */
  readonly presence?: LookupPresence;
  /**
   * Whether the number is roaming. Absent unless you requested the `roaming` property.
   */
  readonly roaming?: LookupRoaming;
  /**
   * When the number's SIM last changed. Absent unless you requested the `sim_swap` property.
   */
  readonly sim_swap?: LookupSimSwap;
  /**
   * The number's porting record. Absent unless you requested the `porting` property.
   */
  readonly porting?: LookupPorting;
  /**
   * The number's credibility score. Absent unless you requested the `score` property.
   */
  readonly score?: LookupScore;
};

export type EmailLookupRequest = {
  /**
   * The email address to look up. Send it exactly as you hold it. The part before the `@` is case-sensitive, so the API does not lowercase it. A display-name form such as `Aisha <aisha@example.com>` is rejected rather than unwrapped.
   *
   */
  email: string;
};

/**
 * The verdict on the address, and the one field to decide on.
 *
 * - `valid`: the address exists and accepts mail.
 * - `neutral`: it could not be confirmed either way, usually because the
 * receiving domain answers every recipient the same.
 * - `risky`: it probably accepts mail but is likelier than most to
 * bounce or complain. Examples include role, disposable, and low-reputation
 * addresses.
 * - `undeliverable`: it does not accept mail, and `reason` says why.
 * - `typo`: the address looks misspelled, and `did_you_mean` contains
 * the correction.
 *
 * Open enum: further verdicts may be added over time, so treat an unrecognized
 * value as a future one rather than an error. Branch on the values you know and
 * fall back on `delivery_confidence`, which is always present and always
 * comparable.
 *
 */
export type EmailLookupResult =
  "valid" | "neutral" | "risky" | "undeliverable" | "typo" | (string & {});

/**
 * A notable characteristic of an email address.
 *
 * - `role`: it addresses a function rather than a person (`support@`,
 * `info@`). Replies and consent are therefore ambiguous, and complaints are
 * more likely.
 * - `disposable`: it belongs to a throwaway-address provider and
 * typically stops existing.
 * - `free_provider`: it belongs to a consumer mailbox provider such as
 * Gmail or Outlook.com. This is ordinary for consumer mail and a signal when
 * you expected a business address.
 *
 * Open enum: more flags may be added over time, so treat an unrecognized value
 * as a future flag rather than an error.
 *
 */
export type EmailLookupFlag =
  "role" | "disposable" | "free_provider" | (string & {});

/**
 * Why an address cannot receive mail.
 *
 * - `invalid_syntax`: the address is malformed.
 * - `invalid_domain`: the domain does not accept mail.
 * - `invalid_recipient`: the domain accepts mail but this mailbox does
 * not exist.
 *
 * Open enum: further reasons may be added over time, so treat an unrecognized
 * value as a future one rather than an error. `result` is what to branch on; this
 * field explains it.
 *
 */
export type EmailLookupReason =
  "invalid_syntax" | "invalid_domain" | "invalid_recipient" | (string & {});

/**
 * Assessment of whether an email address accepts mail, the confidence and reason for that
 * assessment, and a suggested correction when the address appears misspelled.
 *
 * `result` is the field to decide on; `delivery_confidence` grades it, and
 * `flags` describes the address itself rather than its deliverability, so a
 * perfectly valid address can still have `role` or `disposable`.
 *
 * Fields without resolved values are omitted rather than sent as null. Every
 * field present in the response was resolved.
 *
 */
export type EmailLookup = {
  /**
   * The address that was looked up, exactly as you sent it.
   */
  readonly email: string;
  /**
   * Whether the address is well-formed and its domain is set up to receive mail at all. It says nothing about the mailbox itself, so a `valid` domain with no such mailbox is `true` here and `undeliverable` in `result`.
   */
  readonly valid: boolean;
  readonly result: EmailLookupResult;
  /**
   * How likely mail to this address is to be delivered, from 0 (certain not to be) to 100 (certain to be). Read it alongside `result` rather than instead of it, because the same score can sit under `neutral` or `risky` for different reasons.
   */
  readonly delivery_confidence: number;
  /**
   * Notable characteristics of the address. Empty when none apply.
   */
  readonly flags: Array<EmailLookupFlag>;
  /**
   * Why the address cannot receive mail. Absent unless `result` is `undeliverable`.
   */
  readonly reason?: EmailLookupReason;
  /**
   * The address this one looks like a misspelling of. Absent unless a correction was found, which in practice means `result` is `typo`. Offer it to whoever typed the original rather than sending to it unasked, because it is a guess and the address they meant may be neither one.
   */
  readonly did_you_mean?: string;
};

export type VerificationId = string;

/**
 * Why a verification session reached its final state without succeeding: `attempts_exhausted` (too many incorrect passcodes), `ttl_elapsed` (the time window elapsed before a correct passcode), or `undeliverable` (no planned channel could deliver a passcode, so the recipient never had one to submit). Open enum: new reasons may be added over time, so treat any unrecognized value as a future reason rather than an error.
 */
export type VerificationTerminalReason =
  "attempts_exhausted" | "ttl_elapsed" | "undeliverable" | (string & {});

/**
 * The recipient to verify. Provide an `email`, a `phone_number`, or both; at least one is required. The addresses also identify the verification: a check must supply exactly the set used on the create call, so a verification created with both addresses is not found by either one alone.
 *
 */
export type VerificationTo = {
  /**
   * The recipient's email address. Case does not matter; the address is lowercased before use.
   */
  email?: string;
  /**
   * The recipient's phone number in E.164 format, with the leading `+` and country code (for example `+15551234567`). A number in any other format is rejected as an invalid recipient (`422`).
   */
  phone_number?: string;
};

/**
 * The channel a passcode is delivered over. Open enum: new channels may be added over time, so treat any unrecognized value as a future channel rather than an error.
 */
export type VerificationChannel =
  "email" | "sms" | "whatsapp" | "telegram" | (string & {});

export type VerificationChannelEntry = {
  channel: VerificationChannel;
};

/**
 * Why a passcode send did not deliver:
 *
 * - `carrier_rejected`: The SMS carrier rejected the send.
 * - `hard_bounce`: The email permanently bounced.
 * - `soft_bounce`: The email temporarily bounced, such as when a mailbox is full.
 * - `undelivered`: The channel reported a generic delivery failure.
 * - `channel_unavailable`: The channel could not be used, so the verification
 * moved to the next channel.
 * - `channel_disabled`: Sending on the channel is temporarily disabled, so the
 * verification moved to the next channel.
 * - `delivery_timeout`: No delivery confirmation arrived before the channel's
 * timeout, so the verification moved to the next channel.
 * - `not_billable`: The send could not be charged, so it was never handed to the
 * channel. Usually the workspace balance is too low to cover it. Topping up
 * the balance is what clears this.
 *
 * New reasons may be added over time. Treat unrecognized values as reasons added
 * later rather than errors.
 */
export type VerificationAttemptFailureReason =
  | "carrier_rejected"
  | "hard_bounce"
  | "soft_bounce"
  | "undelivered"
  | "channel_unavailable"
  | "channel_disabled"
  | "delivery_timeout"
  | "not_billable"
  | (string & {});

/**
 * Meta's content classification for a template.
 *
 * - `authentication`: delivers one-time passcodes.
 * - `utility`: delivers transaction-triggered updates (receipts, order status).
 * - `marketing`: carries promotional content.
 *
 * The category determines the sender number and price. This is an open enum.
 * Accept unrecognized values.
 *
 */
export type WhatsAppTemplateCategory =
  "authentication" | "utility" | "marketing" | (string & {});

export type Verification = {
  readonly id: VerificationId;
  /**
   * The verification's current state:
   *
   * - `pending`: Awaiting a correct passcode.
   * - `verified`: A correct passcode was submitted.
   * - `failed`: The verification cannot be completed. Either too many
   * incorrect passcodes were submitted, or no planned channel could
   * deliver one. Read `reason` to tell those apart.
   * - `expired`: The validity window elapsed before a correct passcode.
   * - `canceled`: The verification was canceled before completion.
   * - `blocked`: A fraud or abuse control stopped the verification.
   */
  readonly status:
    "pending" | "verified" | "failed" | "expired" | "canceled" | "blocked";
  /**
   * Why the verification reached its final state, or `null` while `pending` and once `verified`. See the enum for the values it can take.
   */
  readonly reason?: VerificationTerminalReason | null;
  readonly to: VerificationTo;
  /**
   * The channels this verification uses to deliver the passcode, in attempt order: the first entry is tried first and later entries are fallbacks. An email recipient is verified over email; a phone recipient is verified over the phone channels enabled for its destination country, in the order that country's configuration sets.
   */
  readonly channels: Array<VerificationChannelEntry>;
  /**
   * The channel the most recent passcode was sent on, or `null` before the first send. Open enum; new channels may be added over time, so treat any unrecognized value as a future channel rather than an error.
   */
  readonly last_channel?: string | null;
  /**
   * The key/value pairs attached when the verification was created.
   */
  readonly metadata?: {
    [key: string]: unknown;
  };
  /**
   * When the verification expires if no correct passcode is submitted first. After this time its status reports `expired`.
   */
  readonly expires_at: string;
  /**
   * When the verification was completed, or `null` if it is not yet verified.
   */
  readonly verified_at?: string | null;
} & Timestamps;

/**
 * Per-request overrides applied to this verification only.
 */
export type VerificationOptions = {
  /**
   * Passcode length for this verification. Omit to use the configured length.
   */
  code_length?: number;
  /**
   * Reorder or narrow the delivery channels for this request. List channel names in the order to try them; a channel you omit is not used for this request, and a channel not already enabled for the recipient is ignored. A list that leaves no usable channel fails the request with `422`. Omit the field to use the configured order.
   */
  channels?: Array<VerificationChannel>;
};

export type VerificationCreateRequest = {
  to: VerificationTo;
  options?: VerificationOptions;
  /**
   * Optional key/value pairs to attach to the verification, for example a correlation id. Returned on the verification.
   */
  metadata?: {
    [key: string]: unknown;
  };
};

export type VerificationCheckRequest = {
  to: VerificationTo;
  /**
   * The passcode the recipient received. Passcodes are numeric; submit the digits exactly as delivered. An incorrect value is a normal `200` outcome with `success: false`. It does not return an error.
   */
  code: string;
};

export type VerificationCheckResult = {
  /**
   * Whether the submitted passcode verified this verification. `true` means the passcode was correct and the verification is now complete; `false` means it did not verify, and `reason` says why. A verification that has already reached a final state is no longer checkable and returns `404`.
   */
  readonly success: boolean;
  /**
   * Why the check did not succeed:
   *
   * - `incorrect_code`: The passcode was wrong and attempts remain.
   * - `expired`: The validity window elapsed.
   * - `attempts_exhausted`: Too many incorrect attempts were submitted.
   *
   * `null` when `success` is `true`. Treat unrecognized values as reasons added
   * later.
   */
  readonly reason?: string | null;
  verification: Verification;
  /**
   * The number of check attempts left while the verification is still pending, or `null` once it has reached a final state.
   */
  readonly attempts_remaining?: number | null;
};

export type VerificationNextChannelRequest = {
  to: VerificationTo;
};

export type DomainId = string;

/**
 * Delivery status:
 *
 * - `accepted`: Accepted and queued for sending.
 * - `sent`: Handed to the WhatsApp network.
 * - `delivered`: Confirmed as delivered to the recipient's device.
 * - `failed`: Permanently failed.
 * - `rejected`: Refused before sending and not charged.
 * - `received`: Received as an inbound message.
 * - `scheduled`: Reserved and not returned.
 * - `canceled`: Reserved and not returned.
 *
 * Read receipts appear in `read_at` and `whatsapp.read` events.
 *
 */
export type WhatsAppMessageStatus =
  | "scheduled"
  | "accepted"
  | "sent"
  | "delivered"
  | "failed"
  | "rejected"
  | "canceled"
  | "received";

export type WhatsAppMessageId = string;

/**
 * Sender or recipient of a WhatsApp message: a phone number, a business-scoped user ID, or both.
 */
export type WhatsAppAddress = {
  /**
   * Phone number in E.164 format, when known.
   */
  phone_number?: string;
  /**
   * Business-scoped user ID, Meta's identifier for the WhatsApp user. Present only on the WhatsApp-user side of the message.
   *
   */
  bsuid?: string;
};

/**
 * The kind of value a template parameter carries, which follows the block it fills. The `text` type is a plain string substituted into a placeholder. This includes a coupon button's code, which the recipient copies from the button. The `image`, `video`, `gif`, and `document` types carry a media header's file in `url`. Each matches its header's `format`. The `location` type fills a location header and carries a point on the map. Open enum: more kinds may be added over time.
 *
 */
export type WhatsAppTemplateParameterType =
  "text" | "image" | "video" | "gif" | "document" | "location" | (string & {});

/**
 * A free-form location to send: a point on the map the recipient can open in their maps app. Deliverable only inside an open 24-hour customer service window; outside one, send a template instead.
 *
 */
export type WhatsAppLocationSend = {
  /**
   * Latitude in decimal degrees.
   */
  latitude: number;
  /**
   * Longitude in decimal degrees.
   */
  longitude: number;
  /**
   * Name of the place, shown above the address.
   */
  name?: string;
  /**
   * Street address of the place. Shown only when `name` is also set.
   */
  address?: string;
};

export type WhatsAppMessageTemplateComponentParameter = {
  /**
   * The kind of value this parameter carries, which decides which of the fields below to send.
   */
  type: WhatsAppTemplateParameterType;
  /**
   * The value substituted into the placeholder, as a plain string. Send it on a `text` parameter.
   */
  text?: string;
  /**
   * Public `https` URL of the file a media header shows. Send it on an `image`, `video`, `gif` or `document` parameter. WhatsApp fetches it at send time, so it must still be reachable then, the same way a free-form media message's `url` must.
   *
   */
  url?: string;
  /**
   * The point on the map a location header opens. Send it on a `location` parameter.
   */
  location?: WhatsAppLocationSend;
  /**
   * Required when the template declares named parameters: the placeholder this value fills (for example `first_name`), matching exactly one of the names the template declares. Name every parameter in that case; order does not matter once names are supplied. Omit this field for a positional template, which takes its values in `{{n}}` order instead. Sending the wrong set of names, or leaving one out that the template requires, returns a `422` `WhatsAppTemplateParameterMismatch`.
   *
   */
  name?: string;
};

/**
 * The values that fill one block of one carousel card.
 */
export type WhatsAppMessageTemplateCardComponent = {
  /**
   * Which part of the card this fills in.
   *
   * - `header`: the card's image or video.
   * - `body`: its text.
   * - `button`: a button's variable.
   *
   */
  type: string;
  /**
   * The values that fill this part's placeholders, in placeholder order.
   */
  parameters?: Array<WhatsAppMessageTemplateComponentParameter>;
};

/**
 * The values that fill one card of a carousel. Cards fill in the order the template was approved with, so send one entry per card and keep them in that order.
 *
 */
export type WhatsAppMessageTemplateCard = {
  /**
   * The values that fill this card's blocks.
   */
  components: Array<WhatsAppMessageTemplateCardComponent>;
};

export type WhatsAppMessageTemplateComponent = {
  /**
   * Which part of the template this fills in.
   *
   * - `body`: the main text.
   * - `button`: a button's variable.
   * - `header`: the header's text, media or location.
   * - `carousel`: the cards.
   *
   */
  type: string;
  /**
   * The values that fill this part's placeholders. A positional template takes them in `{{n}}` placeholder order; a template with named parameters requires each parameter's `name` to match one the template declares, and order then carries no meaning. Send it on every part except `carousel`, which carries its values on `cards`. Send no `button` part at all for a button that takes no value, such as a `quick_reply` or `request_contact_info` button, or a `url` button whose address has no placeholder: a part the template has no slot for is refused here, before the message is sent and charged.
   *
   */
  parameters?: Array<WhatsAppMessageTemplateComponentParameter>;
  /**
   * The values that fill each card of a carousel. Send it only on a `carousel` part. A carousel sends exactly the number of cards its template was approved with, so every card needs an entry.
   *
   */
  cards?: Array<WhatsAppMessageTemplateCard>;
};

/**
 * The template a message was sent from. On reads `slug`, `language`, `category`, and `components` are always present; `components` is an empty array for an authentication template (the filled-in values, for example a verification code, are never returned).
 *
 */
export type WhatsAppMessageTemplate = {
  /**
   * The template's stable handle (for example `bird_otp`).
   */
  readonly slug: TemplateSlug;
  /**
   * Content classification applied to messages sent from this template.
   */
  readonly category: WhatsAppTemplateCategory;
  /**
   * The canonical BCP-47 tag of the template variant that was sent.
   */
  readonly language: LanguageTag;
  /**
   * The values that filled the template's placeholders. Empty for an authentication template, whose content is never returned.
   *
   */
  readonly components: Array<WhatsAppMessageTemplateComponent>;
};

/**
 * Text content of a WhatsApp message.
 */
export type WhatsAppText = {
  /**
   * The message text.
   */
  body: string;
};

export type WhatsAppFileId = string;

/**
 * Fields shared by every media content object on a WhatsApp message.
 */
export type WhatsAppMedia = {
  /**
   * ID of the stored file, to pass as `media_id` when fetching it. Absent on an outbound message, whose file we never stored.
   *
   */
  readonly id?: WhatsAppFileId;
  /**
   * Where to fetch the media. On an inbound message this is a Bird URL you fetch with your API key; it is absent when the file could not be retrieved from WhatsApp. It stays populated after the stored bytes expire, and the link returns `410` from then on. On an outbound message it is the URL the sender supplied, whose availability is the sender's to guarantee.
   *
   */
  url?: string;
  /**
   * Media type WhatsApp reported for the file, for example `image/jpeg`. Absent on outbound messages.
   *
   */
  mime_type?: string;
};

/**
 * Image content of a WhatsApp message.
 *
 */
export type WhatsAppImage = WhatsAppMedia & {
  /**
   * Text shown beneath the image. Absent when the sender wrote none.
   */
  caption?: string;
};

/**
 * Video content of a WhatsApp message.
 *
 */
export type WhatsAppVideo = WhatsAppMedia & {
  /**
   * Text shown beneath the video. Absent when the sender wrote none.
   */
  caption?: string;
};

/**
 * Audio content of a WhatsApp message.
 *
 */
export type WhatsAppAudio = WhatsAppMedia & {
  /**
   * Whether this is a voice note rather than an attached audio file. A voice note auto-downloads in the WhatsApp client and can be transcribed for the recipient.
   *
   */
  voice?: boolean;
};

/**
 * Sticker content of a WhatsApp message.
 *
 */
export type WhatsAppSticker = WhatsAppMedia & {
  /**
   * Whether the sticker is animated. Absent on an outbound message.
   *
   */
  animated?: boolean;
};

/**
 * Document content of a WhatsApp message.
 *
 */
export type WhatsAppDocument = WhatsAppMedia & {
  /**
   * Text shown beneath the document. Absent when the sender wrote none.
   */
  caption?: string;
  /**
   * The sender's own name for the file.
   */
  filename?: string;
};

/**
 * Location content of a WhatsApp message: a point on the map the recipient can open in their maps app.
 *
 */
export type WhatsAppLocation = {
  /**
   * Latitude in decimal degrees.
   */
  latitude?: number;
  /**
   * Longitude in decimal degrees.
   */
  longitude?: number;
  /**
   * Name of the place. Absent when the sender shared a plain pin.
   */
  name?: string;
  /**
   * Street address of the place. Shown only when `name` is also set.
   */
  address?: string;
  /**
   * Link to the place, which WhatsApp includes mainly for business locations. Present on an inbound message when the sender's client supplied one, and absent on a message you sent, since sending a location does not support this field.
   *
   */
  url?: string;
};

/**
 * The contact's name, in the parts their device supplied. Every part is optional: WhatsApp sends what the card holds and omits the rest.
 *
 */
export type WhatsAppContactName = {
  /**
   * The whole name as the contact's device renders it.
   */
  formatted_name?: string;
  first_name?: string;
  middle_name?: string;
  last_name?: string;
  prefix?: string;
  suffix?: string;
};

/**
 * Where the contact works, as their card records it.
 */
export type WhatsAppContactOrg = {
  company?: string;
  department?: string;
  title?: string;
};

/**
 * One phone number on a shared contact card.
 */
export type WhatsAppContactPhone = {
  /**
   * The number as the card holds it, normalized to E.164 where we can parse it. A card is whatever the contact's device stored, so a number that no country's numbering plan accepts, an extension among them, is passed through exactly as it arrived rather than dropped. Parse defensively: most values are E.164 and none is guaranteed to be.
   *
   */
  phone_number?: string;
  /**
   * The label the contact's device attached, for example `CELL`, `Home` or `iPhone`. Free text passed through verbatim: WhatsApp declares no vocabulary here and does not normalize the casing, so neither do we.
   *
   */
  type?: string;
};

/**
 * One email address on a shared contact card.
 */
export type WhatsAppContactEmail = {
  email?: string;
  /**
   * The label the contact's device attached, for example `Personal` or `Work`. Free text passed through verbatim.
   *
   */
  type?: string;
};

/**
 * One website on a shared contact card.
 */
export type WhatsAppContactUrl = {
  /**
   * The address as the card holds it, which is often bare rather than a full URL, so it is passed through as text rather than validated.
   *
   */
  url?: string;
  /**
   * The label the contact's device attached, for example `Company`. Free text passed through verbatim.
   *
   */
  type?: string;
};

/**
 * One postal address on a shared contact card.
 */
export type WhatsAppContactAddress = {
  street?: string;
  city?: string;
  state?: string;
  zip?: string;
  country?: string;
  /**
   * The country as the card holds it, left exactly as WhatsApp sent it: it describes a postal address rather than a routing destination.
   *
   */
  country_code?: string;
  /**
   * The label the contact's device attached, for example `Home`. Free text passed through verbatim.
   *
   */
  type?: string;
};

/**
 * A contact card the contact shared, either by tapping a button that asked for their number or by sending a card from their address book. Inbound only.
 * Nothing here is required. WhatsApp sends the parts the card holds and omits the rest, and a card that arrives with only an `origin` is still meaningful, so an empty card reads back empty rather than being dropped.
 *
 */
export type WhatsAppContactCard = {
  /**
   * Why the card arrived. `contact_request` means the contact tapped a button this workspace sent asking for their number, which is the only signal that the message answers that ask; `other` means they shared a card in the chat. Open enum: treat an unrecognized value as a way of sharing added since.
   *
   */
  origin?: string;
  /**
   * The contact's card in vCard format. WhatsApp sends it on a card shared in the chat and omits it on a button tap, which carries the number alone.
   *
   */
  vcard?: string;
  /**
   * The contact's name, when the card carries one.
   */
  name?: WhatsAppContactName;
  /**
   * Where the contact works, when the card carries it.
   */
  org?: WhatsAppContactOrg;
  /**
   * The contact's birthday, which WhatsApp sends as `YYYY-MM-DD`. Passed through as text rather than typed as a date: the value comes off the contact's own device unvalidated, and a card we could not parse would otherwise have to lose the field or fail the whole read.
   *
   */
  birthday?: string;
  /**
   * The numbers on the card. A button tap carries the contact's own number here, which is the point of asking.
   *
   */
  phone_numbers?: Array<WhatsAppContactPhone>;
  emails?: Array<WhatsAppContactEmail>;
  urls?: Array<WhatsAppContactUrl>;
  addresses?: Array<WhatsAppContactAddress>;
};

/**
 * A message whose content we do not model, named so it is visible in the message log rather than arriving empty. Inbound only.
 *
 */
export type WhatsAppUnsupported = {
  /**
   * The WhatsApp content type we did not model. `unsupported` is not a placeholder here: WhatsApp reports its own `unsupported` type for a message its own clients cannot render, and that arrives as this value. Open enum: WhatsApp adds content types over time, so treat an unrecognized value as a future type rather than an error.
   *
   */
  type: string;
};

/**
 * Standardized failure reason:
 *
 * - `insufficient_balance`: The workspace wallet could not fund the send.
 * - `price_not_found`: No price was configured for the destination and template.
 * - `internal_error`: An unexpected service failure occurred.
 * - `undeliverable`: The recipient could not be reached.
 * - `service_window_expired`: The 24-hour service window closed; send a template.
 * - `rate_limited`: The send was throttled.
 * - `recipient_suppressed`: The recipient is on the workspace suppression list.
 * - `media_rejected`: WhatsApp could not fetch the media URL, or refused the file it found there; `description` carries its reason.
 *
 * This is an open enum. Accept unrecognized values.
 *
 */
export type WhatsAppErrorCode =
  | "insufficient_balance"
  | "price_not_found"
  | "internal_error"
  | "undeliverable"
  | "service_window_expired"
  | "rate_limited"
  | "recipient_suppressed"
  | "media_rejected"
  | (string & {});

/**
 * Failure detail for a message that could not be delivered or was rejected.
 */
export type WhatsAppError = {
  code: WhatsAppErrorCode;
  /**
   * Human-readable explanation of the failure.
   */
  readonly description: string;
  /**
   * Raw error code from the WhatsApp Cloud API, when available, for low-level debugging.
   */
  readonly meta_error_code?: string | null;
  /**
   * When the failure occurred.
   */
  readonly occurred_at: string;
} | null;

export type WhatsAppMessage = {
  /**
   * ID of the message, assigned when the send is accepted. Pass it as `message_id` to the get-message and list-events endpoints.
   *
   */
  readonly id: WhatsAppMessageId;
  /**
   * Whether the message was sent by the business (`outbound`) or received from the contact (`inbound`).
   */
  readonly direction: "outbound" | "inbound";
  /**
   * Sender of the message. On outbound messages, the business number it was sent from; on inbound, the WhatsApp contact.
   */
  readonly from: WhatsAppAddress;
  /**
   * Recipient of the message. On outbound messages, the WhatsApp contact; on inbound, the business number.
   */
  readonly to: WhatsAppAddress;
  /**
   * The template the message was sent from. For authentication templates the filled-in values are not returned.
   */
  readonly template?: WhatsAppMessageTemplate;
  /**
   * Text the message carried.
   */
  readonly text?: WhatsAppText;
  /**
   * Image the message carried.
   */
  readonly image?: WhatsAppImage;
  /**
   * Video the message carried.
   */
  readonly video?: WhatsAppVideo;
  /**
   * Audio the message carried.
   */
  readonly audio?: WhatsAppAudio;
  /**
   * Sticker the message carried.
   */
  readonly sticker?: WhatsAppSticker;
  /**
   * Document the message carried.
   */
  readonly document?: WhatsAppDocument;
  /**
   * Location the message carried.
   */
  readonly location?: WhatsAppLocation;
  /**
   * Contact cards the contact shared, either by tapping a button that asked for their number or by sending a card from their address book. Inbound only: sending a contact card is not supported.
   *
   */
  readonly contact_cards?: Array<WhatsAppContactCard>;
  /**
   * Set when the contact sent content we do not model, naming the WhatsApp content type so the message is not silently empty. Inbound only.
   *
   */
  readonly unsupported?: WhatsAppUnsupported;
  readonly status: WhatsAppMessageStatus;
  /**
   * Failure detail for a message that did not reach the recipient. Present only when the message failed.
   */
  last_error?: WhatsAppError;
  /**
   * When the message was accepted for delivery.
   */
  readonly created_at: string;
  /**
   * When the message was handed to the WhatsApp network. Null until then.
   */
  readonly sent_at?: string | null;
  /**
   * When delivery was confirmed. Null until then.
   */
  readonly delivered_at?: string | null;
  /**
   * When the message was read by the recipient. Null until then.
   */
  readonly read_at?: string | null;
  /**
   * What the message cost, split into Bird's charge and any third-party fees passed through. Null on an inbound message, which is never priced, on an outbound message that has not been priced yet, and on one rejected before pricing. The rate depends on the message category and the recipient's country.
   */
  readonly cost?: MessageCost;
  /**
   * Structured `{name, value}` filter labels applied to this message.
   */
  tags?: Array<Tag>;
  /**
   * Arbitrary JSON metadata stored on the message.
   */
  metadata?: {
    [key: string]: unknown;
  };
};

export type WhatsAppMessageList = {
  /**
   * Page of WhatsApp messages, newest first.
   */
  data: Array<WhatsAppMessage>;
} & ListEnvelope;

export type WhatsAppTemplateId = string;

export type WhatsAppTemplateSend = unknown & {
  /**
   * The template to send, by its id.
   */
  id?: WhatsAppTemplateId;
  /**
   * The template to send, by its slug handle (for example `bird_otp`).
   */
  slug?: TemplateSlug;
  /**
   * Which of the template's languages to send, as a BCP-47 tag (for example `en` or `pt-BR`); Meta's underscore form (`pt_BR`) is accepted and normalized. Omit it to send the template's default language, unless the template sets `language_source_required`, in which case a send naming no language is rejected. When the template does not carry the language you ask for, its own `on_missing_language` setting decides whether the closest available language is sent instead or the send is rejected. The accepted message echoes the canonical BCP-47 form of the language it resolved to.
   *
   */
  language?: LanguageTag;
  /**
   * The values that fill the template's placeholders: one entry per content block that has placeholders, each carrying its `parameters`. A positional template takes its parameters in `{{n}}` order; a template with named parameters requires each parameter's `name` to match one the template declares. Either way, sending parameters that do not match what the template declares returns a `422` `WhatsAppTemplateParameterMismatch`.
   *
   */
  components?: Array<WhatsAppMessageTemplateComponent>;
};

/**
 * Free-form text to send. Deliverable only inside an open 24-hour customer service window; outside one, send a template instead.
 *
 */
export type WhatsAppTextSend = {
  /**
   * The message text. The WhatsApp client turns any URL it contains into a clickable link.
   *
   */
  body: string;
  /**
   * Whether the WhatsApp client renders a preview of the first URL in `body`. A URL must begin with `http://` or `https://`, only the first one is previewed, and the client falls back to a plain link when it cannot fetch a preview. Not returned when the message is read back, because WhatsApp does not report whether a preview rendered.
   *
   */
  preview_url?: boolean;
};

/**
 * A free-form image to send, with an optional caption. Deliverable only inside an open 24-hour customer service window; outside one, send a template instead.
 *
 */
export type WhatsAppImageSend = {
  /**
   * Public `https` URL of the image. WhatsApp fetches it at send time, so it must still be reachable then: a signed URL has to outlive the send. We do not store or proxy the file. WhatsApp caches a fetched URL for 10 minutes and re-serves that copy for an identical URL sent again within the window; vary the URL to force a re-fetch. JPEG and PNG only, up to 5 MB.
   *
   */
  url: string;
  /**
   * Text shown beneath the image.
   */
  caption?: string;
};

/**
 * A free-form video to send, with an optional caption. Deliverable only inside an open 24-hour customer service window; outside one, send a template instead.
 *
 */
export type WhatsAppVideoSend = {
  /**
   * Public `https` URL of the video. WhatsApp fetches it at send time, so it must still be reachable then: a signed URL has to outlive the send. We do not store or proxy the file. WhatsApp caches a fetched URL for 10 minutes and re-serves that copy for an identical URL sent again within the window; vary the URL to force a re-fetch. MP4 with H.264 video and AAC audio, up to 16 MB.
   *
   */
  url: string;
  /**
   * Text shown beneath the video.
   */
  caption?: string;
};

/**
 * Free-form audio to send, either as a voice note or as a basic audio file. Deliverable only inside an open 24-hour customer service window; outside one, send a template instead.
 *
 */
export type WhatsAppAudioSend = {
  /**
   * Public `https` URL of the audio file. WhatsApp fetches it at send time, so it must still be reachable then: a signed URL has to outlive the send. We do not store or proxy the file. WhatsApp caches a fetched URL for 10 minutes and re-serves that copy for an identical URL sent again within the window; vary the URL to force a re-fetch. AAC, AMR, MP3, M4A and OGG (OPUS codec, mono) are supported, up to 16 MB.
   *
   */
  url: string;
  /**
   * Whether to send this as a voice note rather than a basic audio message. A voice note auto-downloads, shows the sender's profile picture, and can be transcribed for the recipient. It requires an `.ogg` file encoded with the OPUS codec; any other format makes transcription fail. Leave it false for an ordinary audio attachment.
   *
   */
  voice?: boolean;
};

/**
 * A free-form sticker to send. Deliverable only inside an open 24-hour customer service window; outside one, send a template instead.
 *
 */
export type WhatsAppStickerSend = {
  /**
   * Public `https` URL of the sticker. WhatsApp fetches it at send time, so it must still be reachable then: a signed URL has to outlive the send. We do not store or proxy the file. WhatsApp caches a fetched URL for 10 minutes and re-serves that copy for an identical URL sent again within the window; vary the URL to force a re-fetch. WebP only: up to 100 KB for a static sticker and 500 KB for an animated one. A sticker carries no caption.
   *
   */
  url: string;
};

/**
 * A free-form document to send, with an optional caption and filename. Deliverable only inside an open 24-hour customer service window; outside one, send a template instead.
 *
 */
export type WhatsAppDocumentSend = {
  /**
   * Public `https` URL of the document. WhatsApp fetches it at send time, so it must still be reachable then: a signed URL has to outlive the send. We do not store or proxy the file. WhatsApp caches a fetched URL for 10 minutes and re-serves that copy for an identical URL sent again within the window; vary the URL to force a re-fetch. Up to 100 MB. PDF, Word, Excel, PowerPoint and plain text render reliably in the WhatsApp client; other file types are transmitted but WhatsApp does not support them.
   *
   */
  url: string;
  /**
   * Text shown beneath the document.
   */
  caption?: string;
  /**
   * Name the recipient sees, including the extension. WhatsApp derives one from the URL when you omit it.
   *
   */
  filename?: string;
};

/**
 * A WhatsApp message to send. Carry exactly one kind of content: a request with none returns a `422` `WhatsAppContentRequired`, and one carrying more than one returns a `422` `WhatsAppContentAmbiguous`. The schema does not express that constraint, because which combinations are available depends on the content types your workspace can send.
 *
 */
export type WhatsAppMessageSendRequest = {
  /**
   * The message recipient: a phone number in E.164 format (for example `+31612345678`), or the recipient's business-scoped user ID (for example `US.13491208655302741918`), which addresses a WhatsApp user whose phone number you do not have. A value that is neither returns a `422` `WhatsAppInvalidRecipient`. One-time-passcode templates require a phone number and return a `422` `WhatsAppRecipientNotSupportedForTemplate` when sent to a business-scoped user ID.
   *
   */
  to: string;
  /**
   * The business phone number to send from, in E.164 format. Omit it for a Bird-managed template, which selects its own number from its category: setting it there returns a `422` `WhatsAppSenderNotAllowed`. Every other send, whether free-form content of any kind or a template your workspace authored, requires it, and the number must be one this workspace owns. Omitting it returns a `422` `WhatsAppSenderRequired`, and naming a number this workspace cannot send from returns a `422` `WhatsAppSenderNotFound`. Naming a number this workspace owns but that sits on a different WhatsApp Business Account than an authored template returns a `422` `WhatsAppSenderWABAMismatch`. A number this workspace holds but has not finished connecting returns a `422` `WhatsAppSenderNotConnected`.
   *
   */
  from?: string;
  /**
   * The template to send. A Bird-managed template selects the sender number from the template's category, so `from` must be omitted. A template is the only content deliverable outside a customer service window.
   *
   */
  template?: WhatsAppTemplateSend;
  /**
   * Free-form text to send instead of a template. Deliverable only inside an open 24-hour customer service window, which the contact opens by messaging or calling you and resets each time they do it again. A send into a closed window is refused with a `422` `WhatsAppServiceWindowClosed` before anything is created or charged; one whose window closes between accept and dispatch fails asynchronously, with `service_window_expired` on the message's `last_error`.
   *
   */
  text?: WhatsAppTextSend;
  /**
   * A free-form image to send instead of a template. Deliverable only inside an open 24-hour customer service window, which the contact opens by messaging or calling you and resets each time they do it again. A send into a closed window is refused with a `422` `WhatsAppServiceWindowClosed` before anything is created or charged; one whose window closes between accept and dispatch fails asynchronously, with `service_window_expired` on the message's `last_error`.
   *
   */
  image?: WhatsAppImageSend;
  /**
   * A free-form video to send instead of a template. Deliverable only inside an open 24-hour customer service window, which the contact opens by messaging or calling you and resets each time they do it again. A send into a closed window is refused with a `422` `WhatsAppServiceWindowClosed` before anything is created or charged; one whose window closes between accept and dispatch fails asynchronously, with `service_window_expired` on the message's `last_error`.
   *
   */
  video?: WhatsAppVideoSend;
  /**
   * Free-form audio to send instead of a template. Deliverable only inside an open 24-hour customer service window, which the contact opens by messaging or calling you and resets each time they do it again. A send into a closed window is refused with a `422` `WhatsAppServiceWindowClosed` before anything is created or charged; one whose window closes between accept and dispatch fails asynchronously, with `service_window_expired` on the message's `last_error`.
   *
   */
  audio?: WhatsAppAudioSend;
  /**
   * A free-form sticker to send instead of a template. Deliverable only inside an open 24-hour customer service window, which the contact opens by messaging or calling you and resets each time they do it again. A send into a closed window is refused with a `422` `WhatsAppServiceWindowClosed` before anything is created or charged; one whose window closes between accept and dispatch fails asynchronously, with `service_window_expired` on the message's `last_error`.
   *
   */
  sticker?: WhatsAppStickerSend;
  /**
   * A free-form document to send instead of a template. Deliverable only inside an open 24-hour customer service window, which the contact opens by messaging or calling you and resets each time they do it again. A send into a closed window is refused with a `422` `WhatsAppServiceWindowClosed` before anything is created or charged; one whose window closes between accept and dispatch fails asynchronously, with `service_window_expired` on the message's `last_error`.
   *
   */
  document?: WhatsAppDocumentSend;
  /**
   * A free-form location to send instead of a template. Deliverable only inside an open 24-hour customer service window, which the contact opens by messaging or calling you and resets each time they do it again. A send into a closed window is refused with a `422` `WhatsAppServiceWindowClosed` before anything is created or charged; one whose window closes between accept and dispatch fails asynchronously, with `service_window_expired` on the message's `last_error`.
   *
   */
  location?: WhatsAppLocationSend;
  /**
   * Structured `{name, value}` labels for filtering. Tags become first-class query dimensions: filter the list endpoint by tag name. Maximum 20 tags per send. Use tags for low-cardinality dimensions (`category`, `experiment_variant`). For arbitrary structured context you do not need as a filter dimension, use `metadata` instead.
   *
   */
  tags?: Array<Tag>;
  /**
   * Arbitrary JSON object stored on the message and returned on API reads. Maximum 2 KB serialized. Use metadata for per-send context like internal IDs and foreign keys. For low-cardinality filterable labels, use `tags` instead.
   *
   */
  metadata?: {
    [key: string]: unknown;
  };
};

/**
 * Message timeline event type:
 *
 * - `whatsapp.accepted`: The API accepted the request.
 * - `whatsapp.sent`: The message reached the WhatsApp network.
 * - `whatsapp.delivered`: Delivery to the recipient's device was confirmed.
 * - `whatsapp.read`: The recipient opened the message.
 * - `whatsapp.failed`: Delivery failed permanently.
 * - `whatsapp.rejected`: The message was refused before sending and not charged.
 * - `whatsapp.received`: An inbound message arrived from the contact.
 *
 * This is an open enum. Accept unrecognized values.
 *
 */
export type WhatsAppEventType =
  | "whatsapp.accepted"
  | "whatsapp.delivered"
  | "whatsapp.failed"
  | "whatsapp.read"
  | "whatsapp.received"
  | "whatsapp.rejected"
  | "whatsapp.sent"
  | (string & {});

export type WhatsAppEventId = string;

export type WhatsAppEvent = {
  /**
   * ID of the event, unique within the message's timeline.
   */
  readonly id: WhatsAppEventId;
  readonly type: WhatsAppEventType;
  /**
   * When this event occurred.
   */
  readonly occurred_at: string;
  /**
   * Failure detail. Present only on `whatsapp.failed` and `whatsapp.rejected` events.
   */
  error?: WhatsAppError;
};

export type WhatsAppEventList = {
  /**
   * Timeline events for this WhatsApp message, in chronological order. The timeline is bounded and returned in full; this list is not paginated.
   */
  data: Array<WhatsAppEvent>;
};

export type NumbersDedicatedAllocationId = string;

export type WhatsAppSuppressionId = string;

/**
 * The window and bucket grain the response covers, echoed from the request, plus the freshness boundary the data is current to.
 *
 */
export type EmailStatsSeriesPeriod = {
  /**
   * Inclusive start of the window. A calendar day (YYYY-MM-DD, in the requested `timezone`) on the day grain. On the hour grain, an RFC 3339 UTC instant marking the start of the first hour bucket, which falls on a local hour boundary when `timezone` is set.
   */
  readonly from: string;
  /**
   * Inclusive end of the window. A calendar day (YYYY-MM-DD, in the requested `timezone`) on the day grain. On the hour grain, an RFC 3339 UTC instant marking the start of the last hour bucket, which falls on a local hour boundary when `timezone` is set.
   */
  readonly to: string;
  readonly grain: StatsGrain;
  /**
   * The instant the statistics in this response are current to: events recorded up to roughly this time are reflected, while more recent events may not be yet. Statistics are served from a rolling aggregation that refreshes every few seconds, so a response reflects data from up to a few seconds ago. Use this field to label data freshness rather than assuming the numbers are to-the-second. Null when the freshness boundary is not being reported.
   *
   */
  readonly data_as_of?: string | null;
};

/**
 * Breakdown of `bounced` by failure type, with each rate as a fraction of `bounced`. Counts are distinct bounced recipients of that type; the five types approximately partition `bounced`, so the five rates sum to roughly 1.0 when `bounced` is non-zero.
 *
 */
export type EmailBounceStatsWithRates = {
  /**
   * Distinct recipients with a permanent delivery failure (invalid address or non-existent domain).
   */
  readonly hard: number;
  /**
   * Distinct recipients with a transient delivery failure (mailbox full or server temporarily unavailable).
   */
  readonly soft: number;
  /**
   * Distinct recipients refused by a policy at the receiving end, such as relaying denied or a blocklisted domain.
   */
  readonly admin: number;
  /**
   * Distinct recipients bounced because the receiving mail server blocked the sending IP for reputation reasons.
   */
  readonly block: number;
  /**
   * Distinct recipients bounced where the receiving server's response did not allow precise classification.
   */
  readonly undetermined: number;
  /**
   * Fraction of bounced recipients that hard bounced, computed as `hard / bounced`. Null when `bounced` is zero.
   *
   */
  readonly hard_rate: number | null;
  /**
   * Fraction of bounced recipients that soft bounced, computed as `soft / bounced`. Null when `bounced` is zero.
   *
   */
  readonly soft_rate: number | null;
  /**
   * Fraction of bounced recipients that admin bounced, computed as `admin / bounced`. Null when `bounced` is zero.
   *
   */
  readonly admin_rate: number | null;
  /**
   * Fraction of bounced recipients that block bounced, computed as `block / bounced`. Null when `bounced` is zero.
   *
   */
  readonly block_rate: number | null;
  /**
   * Fraction of bounced recipients with undetermined classification, computed as `undetermined / bounced`. Null when `bounced` is zero.
   *
   */
  readonly undetermined_rate: number | null;
};

/**
 * Delivery counts and rates for the scope of the containing row (a time bucket, a breakdown dimension, or the whole period). Every count is the number of distinct recipients that reached the named lifecycle stage in scope. On the period summary, each count is the sum of the per-bucket distinct counts. Event time determines attribution; send time does not. A recipient delivered on Monday counts in Monday's row. A recipient who bounced and then succeeded on a retry can appear in both `bounced` and `delivered`. Very large counts are close estimates rather than exact tallies.
 *
 * These counts are successive lifecycle stages, so a recipient can appear in more than one:
 *
 * - `rejected`: Happens before any send attempt, from suppression, policy, or a generation failure.
 * - `deferred`: A temporary in-flight delay that is still being retried.
 * - `bounced`: A delivery failure, with its own hard, soft, admin, block, and undetermined sub-types.
 * - `complained`: Post-delivery spam feedback.
 *
 * Each rate is a fraction in the range 0 to 1 and is null when its denominator is zero. `accepted` is reported only where it can be attributed (time buckets and the period summary). Breakdown rows omit it.
 *
 */
export type EmailDeliveryStats = {
  /**
   * Distinct recipients accepted for delivery after suppression filtering. Reported on time buckets and the period summary. Breakdown rows leave it out, because their rollups do not have it.
   */
  readonly accepted?: number;
  /**
   * Distinct recipients whose message was processed and handed off for delivery.
   */
  readonly processed: number;
  /**
   * Distinct recipients whose message the receiving mail server accepted.
   */
  readonly delivered: number;
  /**
   * Distinct recipients whose delivery failed. This is approximately the sum of the five `bounces.*` sub-counts (hard, soft, admin, block, undetermined). The two totals are worked out independently, so they can differ slightly.
   *
   */
  readonly bounced: number;
  readonly bounces: EmailBounceStatsWithRates;
  /**
   * Distinct recipients who reported the message as spam via a feedback loop.
   */
  readonly complained: number;
  /**
   * Distinct recipients whose delivery the receiving server temporarily delayed and is still being retried.
   *
   */
  readonly deferred: number;
  /**
   * Distinct recipients rejected before any delivery attempt. Includes recipients on the workspace suppression list, transmissions that could not be completed, message-generation failures, and recipients refused by sending policy. The per-recipient `rejection_reason` field on `GET /v1/email/messages/{message_id}/recipients` surfaces the specific cause.
   *
   */
  readonly rejected: number;
  /**
   * Out-of-band bounce events: distinct failure notifications received after the receiving server had initially confirmed delivery. The count represents deduplicated events rather than unique recipients.
   *
   */
  readonly oob_bounces: number;
  /**
   * Recipients who remain delivered after all bounce signals resolve, computed as `delivered - oob_bounces`. Use this as the base for engagement-rate denominators. Clamped to 0 when `oob_bounces` exceeds `delivered`.
   */
  readonly effective_delivered: number;
  /**
   * Total recipients in this scope who did not receive the message, computed as `bounced + oob_bounces`.
   */
  readonly all_bounces: number;
  /**
   * Share of this scope's delivery attempts that resulted in an out-of-band bounce, computed as `oob_bounces / (delivered + bounced)`. Null when there were no attempts.
   */
  readonly oob_rate: number | null;
  /**
   * Share of this scope's delivery attempts that remained delivered after all bounce signals, computed as `effective_delivered / (delivered + bounced)`. Null when there were no attempts.
   *
   */
  readonly delivery_rate: number | null;
  /**
   * Share of this scope's delivery attempts that ultimately failed (inband or out-of-band), computed as `all_bounces / (delivered + bounced)`. Because `oob_bounces` counts events rather than recipients, `all_bounces` can exceed the attempt count. The rate is clamped to 1. Null when there were no attempts.
   *
   */
  readonly bounce_rate: number | null;
  /**
   * Spam complaints in this scope relative to effectively delivered recipients, computed as `complained / effective_delivered`. Complaints are attributed by event time, so a scope can record more of them than it effectively delivered, pushing the rate above 1. Null when `effective_delivered` is zero.
   *
   */
  readonly complaint_rate: number | null;
};

/**
 * Engagement counts and rates for the scope of the containing row (a time bucket, a breakdown dimension, or the whole period). `opens`, `opens_non_prefetched` and `clicks` count distinct engagement events (deduplicated occurrences). The `unique_*` fields count distinct recipients. `unsubscribes` counts distinct unsubscribe events. An event counts in the time bucket when it occurs, even if the message was sent in an earlier bucket. Counts are deduplicated with a scalable approximate counting method, so very large counts are close estimates rather than exact tallies. Each rate divides the counts in this scope and is null when its denominator is zero.
 *
 */
export type EmailEngagementStats = {
  /**
   * Distinct open events, counting repeat opens from the same recipient and opens auto-fetched by inbox privacy features (such as Apple Mail Privacy Protection and the Gmail image proxy).
   *
   */
  readonly opens: number;
  /**
   * Distinct open events excluding those auto-fetched by inbox privacy features. Same event-counting semantics as `opens` (repeat opens from the same recipient count separately), with prefetched opens removed.
   *
   */
  readonly opens_non_prefetched: number;
  /**
   * Distinct recipients who opened at least once, including opens auto-fetched by inbox privacy features.
   */
  readonly unique_opens: number;
  /**
   * Distinct recipients who opened at least once, excluding opens auto-fetched by inbox privacy features. This is the numerator used for open rate, so iOS-heavy audiences (Apple Mail Privacy Protection and similar) do not inflate it.
   *
   */
  readonly unique_opens_non_prefetched: number;
  /**
   * Distinct click events, counting repeat clicks from the same recipient.
   */
  readonly clicks: number;
  /**
   * Distinct recipients who clicked at least once.
   */
  readonly unique_clicks: number;
  /**
   * Distinct unsubscribe events, recorded via the list-unsubscribe header or the footer link.
   */
  readonly unsubscribes: number;
  /**
   * Distinct non-prefetched openers relative to effectively delivered recipients in the same scope, computed as `unique_opens_non_prefetched / delivery.effective_delivered`; on rows without an `effective_delivered` field (the mailbox-provider breakdowns) the denominator equals `delivery.delivered`. The numerator excludes opens auto-fetched by inbox privacy features. Opens are attributed by event time, so engagement earned by earlier deliveries can push the rate above 1. Null when the denominator is zero.
   *
   */
  readonly open_rate: number | null;
  /**
   * Distinct clickers relative to effectively delivered recipients in the same scope, computed as `unique_clicks / delivery.effective_delivered` (`delivery.delivered` on rows without an `effective_delivered` field). Clicks are attributed by event time, so engagement earned by earlier deliveries can push the rate above 1. Null when the denominator is zero.
   *
   */
  readonly click_rate: number | null;
  /**
   * Unsubscribe events relative to effectively delivered recipients in the same scope, computed as `unsubscribes / delivery.effective_delivered` (`delivery.delivered` on rows without an `effective_delivered` field). Unsubscribes are attributed by event time, so the rate can exceed 1. Null when the denominator is zero.
   *
   */
  readonly unsubscribe_rate: number | null;
};

/**
 * Approximate p50, p95, and p99 latency percentiles in milliseconds for one latency family over the bucket. All three are null when no qualifying event contributed a measurement.
 *
 */
export type EmailLatencyQuantiles = {
  /**
   * Median (50th percentile) latency in milliseconds. Null when no qualifying event contributed a measurement.
   */
  readonly p50_ms: number | null;
  /**
   * 95th percentile latency in milliseconds. Null when no qualifying event contributed a measurement.
   */
  readonly p95_ms: number | null;
  /**
   * 99th percentile latency in milliseconds. Null when no qualifying event contributed a measurement.
   */
  readonly p99_ms: number | null;
};

/**
 * Latency percentiles (p50, p95, p99) in milliseconds for the bucket. On the summary endpoint these are computed across the whole period rather than per bucket. Three families are reported:
 *
 * - `processing`: Time from accepting the send to handing the message off for delivery. Measured per processed recipient; null when no recipient in the bucket has reached the processed stage.
 * - `delivery`: Time from handoff to the receiving mail server accepting the message, dominated by recipient-side delivery behavior. Measured per delivered recipient; null when no deliveries occurred in the bucket.
 * - `total`: End-to-end time from accepting the send to delivery, and the number most worth watching against your own delivery targets. Measured per delivered recipient; null when no deliveries occurred in the bucket.
 *
 * Each family is reported independently. A family is omitted when no qualifying
 * event contributed a latency measurement in the bucket. This also applies when
 * the workspace has not recorded latency for that stage yet. The `processing`
 * family can therefore be present while `delivery` and `total` are absent. A
 * client must handle a missing family, and a null p50/p95/p99 within a present
 * family, by rendering a placeholder rather than assuming a number.
 *
 */
export type EmailLatencyStats = {
  processing?: EmailLatencyQuantiles;
  delivery?: EmailLatencyQuantiles;
  total?: EmailLatencyQuantiles;
};

/**
 * Aggregate stats for one time bucket (a calendar day or hour, per the requested grain, in the requested `timezone` or UTC by default), bucketed by event time. Buckets with no activity are included with zero counts and null latency percentiles, so the series charts continuously without client-side gap handling.
 *
 */
export type EmailStatsPoint = {
  /**
   * The day (YYYY-MM-DD, in the requested `timezone`) or hour this point covers, matching the period's grain. An hour bucket is an RFC 3339 UTC instant marking the start of the hour. It falls on a local hour boundary when `timezone` is set, which is on the UTC hour only for whole-hour offsets.
   */
  readonly bucket: string;
  /**
   * Distinct email messages accepted in this bucket, counted at the message level (one per accepted send regardless of how many recipients it addresses). Every other metric in `delivery` and `engagement` is recipient-level or event-level.
   *
   */
  readonly sends_accepted: number;
  readonly delivery: EmailDeliveryStats;
  readonly engagement: EmailEngagementStats;
  readonly latency: EmailLatencyStats;
};

/**
 * Time-series stats payload. `period` echoes the range and bucket grain actually computed against. `data` is one row per bucket in chronological order.
 *
 */
export type EmailStatsResponse = {
  period: EmailStatsSeriesPeriod;
  /**
   * One row per bucket (day or hour, per the grain) in the period, in chronological order. Buckets with no activity are included with zero counts.
   */
  readonly data: Array<EmailStatsPoint>;
};

/**
 * Metric to rank breakdown rows by, applied descending. Shared by the breakdowns whose rows have the full delivery, engagement, and latency block: tags, sending domains, categories, recipient domains, templates, and broadcasts. Any count or rate can be used. A row whose rate is undefined, because its denominator was zero, sorts last. A bounce sub-type is nested under `bounces` in each row, so its sort name reflects that, for example `bounces.hard` and `bounces.hard_rate`. `oob_bounces` is distinct from `bounced`: it counts out-of-band bounces, failure notifications that arrive after delivery was already confirmed.
 *
 */
export type EmailStatsSortMetric =
  | "processed"
  | "delivered"
  | "bounced"
  | "complained"
  | "deferred"
  | "rejected"
  | "oob_bounces"
  | "bounces.hard"
  | "bounces.soft"
  | "bounces.admin"
  | "bounces.block"
  | "bounces.undetermined"
  | "opens"
  | "opens_non_prefetched"
  | "unique_opens"
  | "unique_opens_non_prefetched"
  | "clicks"
  | "unique_clicks"
  | "unsubscribes"
  | "delivery_rate"
  | "bounce_rate"
  | "complaint_rate"
  | "open_rate"
  | "click_rate"
  | "unsubscribe_rate"
  | "bounces.hard_rate"
  | "bounces.soft_rate"
  | "bounces.admin_rate"
  | "bounces.block_rate"
  | "bounces.undetermined_rate";

/**
 * The date range this response was actually computed against. Echoed back so clients can render the period without tracking it themselves and so cached responses can be keyed by what was queried.
 *
 */
export type EmailStatsPeriod = {
  /**
   * Inclusive start date the response covers (YYYY-MM-DD).
   */
  readonly from: string;
  /**
   * Inclusive end date the response covers (YYYY-MM-DD).
   */
  readonly to: string;
  /**
   * The instant the statistics in this response are current to: events recorded up to roughly this time are reflected, while more recent events may not be yet. Statistics are served from a rolling aggregation that refreshes every few seconds, so a response reflects data from up to a few seconds ago. Use this field to label data freshness (for example "as of 14:03") rather than assuming the numbers are to-the-second. Null when the freshness boundary is not being reported.
   *
   */
  readonly data_as_of?: string | null;
};

/**
 * One point in a breakdown row's trend series: the headline delivery and engagement rates for that row's dimension value over a single day or hour. Returned only when `include_trend=true`. The bucket grain (day or hour) follows the `trend_grain` parameter. Counts and rates are approximate at scale.
 *
 */
export type EmailStatsSeriesPoint = {
  /**
   * The day (YYYY-MM-DD) or hour (ISO 8601, on the hour) this point covers, matching the requested `trend_grain`.
   */
  readonly bucket: string;
  /**
   * Delivered recipients in this bucket.
   */
  readonly delivered: number;
  /**
   * Bounced recipients in this bucket.
   */
  readonly bounced: number;
  /**
   * Delivery rate for this bucket, as a fraction. Null when nothing was delivered or bounced.
   */
  readonly delivery_rate: number | null;
  /**
   * Bounce rate for this bucket, as a fraction. Null when nothing was delivered or bounced.
   */
  readonly bounce_rate: number | null;
  /**
   * Complaint rate for this bucket, as a fraction. Event-time attribution can push it above 1 when complaints outrun the bucket's deliveries. Null when nothing was delivered in the bucket. On a sending-IP row complaints are not attributed to the IP, so this reads 0 in buckets that had deliveries and null in buckets that had none.
   */
  readonly complaint_rate: number | null;
  /**
   * Open rate for this bucket, as a fraction. Event-time attribution can push it above 1 when opens outrun the bucket's deliveries. Null when nothing was delivered in the bucket. On a sending-IP row engagement is not attributed to the IP, so this reads 0 in buckets that had deliveries and null in buckets that had none.
   */
  readonly open_rate: number | null;
  /**
   * Click rate for this bucket, as a fraction. Event-time attribution can push it above 1 when clicks outrun the bucket's deliveries. Null when nothing was delivered in the bucket. On a sending-IP row engagement is not attributed to the IP, so this reads 0 in buckets that had deliveries and null in buckets that had none.
   */
  readonly click_rate: number | null;
};

/**
 * Aggregate delivery and engagement stats for a single tag name-and-value pair over the requested period.
 */
export type EmailTagStatsPoint = {
  /**
   * The tag this row aggregates, formatted as `name:value` from the tag set at send time (for example `campaign:welcome-series`). Each distinct name-and-value pair is its own row.
   *
   */
  readonly tag: string;
  readonly delivery: EmailDeliveryStats;
  readonly engagement: EmailEngagementStats;
  readonly latency: EmailLatencyStats;
  /**
   * Per-bucket rate series for this tag over the window. Present only when `include_trend=true`.
   */
  readonly trend?: Array<EmailStatsSeriesPoint>;
};

/**
 * Per-tag breakdown for the requested period, ranked by the `sort` metric (default `processed`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type EmailStatsTagsResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: EmailStatsPeriod;
  /**
   * Tag breakdown rows, ranked by the `sort` metric (default `processed`) descending. Empty when no tagged sends occurred in the period.
   */
  readonly data: Array<EmailTagStatsPoint>;
  /**
   * Total number of distinct tags (name and value pairs) with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped. Raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * The window this response was actually computed against. The summary serves two window grains: calendar days (bounds are YYYY-MM-DD) and hours (bounds are RFC 3339 instants). The grain of `from` and `to` mirrors the grain of the request's bounds. Days and hour boundaries follow the requested `timezone` (UTC when omitted).
 *
 */
export type EmailStatsSummaryPeriod = {
  /**
   * Inclusive start of the window the response covers. A calendar day (YYYY-MM-DD, in the requested `timezone`) for day windows. For hour windows, an RFC 3339 UTC instant marking the start of the first hour, which falls on a local hour boundary when `timezone` is set.
   */
  readonly from: string;
  /**
   * Inclusive end of the window the response covers. A calendar day (YYYY-MM-DD, in the requested `timezone`) for day windows. For hour windows, an RFC 3339 UTC instant marking the start of the last hour, which falls on a local hour boundary when `timezone` is set.
   */
  readonly to: string;
  /**
   * The instant the statistics in this response are current to: events recorded up to roughly this time are reflected, while more recent events may not be yet. Statistics are served from a rolling aggregation that refreshes every few seconds, so a response reflects data from up to a few seconds ago. Use this field to label data freshness (for example "as of 14:03") rather than assuming the numbers are to-the-second. Null when the freshness boundary is not being reported.
   *
   */
  readonly data_as_of?: string | null;
};

/**
 * The change in each headline metric from the preceding period to the requested one. A `*_pct_change` field is a signed relative change in a count, computed as `(current - previous) / previous`, so `0.5` means 50% higher and `-0.2` means 20% lower. It is null when the previous period's count was zero because a relative change cannot be computed. A `*_rate_pp` field is the signed difference between the two periods' rate values. Each value is expressed as a fraction. A value of `0.012` means the rate rose by 1.2 percentage points. A value of `-0.003` means it fell by 0.3 points. The field is null when either period's rate is undefined, because its denominator was zero. `delivery_rate_pp` and `bounce_rate_pp` range from `-1` to `1`, because the rates behind them cannot exceed 1. The engagement deltas have no fixed bound, because events are counted when they arrive rather than when the message was sent, which can push their rate above 1.
 *
 */
export type EmailStatsComparisonDelta = {
  /**
   * Relative change in accepted messages (the `sends_accepted` count) versus the previous period, as a signed fraction. Null when the previous period accepted none.
   */
  readonly sends_accepted_pct_change: number | null;
  /**
   * Relative change in effectively delivered recipients (`delivery.effective_delivered`, the delivery-rate numerator) versus the previous period, as a signed fraction. Null when the previous period effectively delivered none.
   */
  readonly delivered_pct_change: number | null;
  /**
   * Relative change in total bounces including out-of-band (`delivery.all_bounces`, the bounce-rate numerator) versus the previous period, as a signed fraction. Null when the previous period had none.
   */
  readonly bounced_pct_change: number | null;
  /**
   * Relative change in spam complaints (`delivery.complained`) versus the previous period, as a signed fraction. Null when the previous period had none.
   */
  readonly complained_pct_change: number | null;
  /**
   * Relative change in unique non-prefetched opens (`engagement.unique_opens_non_prefetched`, the same count the open rate uses) versus the previous period, as a signed fraction. Null when the previous period had none.
   */
  readonly opened_pct_change: number | null;
  /**
   * Signed difference between this period's and the previous period's delivery rate, both fractions in [0,1] (multiply by 100 for percentage points). Null when either period's delivery rate is undefined.
   */
  readonly delivery_rate_pp: number | null;
  /**
   * Signed difference between this period's and the previous period's open rate, both fractions (multiply by 100 for percentage points). Null when either period's open rate is undefined.
   */
  readonly open_rate_pp: number | null;
  /**
   * Signed difference between this period's and the previous period's click rate, both fractions (multiply by 100 for percentage points). Null when either period's click rate is undefined.
   */
  readonly click_rate_pp: number | null;
  /**
   * Signed difference between this period's and the previous period's bounce rate, both fractions in [0,1] (multiply by 100 for percentage points). Null when either period's bounce rate is undefined.
   */
  readonly bounce_rate_pp: number | null;
  /**
   * Signed difference between this period's and the previous period's complaint rate, both fractions (multiply by 100 for percentage points). Null when either period's complaint rate is undefined.
   */
  readonly complaint_rate_pp: number | null;
  /**
   * Signed difference between this period's and the previous period's unsubscribe rate, both fractions (multiply by 100 for percentage points). Null when either period's unsubscribe rate is undefined.
   */
  readonly unsubscribe_rate_pp: number | null;
};

/**
 * The same statistics for the equal-length, inclusive period ending the day immediately before the requested start, together with the change between the two periods. Present only when `compare=previous_period` is requested. The change is already computed, so a percentage difference needs no second request.
 *
 */
export type EmailStatsComparison = {
  /**
   * The preceding window these comparison figures cover, the equal-length window ending immediately before the requested start (the prior day for day windows, the prior hour for hour windows). For a request covering 2026-05-01 to 2026-05-31, this is 2026-03-31 to 2026-04-30, both inclusive.
   */
  period: EmailStatsSummaryPeriod;
  /**
   * Distinct email messages accepted in the preceding period, counted at the message level.
   */
  readonly sends_accepted: number;
  readonly delivery: EmailDeliveryStats;
  readonly engagement: EmailEngagementStats;
  readonly latency: EmailLatencyStats;
  readonly delta: EmailStatsComparisonDelta;
};

/**
 * A single row that aggregates delivery and engagement counts, plus derived
 * rates, across the whole requested period. Use this endpoint for KPI
 * tiles, campaign reporting, and anywhere you need a rate with a meaningful
 * denominator. The daily and hourly endpoints report the same rates, but
 * per bucket, each one dividing that bucket's own counts.
 *
 * Every count is a sum of per-bucket counts across the window (per day for
 * day windows, per hour for hour windows). A recipient, or a message, that
 * is active in two buckets contributes to each of them, so it is counted
 * twice in the period total. This matches how most mailbox providers report
 * their own numbers. The effect to plan for is that the total is a sum of
 * per-bucket activity rather than a count of distinct recipients or messages
 * across the whole period. Latency percentiles work differently: they are computed
 * once across the whole period rather than summed from the buckets. A rate
 * is null when its denominator is zero.
 *
 */
export type EmailStatsSummary = {
  /**
   * The window the response covers (echoed back from the request, day or hour grain), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: EmailStatsSummaryPeriod;
  /**
   * Distinct email messages accepted, counted at the message level (one per accepted send regardless of recipient count) and summed per bucket across the period. This field counts messages. `delivery.accepted` counts recipients, so the two values are not comparable (a single message to 500 recipients is 1 here and up to 500 there).
   */
  readonly sends_accepted: number;
  readonly delivery: EmailDeliveryStats;
  readonly engagement: EmailEngagementStats;
  readonly latency: EmailLatencyStats;
  readonly comparison?: EmailStatsComparison;
};

export type IpPoolId = string;

/**
 * Delivery counts and rates for messages attributed to a single sending IP. Per-IP results omit `accepted` and `processed` counts. The sending IP becomes known only after a message is delivered, bounced, deferred, or bounced late. Those earlier lifecycle states cannot be attributed to a specific IP. Spam complaints and out-of-band bounce notifications also lack per-IP attribution on this breakdown. The `complained` and `oob_bounces` fields therefore read 0. Their rates read 0 when the denominator is non-zero and null when it is zero. The `effective_delivered` field equals `delivered`, and `all_bounces` equals `bounced`.
 *
 */
export type EmailSendingIpDeliveryStats = {
  /**
   * Distinct recipients whose message the receiving mail server accepted.
   */
  readonly delivered: number;
  /**
   * Distinct recipients whose delivery failed. This is approximately the sum of the five `bounces.*` sub-counts (hard, soft, admin, block, undetermined). The two are computed independently, so they can differ slightly.
   */
  readonly bounced: number;
  /**
   * Distinct recipients who reported the message as spam. Complaints are not attributed to a sending IP, so this reads 0 on this breakdown. Read complaint counts from the summary or time-series statistics instead.
   */
  readonly complained: number;
  /**
   * Distinct recipients in transient delivery deferral that is still being retried.
   */
  readonly deferred: number;
  /**
   * Out-of-band bounce events: failure notifications received after the receiving server had initially confirmed delivery. Not attributed to a sending IP on this breakdown, so this reads 0. Workspace-wide out-of-band counts are on the summary and time-series statistics.
   *
   */
  readonly oob_bounces: number;
  /**
   * Recipients on this IP who remain delivered after all bounce signals resolve, computed as `delivered - oob_bounces`. Clamped to 0 when `oob_bounces` exceeds `delivered`.
   */
  readonly effective_delivered: number;
  /**
   * Total recipients on this IP who did not receive the message, computed as `bounced + oob_bounces`.
   */
  readonly all_bounces: number;
  /**
   * Share of this IP's delivery attempts that resulted in an out-of-band bounce, computed as `oob_bounces / (delivered + bounced)`. Null when `delivered + bounced` is zero (no attempts).
   */
  readonly oob_rate: number | null;
  readonly bounces: EmailBounceStatsWithRates;
  /**
   * Share of this IP's delivery attempts that remained delivered after all bounce signals, computed as `effective_delivered / (delivered + bounced)`. Null when `delivered + bounced` is zero.
   *
   */
  readonly delivery_rate: number | null;
  /**
   * Share of this IP's delivery attempts that ultimately failed (inband or out-of-band), computed as `all_bounces / (delivered + bounced)`. Null when `delivered + bounced` is zero (no attempts).
   *
   */
  readonly bounce_rate: number | null;
  /**
   * Share of effectively delivered recipients on this IP who reported the message as spam, computed as `complained / effective_delivered`. Null when `effective_delivered` is zero.
   *
   */
  readonly complaint_rate: number | null;
};

/**
 * Latency percentiles (p50, p95, p99) in milliseconds for the messages in this breakdown row, for breakdowns whose dimension is known only from delivery onward (sending IP, mailbox provider).
 *
 * - `delivery`: Time from handing the message off to the receiving mail server accepting it. Null when no deliveries occurred for this row in the period.
 * - `total`: End-to-end time from accepting the send to delivery. Null when no deliveries occurred for this row in the period.
 *
 * These breakdowns have no `processing` latency family. A message's row identifies which sending IP carried it or which mailbox provider received it. This becomes known only after the receiving mail server reports a delivery, bounce, deferral, or late bounce. The accept-to-processed phase ends before that attribution is known, preventing row-level processing latency. Use `GET /v1/email/stats/daily` for processing-latency percentiles across the whole workspace.
 *
 */
export type EmailDeliveryLatencyStats = {
  delivery: EmailLatencyQuantiles;
  total: EmailLatencyQuantiles;
};

/**
 * Delivery and latency stats for messages sent from a single IP address over the requested period. Per-IP attribution begins only after a message is processed: we learn which IP a message used only from its delivery, bounce, deferral, and late-bounce events. Acceptance and processing events do not contribute to per-IP attribution. As a result, per-IP rows omit the `accepted` and `processed` counts and the `processing` latency family. Those fields never appear on a per-IP row. They are not returned as null.
 *
 */
export type EmailSendingIpStatsPoint = {
  /**
   * The IP address used to send messages aggregated in this row.
   */
  readonly sending_ip: string;
  /**
   * The dedicated IP pool this address sent through, or null when the messages went through the shared pool. Recorded when each message was sent, so it reflects the pool used at send time even if the IP has since moved between pools or been released.
   *
   */
  readonly ip_pool_id?: IpPoolId | null;
  readonly delivery: EmailSendingIpDeliveryStats;
  readonly latency: EmailDeliveryLatencyStats;
  /**
   * Per-bucket delivery-rate series for this IP over the window. Present only when `include_trend=true`. Engagement is not attributed to a sending IP, so each point's open and click rates read 0 in buckets with deliveries and null in buckets without.
   */
  readonly trend?: Array<EmailStatsSeriesPoint>;
};

/**
 * Per-sending-IP breakdown for the requested period, ranked by the `sort` metric (default `delivered`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type EmailStatsBySendingIpResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: EmailStatsPeriod;
  /**
   * Sending-IP breakdown rows, ranked by the `sort` metric (default `delivered`) descending. Empty when no per-IP-attributable activity (delivery, bounce, deferral, or late bounce) occurred in the period.
   */
  readonly data: Array<EmailSendingIpStatsPoint>;
  /**
   * Total number of distinct sending IP addresses with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped. Raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Aggregate delivery, engagement, and latency stats for messages sent from a single sending domain over the requested period.
 */
export type EmailSendingDomainStatsPoint = {
  /**
   * The sending domain (the portion of the `From` address after the `@`), normalized to lowercase.
   */
  readonly sending_domain: string;
  readonly delivery: EmailDeliveryStats;
  readonly engagement: EmailEngagementStats;
  readonly latency: EmailLatencyStats;
  /**
   * Per-bucket rate series for this sending domain over the window. Present only when `include_trend=true`.
   */
  readonly trend?: Array<EmailStatsSeriesPoint>;
};

/**
 * Per-sending-domain breakdown for the requested period, ranked by the `sort` metric (default `processed`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type EmailStatsBySendingDomainResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: EmailStatsPeriod;
  /**
   * Sending-domain breakdown rows, ranked by the `sort` metric (default `processed`) descending. Empty when no eligible activity occurred in the period.
   */
  readonly data: Array<EmailSendingDomainStatsPoint>;
  /**
   * Total number of distinct sending domains with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped. Raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Aggregate delivery and engagement stats for a single category over the requested period.
 */
export type EmailCategoryStatsPoint = {
  /**
   * The category this row aggregates, as set at send time. `transactional` is one-to-one mail triggered by a user action. `marketing` is bulk sending. New categories may be added over time.
   */
  readonly category: string;
  readonly delivery: EmailDeliveryStats;
  readonly engagement: EmailEngagementStats;
  readonly latency: EmailLatencyStats;
  /**
   * Per-bucket rate series for this category over the window. Present only when `include_trend=true`.
   */
  readonly trend?: Array<EmailStatsSeriesPoint>;
};

/**
 * Per-category breakdown for the requested period, ranked by the `sort` metric (default `processed`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type EmailStatsByCategoryResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: EmailStatsPeriod;
  /**
   * Category breakdown rows, ranked by the `sort` metric (default `processed`) descending. Empty when no sends occurred in the period.
   */
  readonly data: Array<EmailCategoryStatsPoint>;
  /**
   * Total number of distinct categories with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped. Raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Metric to rank rows by, applied descending. Shared by every breakdown whose attribution begins at delivery, so `processed`, `rejected`, and `oob_bounces` are not part of those rows and are not sortable. Any count or rate on the row can be used; rows whose rate is undefined (zero denominator) sort last. Bounce sub-types use their nested location in each row, for example `bounces.hard` and `bounces.hard_rate`.
 *
 */
export type EmailMailboxProviderSortMetric =
  | "delivered"
  | "bounced"
  | "complained"
  | "deferred"
  | "bounces.hard"
  | "bounces.soft"
  | "bounces.admin"
  | "bounces.block"
  | "bounces.undetermined"
  | "opens"
  | "opens_non_prefetched"
  | "unique_opens"
  | "unique_opens_non_prefetched"
  | "clicks"
  | "unique_clicks"
  | "unsubscribes"
  | "delivery_rate"
  | "bounce_rate"
  | "complaint_rate"
  | "open_rate"
  | "click_rate"
  | "unsubscribe_rate"
  | "bounces.hard_rate"
  | "bounces.soft_rate"
  | "bounces.admin_rate"
  | "bounces.block_rate"
  | "bounces.undetermined_rate";

/**
 * Delivery counts and rates for messages attributed to a single recipient mailbox provider. Per-provider results do not include `accepted` or `processed` counts, because we only learn the recipient's mailbox provider once the receiving mail server reports delivery, a bounce, a deferral, or a late bounce. Earlier lifecycle states (accepted, processed) cannot be attributed to a specific provider.
 *
 */
export type EmailMailboxProviderDeliveryStats = {
  /**
   * Distinct recipients whose message the receiving mail server accepted.
   */
  readonly delivered: number;
  /**
   * Distinct recipients whose delivery failed. Approximately the sum of the five `bounces.*` sub-counts (hard, soft, admin, block, undetermined); the totals are computed independently so they may differ slightly at the approximation error.
   */
  readonly bounced: number;
  /**
   * Distinct recipients who reported the message as spam.
   */
  readonly complained: number;
  /**
   * Distinct recipients in transient delivery deferral that is still being retried.
   */
  readonly deferred: number;
  readonly bounces: EmailBounceStatsWithRates;
  /**
   * Share of attempted recipients on this mailbox provider that were delivered, computed as `delivered / (delivered + bounced)`. Null when `delivered + bounced` is zero (no attempts).
   *
   */
  readonly delivery_rate: number | null;
  /**
   * Share of attempted recipients on this mailbox provider that bounced, computed as `bounced / (delivered + bounced)`. Null when `delivered + bounced` is zero (no attempts).
   *
   */
  readonly bounce_rate: number | null;
  /**
   * Share of delivered recipients on this mailbox provider who reported the message as spam, computed as `complained / delivered`. Null when `delivered` is zero.
   *
   */
  readonly complaint_rate: number | null;
};

/**
 * Delivery, engagement, and deliverability stats for messages grouped by a single recipient mailbox provider (`gmail`, `microsoft`, `yahoo`, `apple`, ...) over the requested period. We learn a recipient's mailbox provider from the receiving mail server. Per-provider rows therefore cover the delivery stage onward. They omit the `accepted` and `processed` counts and the `processing` latency family. These fields are absent rather than null. Engagement (opens and clicks, and their rates) is included because those events happen after delivery, once the mailbox provider is already known.
 *
 */
export type EmailMailboxProviderStatsPoint = {
  /**
   * The recipient mailbox provider this row aggregates, as a lowercase classifier such as `gmail`, `yahoo`, `microsoft`, or `apple`. New classifiers may be added over time.
   */
  readonly mailbox_provider: string;
  readonly delivery: EmailMailboxProviderDeliveryStats;
  readonly engagement: EmailEngagementStats;
  readonly latency: EmailDeliveryLatencyStats;
  /**
   * Per-bucket rate series for this mailbox provider over the window. Present only when `include_trend=true`.
   */
  readonly trend?: Array<EmailStatsSeriesPoint>;
};

/**
 * Per-mailbox-provider breakdown for the requested period, ranked by the `sort` metric (default `delivered`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type EmailStatsByMailboxProviderResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: EmailStatsPeriod;
  /**
   * Mailbox-provider breakdown rows, ranked by the `sort` metric (default `delivered`) descending. Empty when no eligible activity occurred in the period.
   */
  readonly data: Array<EmailMailboxProviderStatsPoint>;
  /**
   * Total number of distinct mailbox providers with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped. Raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Delivery, engagement, and deliverability stats for messages grouped by a single mailbox provider and provider region pair over the requested period, for example `gmail` in `NA` or `microsoft` in `EU`. The provider region is the regional pod the receiving mail system reports for the recipient's provider; pairing it with the provider disambiguates a region label that several providers share. Like the mailbox-provider breakdown, rows cover the delivery stage onward: the `accepted` and `processed` counts and the `processing` latency family are omitted (a provider region cannot be attributed before delivery).
 *
 */
export type EmailMailboxProviderRegionStatsPoint = {
  /**
   * The recipient mailbox provider this row aggregates, as a lowercase classifier such as `gmail`, `yahoo`, `microsoft`, or `apple`.
   */
  readonly mailbox_provider: string;
  /**
   * The provider region this row aggregates, as reported by the receiving mail system (for example `NA`, `EU`, `APAC`). The set is open and provider-specific.
   */
  readonly mailbox_provider_region: string;
  readonly delivery: EmailMailboxProviderDeliveryStats;
  readonly engagement: EmailEngagementStats;
  readonly latency: EmailDeliveryLatencyStats;
  /**
   * Per-bucket rate series for this provider region over the window. Present only when `include_trend=true`.
   */
  readonly trend?: Array<EmailStatsSeriesPoint>;
};

/**
 * Per-(mailbox provider, provider region) breakdown for the requested period, ranked by the `sort` metric (default `delivered`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type EmailStatsByMailboxProviderRegionResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: EmailStatsPeriod;
  /**
   * Provider-region breakdown rows, ranked by the `sort` metric (default `delivered`) descending. Empty when no deliveries occurred in the period.
   */
  readonly data: Array<EmailMailboxProviderRegionStatsPoint>;
  /**
   * Total number of distinct mailbox provider and region pairs with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped. Raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Aggregate delivery, engagement, and latency stats for messages sent to a single recipient mailbox domain over the requested period.
 */
export type EmailRecipientDomainStatsPoint = {
  /**
   * The recipient mailbox domain this row aggregates (the part of the recipient address after the `@`), normalized to lowercase.
   */
  readonly recipient_domain: string;
  readonly delivery: EmailDeliveryStats;
  readonly engagement: EmailEngagementStats;
  readonly latency: EmailLatencyStats;
  /**
   * Per-bucket rate series for this recipient domain over the window. Present only when `include_trend=true`.
   */
  readonly trend?: Array<EmailStatsSeriesPoint>;
};

/**
 * Per-recipient-domain breakdown for the requested period, ranked by the `sort` metric (default `processed`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type EmailStatsByRecipientDomainResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: EmailStatsPeriod;
  /**
   * Recipient-domain breakdown rows, ranked by the `sort` metric (default `processed`) descending. Empty when no eligible activity occurred in the period.
   */
  readonly data: Array<EmailRecipientDomainStatsPoint>;
  /**
   * Total number of distinct recipient domains with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped. Raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Delivery, engagement, and latency numbers for every message sent with one template over the requested period.
 */
export type EmailTemplateStatsPoint = {
  /**
   * The template this row is about, using the same `id` the email template endpoints return. Only messages sent with a template appear in this breakdown at all. If the template was deleted after it was used to send, this row still appears, keyed by that same `id`.
   *
   */
  readonly template_id: EmailTemplateId;
  readonly delivery: EmailDeliveryStats;
  readonly engagement: EmailEngagementStats;
  readonly latency: EmailLatencyStats;
  /**
   * A short series of this template's delivery and engagement rates, one point per time bucket over the window. Only present when you set `include_trend=true` on the request.
   *
   */
  readonly trend?: Array<EmailStatsSeriesPoint>;
};

/**
 * Per-template breakdown for the requested period, ranked by the `sort` metric (default `processed`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type EmailStatsByTemplateResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: EmailStatsPeriod;
  /**
   * Template breakdown rows, ranked by the `sort` metric (default `processed`) descending. Empty when no messages were sent with a template in the period.
   */
  readonly data: Array<EmailTemplateStatsPoint>;
  /**
   * Total number of distinct templates with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped. Raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Metric to rank rows by, applied descending. Shared by the engagement-only breakdowns (locations, email clients), which report open and click counts but no rates because delivery events provide no per-dimension denominator.
 *
 */
export type EmailEngagementSortMetric =
  | "opens"
  | "opens_non_prefetched"
  | "unique_opens"
  | "unique_opens_non_prefetched"
  | "clicks"
  | "unique_clicks";

/**
 * Open and click counts for a breakdown row whose dimension is resolved from engagement events only. `opens`, `opens_non_prefetched`, and `clicks` count each event. The same recipient opening or clicking more than once counts each time. The `unique_*` fields count distinct recipients instead, so a recipient who opened five times only counts once there. Rates and unsubscribe counts are not included here. A per-dimension delivered count is unavailable as a rate's denominator, and an unsubscribe event has none of the information this breakdown is grouped by, so it cannot be placed on a row.
 *
 */
export type EmailEngagementCounts = {
  /**
   * Distinct open events, counting repeat opens from the same recipient and opens auto-fetched by inbox privacy features (such as Apple Mail Privacy Protection and the Gmail image proxy).
   *
   */
  readonly opens: number;
  /**
   * Distinct open events excluding those auto-fetched by inbox privacy features. Same event-counting semantics as `opens`, with prefetched opens removed.
   *
   */
  readonly opens_non_prefetched: number;
  /**
   * Distinct recipients who opened at least once, including opens auto-fetched by inbox privacy features.
   */
  readonly unique_opens: number;
  /**
   * Distinct recipients who opened at least once, excluding opens auto-fetched by inbox privacy features.
   */
  readonly unique_opens_non_prefetched: number;
  /**
   * Distinct click events, counting repeat clicks from the same recipient.
   */
  readonly clicks: number;
  /**
   * Distinct recipients who clicked at least once.
   */
  readonly unique_clicks: number;
};

/**
 * Open and click counts for messages engaged with from a single location over the requested period. Location is resolved from open and click events only, so this breakdown reports engagement activity: opens, clicks, and the recipients behind them. It has no delivery counts and no open or click rates, because the receiving mail server reports delivery without a recipient location, preventing a per-location delivered denominator and rates. Each row always includes all three of `country`, `region`, and `city`; the levels below the requested `group_by` are null.
 *
 */
export type EmailLocationStatsPoint = {
  /**
   * The country this row aggregates, as a two-letter country code (ISO 3166-1 alpha-2) resolved from the open or click event. Always present.
   */
  readonly country: string;
  /**
   * The region (state or province) within the country. Populated when `group_by` is `region` or `city`; null at coarser groupings.
   */
  readonly region: string | null;
  /**
   * The city within the region. Populated when `group_by` is `city`; null at coarser groupings.
   */
  readonly city: string | null;
  readonly engagement: EmailEngagementCounts;
};

/**
 * Per-location engagement breakdown for the requested period, grouped at the requested `group_by` granularity, ranked by the `sort` metric (default `unique_opens`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type EmailStatsByLocationResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: EmailStatsPeriod;
  /**
   * Location breakdown rows, ranked by the `sort` metric (default `unique_opens`) descending. Empty when no opens or clicks with a resolved location occurred in the period.
   */
  readonly data: Array<EmailLocationStatsPoint>;
  /**
   * Total number of distinct locations at the requested `group_by` level with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped. Raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Engagement counts for messages opened or clicked from a single email client, operating system, or device type over the requested period. The reading environment is resolved from open and click events only, so this breakdown reports engagement activity: opens, clicks, and the recipients behind them. It has no delivery counts and no open or click rates, because the receiving mail server reports delivery without a client or device, preventing a per-client delivered denominator and rates. Exactly one of `email_client`, `os`, and `device_type` is populated, selected by the request's `group_by`. The other two are null. Inbox-privacy prefetching also affects the detected client. As with open counts, `opens_non_prefetched` excludes opens auto-fetched by an inbox privacy feature. It includes opens caused by a person opening the message.
 *
 */
export type EmailClientStatsPoint = {
  /**
   * The mail client this row aggregates (for example `Gmail`, `Apple Mail`, `Outlook`). Populated only when `group_by=email_client`. Null otherwise.
   */
  readonly email_client: string | null;
  /**
   * The operating system this row aggregates (for example `iOS`, `Android`, `Windows`, `macOS`). Populated only when `group_by=os`. Null otherwise.
   */
  readonly os: string | null;
  /**
   * The device type this row aggregates (for example `mobile`, `desktop`, `tablet`). Populated only when `group_by=device_type`. Null otherwise.
   */
  readonly device_type: string | null;
  readonly engagement: EmailEngagementCounts;
};

/**
 * Per-client engagement breakdown for the requested period, grouped by the requested `group_by` facet, ranked by the `sort` metric (default `unique_opens`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type EmailStatsByClientResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: EmailStatsPeriod;
  /**
   * Client breakdown rows, ranked by the `sort` metric (default `unique_opens`) descending. Empty when no opens or clicks with a detected client occurred in the period.
   */
  readonly data: Array<EmailClientStatsPoint>;
  /**
   * Total number of distinct values of the requested `group_by` facet with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped. Raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Breakdown of `bounced` by failure type. Each field counts distinct bounced recipients of that type in this row's scope; the five types approximately partition `bounced`.
 *
 */
export type EmailBounceStats = {
  /**
   * Distinct recipients with a permanent delivery failure (invalid address or non-existent domain). The address is automatically added to the suppression list.
   *
   */
  readonly hard: number;
  /**
   * Distinct recipients with a transient delivery failure (mailbox full or server temporarily unavailable). Delivery was retried.
   *
   */
  readonly soft: number;
  /**
   * Distinct recipients refused by a policy at the receiving end, such as relaying denied or a blocklisted domain. Fix these by changing your content or sender configuration. Cleaning the recipient list does not usually help.
   *
   */
  readonly admin: number;
  /**
   * Distinct recipients bounced because the receiving mail server blocked the sending IP for reputation reasons (mail block, spam block, spam content). Triage usually focuses on IP reputation and sending volume.
   *
   */
  readonly block: number;
  /**
   * Distinct recipients bounced where the receiving server's response did not allow precise classification.
   *
   */
  readonly undetermined: number;
};

/**
 * Bounce counts for a single SMTP status code over the requested period, with the per-type breakdown. This is a deliverability-debugging view keyed on what the receiving mail server returned, so it only reports the failure side: bounced recipients, and their `hard`, `soft`, `admin`, `block`, and `undetermined` split. It has no delivered, open, or rate fields.
 *
 */
export type EmailBounceCodeStatsPoint = {
  /**
   * The SMTP error code the receiving mail server returned for these bounces, as reported by that server (for example `5.1.1` for an unknown recipient, `4.2.2` for a full mailbox). The form varies by server, and the set of codes is open.
   */
  readonly smtp_error_code: string;
  /**
   * Distinct recipients whose delivery failed with this SMTP status code, approximately equal to the sum of the five `bounces.*` sub-counts. The two are computed independently, so they can differ slightly because of approximation.
   */
  readonly bounced: number;
  readonly bounces: EmailBounceStats;
};

/**
 * Per-SMTP-code bounce breakdown for the requested period, ranked by the `sort` metric (default `bounced`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type EmailStatsByBounceCodeResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: EmailStatsPeriod;
  /**
   * Bounce-code breakdown rows, ranked by the `sort` metric (default `bounced`) descending. Empty when no bounces occurred in the period.
   */
  readonly data: Array<EmailBounceCodeStatsPoint>;
  /**
   * Total number of distinct SMTP error codes with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped. Raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Complaint counts for a single feedback-loop complaint type over the requested period. A complaint type is recorded only on spam-complaint events, so this breakdown reports the complained count for each type and nothing else. A complaint event has no delivery or engagement information attached to it, so no other count applies.
 *
 */
export type EmailComplaintTypeStatsPoint = {
  /**
   * The complaint classification reported by the mailbox provider's feedback loop, in the abuse-reporting-format vocabulary (for example `abuse`, `fraud`, `virus`, `other`). The set is open.
   */
  readonly feedback_type: string;
  /**
   * Distinct recipients who reported a message as spam with this complaint type at any point in the period.
   */
  readonly complained: number;
};

/**
 * Per-complaint-type breakdown for the requested period, ranked by `complained` descending and capped at the requested `limit` (default 50, max 200).
 */
export type EmailStatsByComplaintTypeResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: EmailStatsPeriod;
  /**
   * Complaint-type breakdown rows, ranked by `complained` descending. Empty when no complaints occurred in the period.
   */
  readonly data: Array<EmailComplaintTypeStatsPoint>;
  /**
   * Total number of distinct feedback types with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped. Raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Delivery, engagement and latency figures for one broadcast's messages over the period you asked for.
 */
export type EmailBroadcastStatsPoint = {
  /**
   * The broadcast this row covers, the same ID the broadcast endpoints return. Only mail sent as part of a broadcast has a broadcast ID, so one-off and transactional sends do not appear in this breakdown at all.
   */
  readonly broadcast_id: string;
  readonly delivery: EmailDeliveryStats;
  readonly engagement: EmailEngagementStats;
  readonly latency: EmailLatencyStats;
};

/**
 * Per-broadcast breakdown for the requested period, ranked by the `sort` metric (default `processed`) descending and capped at the requested `limit` (default 50, max 200).
 */
export type EmailStatsByBroadcastResponse = {
  /**
   * The date range the response covers (echoed back from the request), plus `data_as_of`, the freshness boundary the data is current to.
   */
  period: EmailStatsPeriod;
  /**
   * Broadcast breakdown rows, ranked by the `sort` metric (default `processed`) descending. Empty when no broadcast messages were active in the period.
   */
  readonly data: Array<EmailBroadcastStatsPoint>;
  /**
   * Total number of distinct broadcasts with activity in the period, regardless of `limit`. When it exceeds the number of rows returned, the ranking was capped. Raise `limit` (up to 200) or narrow the window to see more.
   *
   */
  readonly total: number;
};

/**
 * Per-domain behavior toggles. Changes apply immediately to new sends.
 *
 */
export type DomainSettings = {
  /**
   * Rewrite links in HTML email through your tracking domain to record clicks. You can enable this before your tracking domain has verified; it begins working once verification completes. A tracking domain must be configured; enabling it without one returns `409`.
   *
   */
  click_tracking?: boolean;
  /**
   * Insert a tracking pixel in HTML email to record opens. You can enable this before your tracking domain has verified: it begins working once verification completes. A tracking domain must be configured; enabling it without one returns `409`.
   *
   */
  open_tracking?: boolean;
};

/**
 * Active DKIM signing configuration for the domain.
 */
export type DomainDkim = {
  /**
   * How the DKIM public key is published in your DNS. `txt`: you publish the key as a TXT record. `delegated`: you publish a single CNAME and we host and rotate the key.
   *
   */
  readonly mode: "txt" | "delegated";
  /**
   * DKIM selector used to sign mail from this domain.
   */
  readonly selector: string;
  /**
   * RSA key size in bits.
   */
  readonly key_size: number;
};

/**
 * A staged configuration change awaiting DNS verification. The currently active configuration keeps serving until the staged one verifies, at which point it is promoted automatically. Submitting another change for the same capability replaces the staged value.
 *
 */
export type DomainCapabilityPending = {
  /**
   * Hostname the capability uses after the staged change verifies.
   */
  readonly domain: string;
  /**
   * Verification status of the staged change.
   *
   * - `pending`: the DNS records have not been detected yet.
   * - `failed`: the records resolved with wrong values; correct them
   * or submit a different change.
   * - `temporary_failure`: the DNS lookup failed transiently and is
   * queued for retry.
   *
   */
  readonly status: "pending" | "failed" | "temporary_failure";
};

export type DomainCapability = {
  /**
   * Capability verification status.
   *
   * - `pending`: verification has not run, or is currently running.
   * - `verified`: all DNS records for this capability resolved with the
   * expected values.
   * - `warning`: a record for this capability verified before and a recent
   * check no longer matches, but it is still within the grace period.
   * Sending is not yet affected; fix it before the grace period ends.
   * - `failed`: DNS records resolved but at least one value is wrong.
   * Update your DNS to recover.
   * - `temporary_failure`: DNS lookup failed transiently. Verification retries
   * automatically; do not change DNS records unless they are incorrect.
   * - `not_configured`: the capability is not set up on this domain
   * (for example, no tracking domain configured).
   *
   */
  readonly status:
    | "pending"
    | "verified"
    | "warning"
    | "failed"
    | "temporary_failure"
    | "not_configured";
  /**
   * Hostname this capability is configured with: the return-path domain, the tracking domain, or the domain where the DMARC policy was found. `null` when not applicable or not configured.
   *
   */
  readonly domain?: string | null;
  pending?: DomainCapabilityPending;
  /**
   * Machine-readable reason code for a failed capability status. Only set when
   * `status` is `failed`. Use this to display a specific message to users rather
   * than a generic failure message.
   *
   * - `tracking_domain_in_use`: the link tracking subdomain is already claimed
   * by another organization.
   *
   */
  readonly reason?: string | null;
};

export type DomainCapabilities = {
  /**
   * Overall authorization to send from this domain. Verified when the DKIM record, the return-path CNAME, and a DMARC policy are all in place. Required for live sends.
   *
   */
  sending: DomainCapability;
  /**
   * Return-path (bounce) CNAME verification. The return-path domain receives bounce and complaint notifications and is what mailbox providers check for SPF: no separate SPF record is needed.
   *
   */
  return_path: DomainCapability;
  /**
   * DMARC policy check. Satisfied by any valid DMARC record covering the sending domain: on the domain itself or on its registered (organizational) domain; `domain` reports where the policy was found. A minimal policy of `p=none` is sufficient.
   *
   */
  dmarc: DomainCapability;
  /**
   * Branded open/click tracking domain. `not_configured` until a tracking domain is set. Tracked links are served over HTTPS once the CNAME verifies.
   *
   */
  tracking: DomainCapability;
  /**
   * Inbound mail receiving. `not_configured` until receiving is enabled on this domain (see `DomainUpdate.inbound`), then `pending` while the published MX records are checked, and `verified` once they resolve to us. The MX records to publish are always listed under `dns_records` (`purpose: inbound_mx`) as a regional reference, even while this is `not_configured`: enabling is what actually starts delivery.
   *
   */
  inbound?: DomainCapability;
};

export type DnsRecord = {
  /**
   * The DNS record type to publish, determined by `purpose`.
   *
   * - `TXT`: used for the `dkim` and `dmarc` purposes.
   * - `CNAME`: used for the `return_path` and `tracking` purposes.
   * - `MX`: used for the `inbound_mx` purpose.
   *
   */
  type: "TXT" | "CNAME" | "MX";
  /**
   * The record name: the part you enter in your DNS provider's `Name` or `Host` field, relative to the DNS zone the record belongs in (your registered domain). For a sending domain `mail.acme.com` the DKIM record name is `bird1._domainkey.mail`, entered in the `acme.com` zone. `@` for records at the zone apex.
   *
   */
  name: string;
  /**
   * The fully qualified hostname for this record (for example, `bird1._domainkey.mail.acme.com`).
   *
   */
  host: string;
  /**
   * The value to publish, as entered in your DNS provider's `Value` or `Content` field. For `TXT`, enter the full record content. For `CNAME`, enter the target hostname. For `MX`, enter the priority followed by the mail server hostname.
   *
   */
  value: string;
  /**
   * What this record is for.
   *
   * - `dkim`: signs outbound mail and proves domain ownership.
   * - `return_path`: identifies the return-path (bounce) CNAME for sending.
   * - `tracking`: identifies the optional branded open/click tracking CNAME.
   * - `inbound_mx`: identifies the MX record routing mail to us for receiving.
   * Always present wherever inbound is available, as a regional reference,
   * regardless of whether receiving is enabled; publishing it does not
   * enable receiving on its own: see `DomainUpdate.inbound`. It is
   * `optional` until receiving is enabled, and publishing it before then
   * is destructive: on a domain at the zone apex it replaces the MX
   * records that carry the domain's existing mail.
   * - `dmarc`: identifies the advisory DMARC policy record.
   *
   */
  purpose: "dkim" | "return_path" | "tracking" | "inbound_mx" | "dmarc";
  /**
   * Lifecycle state of this record.
   *
   * - `active`: the record backs the domain's current configuration.
   * - `pending`: the record belongs to a staged configuration change;
   * publish it to complete the change.
   * - `deprecated`: the record belonged to a previous configuration.
   * Keep it in DNS until `safe_to_remove` is `true`; in-flight mail and
   * previously sent tracked links may still resolve through it.
   *
   */
  readonly state: "active" | "pending" | "deprecated";
  /**
   * Whether this record can be skipped. An optional record enables extra functionality (branded tracking, or receiving) rather than sending, so publish one only when you want what it enables. The `inbound_mx` records are optional until you enable receiving on the domain, and publishing one before then changes where mail to the domain is delivered.
   *
   */
  readonly optional: boolean;
  /**
   * Verification status of this record's most recent DNS check.
   *
   * - `pending`: the record has not verified yet; publish it (or correct it)
   * and it verifies on the next check.
   * - `verified`: the most recent check matched the expected value.
   * - `warning`: the record verified before and a recent check no longer
   * matched, but it is still within the grace period. Sending is not yet
   * affected; fix the record before the grace period ends to avoid it
   * being blocked.
   * - `failed`: the record verified before but later checks kept failing
   * past the grace period; the configuration has regressed and needs
   * attention.
   *
   */
  readonly status: "pending" | "verified" | "warning" | "failed";
  /**
   * Human-readable detail for a failed check on this record: what was found in DNS and why it did not match. `null` when the record is verified or not yet checked.
   *
   */
  readonly error?: string | null;
  /**
   * Only set on `deprecated` records: `true` once the record is no longer referenced by in-flight mail or live tracked links and can be deleted from your DNS. `null` on `active` and `pending` records.
   *
   */
  readonly safe_to_remove?: boolean | null;
};

export type Domain = {
  readonly id: DomainId;
  readonly workspace_id: WorkspaceId;
  /**
   * The sending domain name. Set at creation and immutable.
   */
  readonly domain: string;
  /**
   * The DNS provider hosting this domain's nameservers, so you know which provider's dashboard to manage the required DNS records in. Returns `other` when the provider has not been detected or is not recognized.
   *
   */
  readonly vendor:
    | "other"
    | "cloudflare"
    | "route53"
    | "godaddy"
    | "namecheap"
    | "google"
    | "azure"
    | "digitalocean"
    | "squarespace";
  /**
   * Domain ownership verification, proven by the DKIM record. Readiness to
   * send or track is reported separately per capability under
   * `capabilities.*.status`.
   *
   * - `pending`: the DKIM record has not been published yet.
   * - `verified`: the DKIM record is in place; ownership is confirmed.
   * - `failed`: a DKIM record exists but does not match the expected
   * value (for example a stale record from an earlier setup), or a
   * previously verified record was removed. Correct the record to
   * recover.
   * - `temporary_failure`: DNS resolution failed transiently, such as from a
   * timeout or unreachable nameserver. Verification retries automatically;
   * do not change the DNS records unless they are incorrect.
   * - `rejected`: the domain was refused for policy reasons and cannot be
   * used for sending. Contact support if you believe this is an error.
   *
   */
  readonly status:
    "pending" | "verified" | "failed" | "temporary_failure" | "rejected";
  settings: DomainSettings;
  /**
   * What to do next about this domain, given the state it is in. Each entry names one action and says
   * why it is worth taking, so you can act on this response without working out the order
   * yourself. Present on reads that compute it: an empty list means there is nothing to do,
   * and the field is absent entirely on responses that do not report next actions.
   *
   * This answers whether you own the domain, which is what `status` reports. What each
   * capability still needs before it can send or receive is reported separately under
   * `capabilities`, so an empty list here does not on its own mean the domain is ready.
   *
   */
  readonly next?: Array<NextAction>;
  readonly dkim: DomainDkim;
  capabilities: DomainCapabilities;
  /**
   * The domain's DNS records and their individual verification state, returned in full on both the list and single-domain responses. This is the complete set to publish across DKIM, return-path, DMARC, tracking, and inbound; records for a staged change carry `state: pending`. Inbound MX records are always included as a regional reference, even while receiving is off and `capabilities.inbound.status` is `not_configured`. Their presence alone does not mean receiving is enabled; see `DomainUpdate.inbound`.
   *
   */
  readonly dns_records: Array<DnsRecord>;
  /**
   * When we last checked this domain's DNS records, whether or not the outcome changed. Updated on every verification: your manual refresh and the periodic automatic re-checks alike. `null` if the domain has never been checked.
   *
   */
  readonly last_checked_at?: string | null;
  /**
   * When the domain's ownership was confirmed: the moment `status` became `verified` via the DKIM record. Unchanged by later re-checks while it stays verified. `null` if the domain has never been verified.
   *
   */
  readonly verified_at?: string | null;
  /**
   * When the domain was added.
   */
  readonly created_at: string;
  /**
   * When the domain's configuration was last changed (such as a settings or return-path change). Verification re-checks do not change this; see `last_checked_at` and `verified_at` for verification timing.
   *
   */
  readonly updated_at: string;
};

export type DomainList = {
  /**
   * Page of sending domains, newest first by default.
   */
  data: Array<Domain>;
} & ListEnvelopeWithTotal;

/**
 * Return-path (bounce) domain configuration. The return-path domain receives bounce and complaint notifications for mail sent from this domain and is what mailbox providers check for SPF. Provide only the name part; we add the sending domain automatically.
 *
 */
export type DomainReturnPathConfig = {
  /**
   * Name part to use for the return-path domain. For example, `send` on `mail.acme.com` becomes `send.mail.acme.com`. Defaults to `send` when omitted at creation.
   *
   */
  name: string;
};

/**
 * Tracking domain configuration for branded open and click tracking URLs. Provide only the name part; we add the sending domain automatically. A domain created with no tracking configuration defaults to `links`. Tracked links are served over HTTPS after the tracking record verifies.
 *
 */
export type DomainTrackingConfig = {
  /**
   * Name part to use for branded open and click tracking URLs. For example, `links` on `mail.acme.com` becomes `links.mail.acme.com`.
   *
   */
  name: string;
};

/**
 * DKIM signing configuration.
 */
export type DomainDkimConfig = {
  /**
   * How the DKIM public key is published in your DNS.
   *
   * - `txt` (default): you publish the DKIM public key as a TXT record. Key
   * rotation requires updating the record.
   * - `delegated`: you publish a CNAME that points to a DKIM key we host and
   * rotate. This mode is unavailable for new configurations; supplying it
   * returns `422`.
   *
   */
  mode?: "txt" | "delegated";
};

export type DomainCreate = {
  /**
   * The domain you send from: the domain of your `from` addresses. Use a dedicated subdomain (for example, `mail.acme.com`) rather than your registered domain so sending reputation stays separate from other services on the domain.
   *
   */
  domain: string;
  return_path?: DomainReturnPathConfig;
  tracking?: DomainTrackingConfig;
  dkim?: DomainDkimConfig;
  settings?: DomainSettings;
};

/**
 * Inbound (receiving) configuration. Enable inbound to receive email addressed to this domain. We return MX records to publish. After they verify, mail to any local-part at this domain is delivered as an inbound message and triggers the `email.received` webhook. Use a dedicated subdomain, such as `inbound.acme.com`, because using your apex domain would capture your corporate mail.
 *
 */
export type DomainInboundConfig = {
  /**
   * Set `true` to enable receiving on this domain, `false` to disable it. Disabling tears receiving down and removes the MX records from `dns_records`; this is immediate in the normal case, and if a step needs retrying the capability clears as soon as teardown finishes.
   *
   */
  enabled: boolean;
};

/**
 * Partial update. `settings` changes apply immediately. Changes to `return_path`, `tracking`, or `dkim` on a verified capability are staged. The current configuration keeps serving until the new DNS records verify. The change is then promoted automatically and the old records are marked `deprecated`. The staged value is visible under `capabilities.*.pending` and can be replaced by submitting another change.
 *
 */
export type DomainUpdate = {
  settings?: DomainSettings;
  /**
   * Change the return-path name part. Cannot be removed: the return-path is required for sending.
   *
   */
  return_path?: DomainReturnPathConfig;
  /**
   * Set or change the tracking name part, or remove tracking by passing `null`. Removal requires `click_tracking` and `open_tracking` to be disabled first, and returns `409` otherwise. After removal, links in previously sent email keep resolving while the tracking records are reported as `deprecated`.
   *
   */
  tracking?: DomainTrackingConfig | null;
  /**
   * Change how the DKIM key is published. The current key keeps signing until the new configuration verifies, so mail is never sent unsigned during the transition.
   *
   */
  dkim?: DomainDkimConfig;
  /**
   * Enable or disable receiving on this domain. Enabling claims the domain for inbound and moves `capabilities.inbound.status` from `not_configured` to `pending`, then `verified` once the MX records resolve to us. The MX records to publish are always present under `dns_records` (`purpose: inbound_mx`) as a regional reference. Their presence does not mean receiving is enabled; enable the domain whenever `capabilities.inbound.status` is `not_configured`. Enabling requires the domain's DKIM to be verified first. A fresh enable on a domain whose DKIM is not verified returns `422` with `E05019` and claims nothing. A domain already receiving inbound for another organization returns `422` with `E05018`.
   *
   */
  inbound?: DomainInboundConfig;
};

export type DomainEventId = string;

export type DomainEvent = {
  /**
   * Event ID.
   */
  readonly id: DomainEventId;
  /**
   * Type of domain event. `domain.status_changed` tracks ownership verification through the domain-level `status`. `domain.sending_status_changed` tracks readiness to send through `capabilities.sending`. The remaining `*_status_changed` types each track one DNS record's verification. Open enum: new event types may be added over time, so treat any unrecognized value as a future event rather than an error. The values below are the types known at this version.
   */
  type: string;
  /**
   * Human-readable summary of what changed.
   */
  summary: string;
  /**
   * Structured details for the event. Status-change events carry `from` and `to`; record-level changes also carry `domain`, the affected hostname.
   */
  metadata: {
    [key: string]: unknown;
  };
  /**
   * When the event was recorded.
   */
  created_at: string;
};

export type DomainEventList = {
  /**
   * Page of domain events, newest first by default.
   */
  data: Array<DomainEvent>;
} & ListEnvelope;

export type ShareDomainDnsRequest = {
  /**
   * Email recipients for the domain's current DNS records. The first address is the direct recipient and the rest are copied on the same email; duplicates are ignored. Any invalid address fails the whole request with `422`.
   */
  emails: Array<string>;
};

export type SuppressionId = string;

export type SuppressionScope = {
  /**
   * How widely the email suppression applies. Responses currently use `workspace`, which blocks the address for every email sent by the workspace. WhatsApp suppressions use a separate list.
   *
   */
  type: "workspace" | "category" | "audience" | "topic" | "contact" | "domain";
  /**
   * Public ID or alias of the scoped resource. For workspace scope, this is the workspace ID.
   *
   */
  id: string;
};

export type Suppression = {
  readonly id: SuppressionId;
  /**
   * The suppressed address, stored lowercase.
   */
  email: string;
  scope: SuppressionScope;
  /**
   * Why the address is suppressed:
   *
   * - `hard_bounce`: A delivery permanently failed.
   * - `complaint`: The recipient reported a message as spam.
   * - `manual`: Added through the API or dashboard.
   *
   * An address can hold one record per reason. This list grows over time. Treat unknown values as informational rather than rejecting the record.
   *
   */
  reason: string;
  /**
   * How the suppression came to exist:
   *
   * - `bounce_event`: Created automatically from a hard bounce.
   * - `complaint_event`: Created from a spam complaint.
   * - `api_key`: Added through the API with an API key.
   * - `user`: Added by a user in the dashboard.
   *
   * This list grows over time. Treat unknown values as informational rather than rejecting the record.
   *
   */
  origin: string;
  /**
   * Which sends the suppression blocks.
   *
   * - `all`: blocks every message category, including transactional.
   * - `non_transactional`: blocks marketing but allows transactional messages.
   * A recipient who complained can therefore still receive
   * mail such as password resets.
   * - `category`: scopes the block to a preference category and blocks every
   * category until one is set.
   *
   * This list grows over time, and any value other than `non_transactional`
   * blocks every category, so treat an unknown value as blocking the send.
   *
   */
  applies_to: string;
  /**
   * ID of the email that triggered suppression. Null for manual additions.
   */
  source_email_id?: EmailId | null;
  /**
   * ID of the recipient event that triggered suppression. Null for manual additions.
   */
  source_recipient_id?: RecipientId | null;
  /**
   * When the address was suppressed.
   */
  readonly created_at: string;
};

export type SuppressionList = {
  /**
   * Page of suppression records.
   */
  data: Array<Suppression>;
} & ListEnvelope;

export type SuppressionCreate = {
  /**
   * The address to stop sending to. Normalized before storage and matching: lowercased and trimmed of surrounding whitespace.
   *
   */
  email: string;
};

export type Actor = {
  /**
   * Actor identifier.
   */
  id: string;
  /**
   * Who or what performed the action: `user` for a member's own session, `oauth_token` for a token issued to a caller on a member's behalf, `api_key` for a workspace API key, `system` for our own automation, `sso` for an organization's SSO connection, and `service_account` for a workspace's connected Integration acting with no member behind it. Open enum: new actor types may be added over time, so treat any unrecognized value as a future type rather than an error.
   */
  type: string;
  /**
   * The label the actor is shown under: typically a member's name or email address, or the API key's name. Null when it could not be resolved.
   *
   */
  readonly display_name?: string | null;
};

export type InboundAddressId = string;

/**
 * An email address we create for you, which receives mail on your behalf. Forward a real mailbox (for example, a support inbox) to this address. Every message sent to it becomes a received email you can retrieve.
 *
 */
export type InboundAddress = {
  /**
   * Inbound address ID.
   */
  readonly id: InboundAddressId;
  /**
   * The address to forward your mailbox to. We generate it when the inbound address is created.
   */
  readonly address: string;
  /**
   * Your own label for this address, typically the source mailbox it maps to. `null` when unset.
   */
  label: string | null;
  /**
   * When the inbound address was created.
   */
  readonly created_at: string;
  /**
   * When the inbound address was last updated.
   */
  readonly updated_at: string;
};

export type InboundAddressList = {
  /**
   * Page of inbound addresses, newest first.
   */
  data: Array<InboundAddress>;
} & ListEnvelope;

/**
 * Parameters for minting a new inbound address.
 */
export type InboundAddressCreate = {
  /**
   * Your own label for this address, typically the source mailbox it maps to.
   */
  label?: string;
};

/**
 * Fields to update on an inbound address.
 */
export type InboundAddressUpdate = {
  /**
   * Your own label for this address, typically the source mailbox it maps to. Send `null` to clear it. Omit the field to leave it unchanged.
   */
  label?: string | null;
};

export type InboundEmailMessageId = string;

export type InboundAttachmentId = string;

/**
 * Metadata for a file attached to a received email. The raw bytes are fetched separately with `GET /v1/email/inbound-messages/{inbound_message_id}/attachments/{attachment_id}`.
 *
 */
export type InboundAttachment = {
  /**
   * Attachment ID, stable within the received message.
   */
  readonly id: InboundAttachmentId;
  /**
   * Filename from the attachment's Content-Disposition, or `null` when the sender did not name the part.
   */
  filename: string | null;
  /**
   * MIME type parsed from the attachment part, or `null` when absent.
   */
  content_type: string | null;
  /**
   * Size of the attachment in bytes.
   */
  size: number;
};

/**
 * An email received on your behalf, parsed from the original message. Fetch the body with `/body`, the original MIME with `/raw`, and attachment bytes with `/attachments/{attachment_id}`.
 *
 */
export type InboundEmailMessage = {
  /**
   * Received message ID.
   */
  readonly id: InboundEmailMessageId;
  /**
   * Sender address parsed from the message.
   */
  from: EmailAddress;
  /**
   * Recipients on the message's To header.
   */
  to: Array<EmailAddress>;
  /**
   * Recipients on the message's Cc header.
   */
  cc: Array<EmailAddress>;
  /**
   * Subject line as received, or `null` when the message had no subject.
   */
  subject: string | null;
  /**
   * RFC 5322 Message-ID header from the sender, or `null` when the sender did not include one.
   */
  message_id: string | null;
  /**
   * The `In-Reply-To` header, which holds the Message-ID this message is replying to. `null` when the message is not a reply.
   */
  in_reply_to: string | null;
  /**
   * The References header, which holds every Message-ID in this conversation, oldest first. Left out when the message arrived without one.
   */
  references?: Array<string>;
  /**
   * Conversation this message belongs to, or `null` when it is not grouped into one.
   */
  thread_id: string | null;
  /**
   * Whether the sender of the received message was authenticated:
   *
   * - `pass`: The sender's identity was verified.
   * - `fail`: The sender's identity was checked and did not verify.
   * - `unknown`: No verdict is available, so the sender should not be treated as verified.
   *
   */
  authentication: "pass" | "fail" | "unknown" | null;
  /**
   * Whether SPF passed for the sender, parsed from the message's authentication results. `null` when the authentication results did not include an SPF verdict.
   */
  spf_pass: boolean | null;
  /**
   * Whether DKIM passed for the sender, parsed from the message's authentication results. `null` when the authentication results did not include a DKIM verdict.
   */
  dkim_pass: boolean | null;
  /**
   * Whether DMARC passed for the sender, parsed from the message's authentication results. `null` when the authentication results did not include a DMARC verdict.
   */
  dmarc_pass: boolean | null;
  /**
   * Spam score on the received message, or `null` when no score is available.
   */
  spam_score: number | null;
  /**
   * Metadata for each attachment found on the message. Empty when the message had no attachments.
   */
  attachments: Array<InboundAttachment>;
  /**
   * When the message was received.
   */
  readonly received_at: string;
};

export type InboundEmailMessageList = {
  /**
   * Page of received emails, newest first.
   */
  data: Array<InboundEmailMessage>;
} & ListEnvelope;

/**
 * The parsed body of a received email.
 */
export type InboundEmailMessageBody = {
  /**
   * The HTML body of the message, or `null` when the message had no HTML part.
   */
  html: string | null;
  /**
   * The plain-text body of the message, or `null` when the message had no text part.
   */
  text: string | null;
};

/**
 * The attachments on a received email. The response returns every attachment without pagination.
 */
export type InboundAttachmentList = {
  /**
   * Metadata for every attachment on the message. Empty when the message had no attachments.
   */
  data: Array<InboundAttachment>;
};

export type MailboxId = string;

/**
 * The principal that owns the mailbox. Always the workspace.
 */
export type MailboxOwner = {
  /**
   * Owner principal type.
   */
  readonly type: "workspace";
  /**
   * Owner principal ID.
   */
  readonly id: WorkspaceId;
};

/**
 * A durable mailbox identity for an agent. A mailbox owns an email address, groups mail into threads, applies receive policy, and remembers message metadata and extracted text for its retention tier. The original rendered source of each message remains available for 30 days.
 *
 */
export type Mailbox = {
  /**
   * Mailbox ID.
   */
  readonly id: MailboxId;
  /**
   * The mailbox's email address. Immutable once created.
   */
  readonly address: string;
  /**
   * Display name used as the sender name on mail from this mailbox. `null` when unset.
   */
  display_name: string | null;
  /**
   * Default `Reply-To` address stamped on mail sent from this mailbox. `null` when unset.
   */
  default_reply_to: string | null;
  /**
   * Which inbound mail the mailbox accepts:
   *
   * - `open`: Accepts everything not blocked by a rule.
   * - `replies_only`: Accepts only replies to messages this mailbox has
   * sent. A reply must match a message the mailbox sent. Landing in an
   * existing thread by itself does not count.
   * - `allowlist`: Accepts only senders matching an allow rule. Replies to
   * prior outbound mail are always admitted unless blocked.
   * - `drop`: Stores nothing.
   *
   */
  receive_policy: "open" | "replies_only" | "allowlist" | "drop";
  /**
   * Lifecycle state. Suspended mailboxes stop emitting events. Inbound mail is retained as blocked.
   */
  readonly state: "active" | "suspended";
  /**
   * The channel this mailbox receives on. Always `email`.
   */
  readonly channel: "email";
  readonly owner: MailboxOwner;
  /**
   * The underlying inbound address that receives this mailbox's mail.
   */
  readonly inbound_address_id: InboundAddressId;
  /**
   * How long the mailbox remembers message metadata and extracted text. Original rendered source (HTML, raw message, attachments) is always available for 30 days regardless of tier.
   */
  retention_tier: "30d" | "90d" | "1y";
  /**
   * Number of retained messages across all threads.
   */
  readonly message_count: number;
  /**
   * Number of retained threads.
   */
  readonly thread_count: number;
  /**
   * Number of threads with unread messages in this mailbox, excluding trash. `null` on create/update responses.
   *
   */
  readonly unread_thread_count?: number | null;
  /**
   * Your own key/value data attached to the mailbox. Up to 2 KB. Keys starting with `__bird` are reserved.
   */
  metadata: {
    [key: string]: unknown;
  };
  /**
   * Whether we generated the local part of the address. `false` means a custom handle was chosen at creation. On the shared `inbox.ai` domain a custom handle counts against your plan's custom-handle allowance.
   */
  readonly local_part_generated?: boolean;
  /**
   * When the mailbox was created.
   */
  readonly created_at: string;
  /**
   * When the mailbox was last updated.
   */
  readonly updated_at: string;
  /**
   * When the mailbox was deleted, or `null` if it is active. A deleted mailbox stops receiving mail immediately but can be restored for 30 days, after which it and its remembered messages are permanently removed.
   */
  readonly deleted_at?: string | null;
};

export type MailboxList = {
  data: Array<Mailbox>;
} & ListEnvelope;

/**
 * Parameters for creating a mailbox.
 */
export type MailboxCreate = {
  /**
   * The local part of the mailbox address (the part before `@`). Letters, digits, dots, underscores, and hyphens. Stored lowercase. On the shared `inbox.ai` domain, separators must sit between letters or digits. Leading, trailing, and repeated separators are not allowed. Reserved names such as `postmaster` and `abuse` are unavailable. Choosing your own local part uses one of your plan's custom-handle allowance slots; generated addresses remain available. Omit this field to generate a random local part.
   */
  local_part?: string;
  /**
   * The domain the address lives under. Defaults to `inbox.ai`, our shared mailbox domain. Creating a mailbox claims the shared address for your organization on a first-come, first-served basis. The address remains reserved to your organization after the mailbox is deleted. You can instead use one of your own domains enabled for receiving email.
   */
  domain?: string;
  /**
   * Display name used as the sender name on mail from this mailbox.
   */
  display_name?: string;
  /**
   * Default `Reply-To` address stamped on mail sent from this mailbox.
   */
  default_reply_to?: string;
  /**
   * Which inbound mail the mailbox accepts:
   *
   * - `open`: Accepts everything not blocked by a rule.
   * - `replies_only`: Accepts only replies to messages this mailbox has
   * sent. A reply must match a message the mailbox sent. Landing in an
   * existing thread by itself does not count.
   * - `allowlist`: Accepts only senders matching an allow rule.
   * - `drop`: Stores nothing.
   *
   */
  receive_policy?: "open" | "replies_only" | "allowlist" | "drop";
  /**
   * How long the mailbox remembers message metadata and extracted text. Original rendered source is always available for 30 days regardless of tier.
   */
  retention_tier?: "30d";
  /**
   * Your own key/value data to attach to the mailbox. Up to 2 KB. Keys starting with `__bird` are reserved.
   */
  metadata?: {
    [key: string]: unknown;
  };
};

/**
 * Fields to update on a mailbox. Omitted fields are unchanged. Fields set to `null` are cleared. The address and domain are immutable.
 */
export type MailboxUpdate = {
  /**
   * Display name used as the sender name on mail from this mailbox. `null` clears it.
   */
  display_name?: string | null;
  /**
   * Default `Reply-To` address stamped on mail sent from this mailbox. `null` clears it.
   */
  default_reply_to?: string | null;
  /**
   * Which inbound mail the mailbox accepts:
   *
   * - `open`: Accepts everything not blocked by a rule.
   * - `replies_only`: Accepts only replies to messages this mailbox has
   * sent. A reply must match a message the mailbox sent. Landing in an
   * existing thread by itself does not count.
   * - `allowlist`: Accepts only senders matching an allow rule.
   * - `drop`: Stores nothing.
   *
   */
  receive_policy?: "open" | "replies_only" | "allowlist" | "drop";
  /**
   * How long the mailbox remembers message metadata and extracted text. Lowering the tier deletes remembered messages older than the new horizon, and requires `confirm=true` when that would happen.
   */
  retention_tier?: "30d";
  /**
   * Replaces the mailbox's key/value data. Up to 2 KB. Keys starting with `__bird` are reserved.
   */
  metadata?: {
    [key: string]: unknown;
  };
};

/**
 * Single-row aggregate of the mailbox's email activity across the full requested period. Counts are sums of per-bucket counts across the window. Latency percentiles are computed across the whole period rather than summed per bucket. Rates are `null` when their denominator is zero.
 *
 */
export type MailboxStatsSummary = {
  /**
   * Distinct email messages the mailbox sent that were accepted, counted at the message level and summed per bucket across the period.
   */
  readonly sends_accepted: number;
  readonly delivery: EmailDeliveryStats;
  readonly engagement: EmailEngagementStats;
  readonly latency: EmailLatencyStats;
  /**
   * Distinct emails the mailbox received, summed per bucket across the period.
   */
  readonly received: number;
};

/**
 * Per-mailbox email activity for one time bucket, bucketed by event time. Sent-mail metrics use the same delivery, engagement, and latency breakdowns as the email stats endpoints. `received` counts mail that arrived at the mailbox. Buckets with no activity are included with zero counts and `null` latency percentiles.
 *
 */
export type MailboxStatsPoint = {
  /**
   * The day (`YYYY-MM-DD`) or instant (RFC 3339, on the bucket boundary) this point covers, matching the period's grain.
   */
  readonly bucket: string;
  /**
   * Distinct email messages the mailbox sent that were accepted in this bucket, counted at the message level (one per accepted send regardless of how many recipients it addresses). Every other sent-mail metric in `delivery` and `engagement` is recipient-level or event-level.
   *
   */
  readonly sends_accepted: number;
  readonly delivery: EmailDeliveryStats;
  readonly engagement: EmailEngagementStats;
  readonly latency: EmailLatencyStats;
  /**
   * Distinct emails the mailbox received in this bucket.
   */
  readonly received: number;
};

/**
 * A mailbox's sent and received email statistics: a period-wide summary plus a bucketed time series. `period` echoes the range and grain actually used. `data` is one row per bucket in chronological order.
 *
 */
export type MailboxStatsResponse = {
  period: EmailStatsSeriesPeriod;
  summary: MailboxStatsSummary;
  /**
   * One row per bucket in the period, in chronological order. Buckets with no activity are included with zero counts.
   */
  readonly data: Array<MailboxStatsPoint>;
};

export type ReceiveRuleId = string;

/**
 * An allow or block entry on a mailbox, evaluated when inbound mail arrives. Matching is against the message's envelope sender; domain entries also match subdomains. A given entry can be allow or block, never both.
 *
 */
export type ReceiveRule = {
  /**
   * Identifies this rule for deletion. There is no update operation.
   */
  readonly id: ReceiveRuleId;
  /**
   * The mailbox the rule applies to.
   */
  readonly mailbox_id: MailboxId;
  /**
   * What the rule does when it matches. Block rules always win: over allow rules and over the reply admission on allowlist mailboxes.
   */
  readonly action: "allow" | "block";
  /**
   * The sender address or domain the rule matches. Domains also match their subdomains.
   */
  readonly entry: string;
  /**
   * Whether the entry is a full address or a domain.
   */
  readonly entry_type: "address" | "domain";
  /**
   * Your own note about why the rule exists. `null` when unset.
   */
  readonly note: string | null;
  /**
   * When the rule was created.
   */
  readonly created_at: string;
};

export type ReceiveRuleList = {
  data: Array<ReceiveRule>;
} & ListEnvelope;

/**
 * Parameters for adding a receive rule to a mailbox.
 */
export type ReceiveRuleCreate = {
  /**
   * What the rule does when it matches. Block rules always win. To flip an entry's action, delete the existing rule and re-create it.
   */
  action: "allow" | "block";
  /**
   * The sender address (`alice@example.com`) or domain (`example.com`) to match. Domains also match their subdomains. Stored lowercase.
   */
  entry: string;
  /**
   * Your own note about why the rule exists.
   */
  note?: string;
};

export type EmailInboundRouteId = string;

/**
 * A routing rule that directs inbound mail on one of your domains into a mailbox, or drops it. Routes are tried in priority order, lowest number first. Each mailbox's own address always matches at priority 10 and your own routes take a priority from 11 to 1000, so delivery to an exact address always takes precedence.
 *
 */
export type InboundRoute = {
  /**
   * Inbound route ID.
   */
  readonly id: EmailInboundRouteId;
  /**
   * The domain the route applies to.
   */
  readonly domain: string;
  /**
   * How the route matches recipients. `address` matches one local part. `catch_all` matches every recipient on the domain that nothing else matched.
   */
  match_type: "address" | "catch_all";
  /**
   * The local part an `address` route matches. `null` for `catch_all` routes.
   */
  match_value: string | null;
  /**
   * What happens to matching mail. `deliver_to_mailbox` delivers it to `target_mailbox_id`. `drop` discards it silently, with nothing stored and no webhook fired.
   */
  action: "deliver_to_mailbox" | "drop";
  /**
   * The mailbox that receives matching mail. `null` for `drop` routes.
   */
  target_mailbox_id: MailboxId | null;
  /**
   * The order routes are tried in, lowest number first. Your own routes take a priority from 11 to 1000, and default to 100. A mailbox's own address always matches at priority 10.
   */
  priority: number;
  /**
   * Whether the route is evaluated. Disabled routes are kept but skipped.
   */
  enabled: boolean;
  /**
   * When the route was created.
   */
  readonly created_at: string;
  /**
   * When the route was last updated.
   */
  readonly updated_at: string;
};

export type InboundRouteList = {
  /**
   * Page of inbound routes in evaluation order, with the lowest priority number first.
   */
  data: Array<InboundRoute>;
} & ListEnvelope;

/**
 * Parameters for creating an inbound route.
 */
export type InboundRouteCreate = {
  /**
   * The domain the route applies to. It has to be one of your inbound-enabled custom domains.
   */
  domain: string;
  /**
   * How the route matches recipients. `address` matches one local part and requires `match_value`. `catch_all` matches every recipient on the domain that nothing else matched.
   */
  match_type: "address" | "catch_all";
  /**
   * The local part an `address` route matches. Required for `address` routes. Stored lowercase.
   */
  match_value?: string;
  /**
   * What happens to matching mail. `deliver_to_mailbox` delivers it to `target_mailbox_id` (required). `drop` discards it silently, with nothing stored and no webhook fired.
   */
  action: "deliver_to_mailbox" | "drop";
  /**
   * The mailbox that receives matching mail. Required for `deliver_to_mailbox` routes.
   */
  target_mailbox_id?: MailboxId;
  /**
   * The order routes are tried in, lowest number first. Your own routes take a priority from 11 to 1000. The mailbox's own address always matches at priority 10, so a route can never pre-empt exact-address delivery.
   */
  priority?: number;
  /**
   * Whether the route is evaluated.
   */
  enabled?: boolean;
};

/**
 * Fields to update on an inbound route. Omitted fields are unchanged. The domain is immutable.
 */
export type InboundRouteUpdate = {
  /**
   * How the route matches recipients.
   */
  match_type?: "address" | "catch_all";
  /**
   * The local part an `address` route matches. `null` for `catch_all` routes.
   */
  match_value?: string | null;
  /**
   * What happens to matching mail. `deliver_to_mailbox` delivers it to `target_mailbox_id` (required). `drop` discards it silently, with nothing stored and no webhook fired.
   */
  action?: "deliver_to_mailbox" | "drop";
  /**
   * The mailbox that receives matching mail. `null` for `drop` routes.
   */
  target_mailbox_id?: MailboxId | null;
  /**
   * The order routes are tried in, lowest number first. Your own routes take a priority from 11 to 1000. The mailbox's own address always matches at priority 10.
   */
  priority?: number;
  /**
   * Whether the route is evaluated.
   */
  enabled?: boolean;
};

export type ThreadId = string;

/**
 * Matched search fragments for a thread, one array per field the query matched, with the matched terms wrapped in `**`. A field is present only when the query matched it, so the keys that are present tell you which fields produced the hit. Returned only on thread search results.
 *
 */
export type EmailThreadHighlights = {
  /**
   * Matched fragments from the conversation's subject.
   */
  subject?: Array<string>;
  /**
   * Matched fragments from a message's body text.
   */
  text?: Array<string>;
};

/**
 * A conversation in a mailbox. It groups every message in both directions, the mail the mailbox received and the replies it sent, and it holds the conversation's read state, labels, and participant list. A message is retained until it is trashed or ages past the mailbox's retention tier. Only retained messages count toward the totals below.
 *
 */
export type EmailThread = {
  /**
   * Thread ID.
   */
  readonly id: ThreadId;
  /**
   * Mailbox this conversation belongs to.
   */
  readonly mailbox_id: MailboxId;
  /**
   * Channel this conversation lives on. Always `email`.
   */
  readonly channel: string;
  /**
   * Contact linked to this conversation, or null when none is linked.
   */
  contact_id: ContactId | null;
  /**
   * Subject of the conversation, taken from its first message. Null when that message had no subject.
   */
  readonly subject: string | null;
  /**
   * Addresses that appear on the retained messages in this conversation, including the mailbox's own address.
   */
  readonly participants: Array<string>;
  /**
   * Number of retained messages in this conversation, both directions.
   */
  readonly message_count: number;
  /**
   * Number of retained received messages that are still unread. Spam and blocked mail is not counted.
   */
  readonly unread_count: number;
  /**
   * When the most recent retained message in this conversation was received or sent.
   */
  readonly last_message_at: string;
  /**
   * Direction of the most recent message: `inbound` for a received message, `outbound` for a sent one.
   */
  readonly last_direction: "inbound" | "outbound";
  /**
   * Labels on this conversation. Exactly one system placement label is always present, set by the message that started the conversation:
   *
   * - `inbox`: The conversation is in the inbox.
   * - `archive`: The conversation was filed away and is done for now.
   * - `spam`: The conversation's opening message failed sender authentication.
   * - `blocked`: The conversation's opening message was rejected by the mailbox's receive policy or rules.
   *
   * Move a conversation by updating its labels. Add `spam` to file it as spam, add `archive` to clean it out of the inbox, and add `inbox`, or remove `spam`, `blocked`, or `archive`, to bring it back. An archived conversation returns to the inbox by itself when a new message arrives. Custom labels share the same list, and a conversation has at most 20 labels in total.
   *
   */
  labels: Array<string>;
  /**
   * When the thread was created.
   */
  readonly created_at: string;
  /**
   * When the thread last changed.
   */
  readonly updated_at: string;
  /**
   * Matched search fragments, keyed by the field that matched. Returned only by thread search. Omitted when listing threads.
   *
   */
  readonly highlights?: EmailThreadHighlights;
};

export type EmailThreadList = {
  data: Array<EmailThread>;
} & ListEnvelope;

/**
 * Label changes to apply. Labels in `add` are applied and labels in `remove` are taken off; other labels are left untouched. Adding a label that is already present, or removing one that is not, has no effect. System labels express state changes. On a conversation, adding `spam` files it as spam. Adding `archive` files it away without deleting it. Adding `inbox`, or removing `spam`, `blocked`, or `archive`, returns it to the inbox. Removing `unread` marks all retained received messages as read in one call. On a message, adding or removing `unread` flips read state. Adding or removing `trash` moves it to or out of the trash. The API rejects changes that contradict this model. A request cannot add more than one placement label. It cannot add `blocked`, because blocking a sender is a receive-rule decision. Removing `inbox` requires adding a destination. A conversation cannot add `trash` or `unread`; removing `unread` is the mark-all-read shortcut, and `trash` uses the `DELETE` verb. A message cannot use placement labels; move its conversation instead. A sent message cannot use `unread`. Custom labels are 1-64 characters with no commas, control characters, or leading or trailing whitespace. System label names and a small reserved set (`all`, `archived`, `deleted`, `draft`, `drafts`, `flagged`, `important`, `junk`, `muted`, `none`, `outbox`, `pinned`, `read`, `scheduled`, `snoozed`, `starred`) cannot be used as custom labels, in any casing. A conversation or message has at most 20 labels, system labels included.
 *
 */
export type EmailLabelsUpdate = {
  /**
   * Labels to apply.
   */
  add?: Array<string>;
  /**
   * Labels to take off.
   */
  remove?: Array<string>;
};

/**
 * Changes to apply to a thread. Omitted fields are left unchanged.
 */
export type EmailThreadUpdateRequest = {
  labels?: EmailLabelsUpdate;
  /**
   * Contact to link this conversation to, or null to unlink the current contact.
   */
  contact_id?: ContactId | null;
};

/**
 * One recipient's terminal delivery outcome on a sent conversation message, recorded once the outcome becomes known.
 *
 */
export type EmailThreadMessageRecipient = {
  /**
   * Recipient address.
   */
  readonly address: string;
  /**
   * Terminal outcome: `delivered`, or `failed` (bounce or provider rejection).
   */
  readonly status: "delivered" | "failed";
};

/**
 * Attachment metadata on a conversation message. The metadata stays readable for the mailbox's retention tier. The attachment bytes are downloadable for 30 days after the message occurred.
 *
 */
export type EmailThreadMessageAttachment = {
  /**
   * Attachment ID, used to download the attachment bytes.
   */
  readonly id: string;
  /**
   * Original filename, or null when the attachment had none.
   */
  readonly filename: string | null;
  /**
   * MIME content type, or null when it could not be determined.
   */
  readonly content_type: string | null;
  /**
   * Attachment size in bytes.
   */
  readonly size: number;
};

/**
 * Link to the message's entry in the received-message or sent-message log, which has delivery analytics such as per-recipient events. Log entries expire 30 days after the message occurred.
 *
 */
export type EmailThreadMessageSource = {
  /**
   * API path of the log entry for this message.
   */
  readonly resource: string;
  /**
   * When the log entry (and the message's original rendered source) expires.
   */
  readonly available_until: string;
};

/**
 * A message in a mailbox conversation, either direction. Message metadata and extracted text stay readable for the mailbox's retention tier. The original rendered source (HTML body, raw MIME, attachment bytes) is available through the body, raw, and attachment endpoints for 30 days after the message occurred.
 *
 */
export type EmailThreadMessage = {
  /**
   * Message ID. Received messages have a `rem_` ID, sent messages an `em_` ID: the same IDs used by the received-message and sent-message logs.
   *
   */
  readonly id: string;
  /**
   * Which way the message went. `inbound` means you received it, `outbound` means you sent it.
   */
  readonly direction: "inbound" | "outbound";
  /**
   * Channel this message lives on. Always `email`.
   */
  readonly channel: string;
  /**
   * Conversation this message belongs to.
   */
  readonly thread_id: ThreadId;
  /**
   * Sender address.
   */
  readonly from: string;
  /**
   * Recipient addresses on the To line.
   */
  readonly to: Array<string>;
  /**
   * Recipient addresses on the Cc line. Empty when the message had none.
   */
  readonly cc: Array<string>;
  /**
   * Address the message was actually delivered to, when it differs from the mailbox address (for example mail routed in from another address). Null for sent messages and for mail addressed directly to the mailbox.
   *
   */
  readonly delivered_to: string | null;
  /**
   * Message subject. Null when the message had no subject.
   */
  readonly subject: string | null;
  /**
   * Short plain-text preview of the message body.
   */
  readonly preview: string | null;
  /**
   * Plain-text content of the message with quoted history stripped. Readable for the mailbox's full retention tier, in both directions. Always present when fetching a single message. On list endpoints it is included only when the request sets `include=extracted_text`. Null when no text could be extracted.
   *
   */
  readonly extracted_text?: string | null;
  /**
   * Labels on this message. A received message always has exactly one placement label:
   *
   * - `inbox`: Accepted mail.
   * - `archive`: The message's conversation was filed away.
   * - `spam`: The message failed sender authentication.
   * - `blocked`: The message was rejected by the mailbox's receive policy or rules.
   *
   * A received message also has `unread` until it is read. `trash` marks a message in the trash, in either direction. Custom labels share the same list, and a message has at most 20 labels in total.
   *
   */
  labels: Array<string>;
  /**
   * Aggregate delivery status of a sent message:
   *
   * - `accepted`: Accepted for sending.
   * - `sent`: Handed off to the provider.
   * - `delivered`: All attempted recipients delivered.
   * - `failed`: Terminal failure.
   *
   * Null for received messages.
   *
   */
  readonly status: string | null;
  /**
   * Terminal per-recipient delivery outcomes of a sent message, filled in as each one becomes known and kept for the mailbox's full retention tier. Null for received messages and before any recipient reaches a terminal state. Per-recipient event detail lives on the sent-message log (`source`) for 30 days.
   *
   */
  readonly recipients: Array<EmailThreadMessageRecipient> | null;
  /**
   * Whether the sender of a received message was authenticated.
   *
   * - `pass`: the sender's identity was verified.
   * - `fail`: it was checked and did not verify.
   * - `unknown`: no verdict could be determined, so do not treat the
   * sender as verified.
   *
   * Null for sent messages. This field is readable for the mailbox's full
   * retention tier, so the verdict is still available after the 30-day
   * received-message log has expired.
   *
   */
  readonly authentication: "pass" | "fail" | "unknown" | null;
  /**
   * Whether SPF passed for the sender of a received message. Null for sent messages and when no verdict is available. This field is kept for the mailbox's retention tier.
   *
   */
  readonly spf_pass: boolean | null;
  /**
   * Whether DKIM passed for the sender of a received message. Null for sent messages and when no verdict is available. This field is kept for the mailbox's retention tier.
   *
   */
  readonly dkim_pass: boolean | null;
  /**
   * Whether DMARC passed for the sender of a received message. Null for sent messages and when no verdict is available. This field is kept for the mailbox's retention tier.
   *
   */
  readonly dmarc_pass: boolean | null;
  /**
   * Scheduled permanent-deletion time. This is the end of the mailbox's retention tier, moved to no more than 30 days in the future while the message is in the trash. Restore a trashed message before then with `PATCH {"labels": {"remove": ["trash"]}}`.
   *
   */
  readonly purge_at: string;
  /**
   * Number of attachments on the message.
   */
  readonly attachment_count: number;
  /**
   * Attachment metadata (filename, content type, size). Stays readable for the mailbox's retention tier even after the attachment bytes themselves have expired.
   *
   */
  readonly attachment_manifest: Array<EmailThreadMessageAttachment>;
  /**
   * RFC 5322 References header entries used to thread the conversation.
   */
  readonly reference_ids: Array<string>;
  /**
   * Contact linked to this message, or null when none is linked.
   */
  contact_id: ContactId | null;
  readonly source: EmailThreadMessageSource;
  /**
   * When the message was received or accepted for sending.
   */
  readonly occurred_at: string;
};

export type EmailThreadMessageList = {
  data: Array<EmailThreadMessage>;
} & ListEnvelope;

/**
 * Changes to apply to a conversation message. Omitted fields are left unchanged.
 */
export type EmailThreadMessageUpdateRequest = {
  labels?: EmailLabelsUpdate;
  /**
   * Contact to link this message to, or null to unlink the current contact.
   */
  contact_id?: ContactId | null;
};

/**
 * The original rendered body of a conversation message. Available for 30 days after the message occurred. After that, the endpoint returns `410 Gone`, but the message's extracted text stays readable on the message itself.
 *
 */
export type EmailThreadMessageBody = {
  /**
   * The HTML body of the message, or null when the message had no HTML part.
   */
  html: string | null;
  /**
   * The plain-text body of the message, or null when the message had no text part.
   */
  text: string | null;
};

/**
 * The attachments on a conversation message.
 */
export type EmailThreadMessageAttachmentList = {
  data: Array<EmailThreadMessageAttachment>;
};

/**
 * A reply to a conversation message. Recipients are derived from the message being replied to: its Reply-To address when present, otherwise its From address. Set `reply_all` to also include the original To and Cc recipients (minus the mailbox's own address). The subject and threading headers are set automatically. At least one of `html` or `text` must be provided.
 *
 */
export type EmailThreadMessageReplyRequest = {
  /**
   * HTML body of the reply. At least one of html or text must be provided.
   */
  html?: string;
  /**
   * Plain-text body of the reply. At least one of html or text must be provided.
   */
  text?: string;
  /**
   * Also send the reply to the original To and Cc recipients, minus the mailbox's own address.
   */
  reply_all?: boolean;
  /**
   * Structured `{name, value}` labels for filtering and analytics on the sent-message log. Cap: 20 tags per send.
   *
   */
  tags?: Array<Tag>;
  /**
   * Arbitrary JSON object stored on the send and echoed in webhook payloads. Cap: 2 KB serialized.
   *
   */
  metadata?: {
    [key: string]: unknown;
  };
  category?: EmailMessageCategory;
  /**
   * File attachments to include with the reply. The send is rejected when the estimated generated message size exceeds 20 MB (bodies plus all attachments after base64 encoding). Keep total raw attachment content at or below 15 MB for reliable headroom. Attachment metadata stays on the message's `attachment_manifest`, and the bytes are downloadable for 30 days.
   *
   */
  attachments?: Array<EmailAttachment>;
};

/**
 * A new message sent from a mailbox, starting a new conversation. Mirrors the plain send request without `from`, because the mailbox is who the message comes from, and without `scheduled_at`, because a mailbox sends immediately. We set the RFC 5322 Message-ID so replies thread back into this conversation. At least one of `html` or `text` must be provided.
 *
 */
export type EmailMailboxComposeRequest = {
  /**
   * Primary recipients. Each entry is a plain email string, an RFC 5322 mailbox string (`Jane <jane@acme.com>`), or an object with an optional display name.
   */
  to: Array<EmailAddressInput>;
  /**
   * CC recipients. Each entry is a plain email string, an RFC 5322 mailbox string (`Jane <jane@acme.com>`), or an object with an optional display name.
   */
  cc?: Array<EmailAddressInput>;
  /**
   * BCC recipients. Each entry is a plain email string, an RFC 5322 mailbox string (`Jane <jane@acme.com>`), or an object with an optional display name.
   */
  bcc?: Array<EmailAddressInput>;
  /**
   * Message subject line.
   */
  subject: string;
  /**
   * HTML body. At least one of html or text must be provided.
   */
  html?: string;
  /**
   * Plain-text body. At least one of html or text must be provided.
   */
  text?: string;
  /**
   * Reply-To addresses. When omitted, the mailbox's `default_reply_to` applies (replies then come back to the mailbox itself).
   *
   */
  reply_to?: Array<EmailAddressInput>;
  /**
   * File attachments. The send is rejected when the estimated generated message size exceeds 20 MB (bodies plus all attachments after base64 encoding). Keep total raw attachment content at or below 15 MB for reliable headroom. Attachment metadata stays on the message's `attachment_manifest`, and the bytes are downloadable for 30 days.
   *
   */
  attachments?: Array<EmailAttachment>;
  /**
   * Structured `{name, value}` labels for filtering and analytics on the sent-message log. Cap: 20 tags per send.
   *
   */
  tags?: Array<Tag>;
  /**
   * Arbitrary JSON object stored on the send and echoed in webhook payloads. Cap: 2 KB serialized.
   *
   */
  metadata?: {
    [key: string]: unknown;
  };
  category?: EmailMessageCategory;
};

/**
 * One label available in a mailbox.
 */
export type EmailMailboxLabel = {
  /**
   * The label name, as it appears on conversations and messages.
   */
  readonly name: string;
  /**
   * `system` labels are the built-in placements a message can be in:
   *
   * - Inbox.
   * - Archive.
   * - Spam.
   * - Blocked.
   * - Sent.
   * - Trash.
   * - Unread.
   *
   * `custom` labels are the workspace's own tags.
   */
  readonly type: "system" | "custom";
};

/**
 * The labels available in a mailbox.
 */
export type EmailMailboxLabelList = {
  data: Array<EmailMailboxLabel>;
};

export type EmailSmtpConfig = {
  /**
   * ID of the API key this config applies to, the same key your SMTP client authenticates with. One config exists per key.
   *
   */
  readonly api_key_id: ApiKeyId;
  /**
   * ID of the IP pool that SMTP sends with this key use, or `ipp_shared` for the shared pool. `null` when this key uses your organization's default pool.
   *
   */
  ip_pool_id?: string | null;
  /**
   * Content classification applied to messages submitted over SMTP with
   * this key. Controls suppression policy:
   *
   * - `marketing`: Blocks on all suppression reasons.
   * - `transactional`: Allows delivery through complaint and unsubscribe suppressions.
   *
   */
  category: "marketing" | "transactional";
  /**
   * Structured `{name, value}` labels applied to every message submitted over SMTP with this key, the same tags used by the email sending API. Use tags to filter and break down your email statistics.
   *
   */
  tags: Array<Tag>;
  /**
   * Whether open events are tracked for messages submitted over SMTP with this key.
   */
  track_opens: boolean;
  /**
   * Whether click events are tracked for messages submitted over SMTP with this key.
   */
  track_clicks: boolean;
} & Timestamps;

export type EmailSmtpConfigList = {
  /**
   * Page of stored SMTP configs, newest first by default.
   */
  data: Array<EmailSmtpConfig>;
} & ListEnvelopeWithTotal;

/**
 * Desired changes to the SMTP config for the key. A field you omit is left unchanged. If no config exists yet for this key, omitted fields take their documented defaults instead.
 *
 */
export type EmailSmtpConfigUpdate = {
  /**
   * ID of the IP pool to send from (`ipp_` prefix), or `ipp_shared` to route through the shared pool explicitly. Send `null` to reset to your organization's default pool, or omit to leave unchanged. An unknown pool, or a pool with no dedicated IPs available to send from, is rejected with a `422`.
   *
   */
  ip_pool_id?: string | null;
  /**
   * Content classification, independent of which endpoint messages are
   * submitted through. Controls suppression policy:
   *
   * - `marketing`: Blocks on all suppression reasons.
   * - `transactional`: Allows delivery through complaint and unsubscribe suppressions.
   *
   * Omit to leave unchanged.
   *
   */
  category?: "marketing" | "transactional";
  /**
   * Structured `{name, value}` labels applied to every message submitted over SMTP with this key. Send an empty array to clear all tags, or omit to leave unchanged.
   *
   */
  tags?: Array<Tag>;
  /**
   * Whether to track open events for messages submitted over SMTP with this key. Omit to leave unchanged.
   */
  track_opens?: boolean;
  /**
   * Whether to track click events for messages submitted over SMTP with this key. Omit to leave unchanged.
   */
  track_clicks?: boolean;
};

export type WebhookEndpointId = string;

